insert into public.shabads (order_index, title, lines, deadline_days) values (0, 'ਵਡਹੰਸੁਮਹਲਾ੪॥', '[{"gurmukhi":"ਮੇਰਾਹਰਿਪ੍ਰਭੁਸੁੰਦਰੁਮੈਸਾਰਨਜਾਣੀ॥","meaning":"ਮੇਰਾ ਹਰੀ ਪ੍ਰਭੂ ਸੋਹਣਾ ਹੈ (ਪਰ) ਮੈਂ (ਉਸ ਦੇ ਸੁਹਣੱਪ ਦੀ) ਕਦਰ ਨਾਹ ਜਾਤੀ,"},{"gurmukhi":"ਹਉਹਰਿਪ੍ਰਭਛੋਡਿਦੂਜੈਲੋਭਾਣੀ॥੧॥","meaning":"(ਤੇ) ਮੈਂ ਉਸ ਹਰੀ ਨੂੰ ਉਸ ਪ੍ਰਭੂ ਨੂੰ ਛੱਡ ਕੇ ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਹੀ ਫਸੀ ਰਹੀ ।੧।"},{"gurmukhi":"ਹਉਕਿਉਕਰਿਪਿਰਕਉਮਿਲਉਇਆਣੀ॥","meaning":"ਮੈਂ ਮੂਰਖ ਹਾਂ, ਮੈਂ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਕਿਵੇਂ ਮਿਲ ਸਕਦੀ ਹਾਂ?"},{"gurmukhi":"ਜੋਪਿਰਭਾਵੈਸਾਸੋਹਾਗਣਿਸਾਈਪਿਰਕਉਮਿਲੈਸਿਆਣੀ॥੧॥ਰਹਾਉ॥","meaning":"ਜੇਹੜੀ (ਜੀਵ-ਇਸਤ੍ਰੀ) ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਪਸੰਦ ਆਉਂਦੀ ਹੈ, ਉਹ ਭਾਗਾਂ ਵਾਲੀ ਹੈ, ਉਹੀ ਅਕਲ ਵਾਲੀ ਹੈ, ਉਹੀ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਮਿਲ ਸਕਦੀ ਹੈ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਮੈਵਿਚਿਦੋਸਹਉਕਿਉਕਰਿਪਿਰੁਪਾਵਾ॥","meaning":"ਮੇਰੇ ਅੰਦਰ (ਅਨੇਕਾਂ) ਐਬ ਹਨ (ਜਿਨ੍ਹਾਂ ਕਰ ਕੇ) ਮੈਂ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਮਿਲ ਨਹੀਂ ਸਕਦੀ ।"},{"gurmukhi":"ਤੇਰੇਅਨੇਕਪਿਆਰੇਹਉਪਿਰਚਿਤਿਨਆਵਾ॥੨॥","meaning":"ਹੇ ਪ੍ਰਭੂ-ਪਤੀ! ਤੇਰੇ ਨਾਲ ਪਿਆਰ ਕਰਨ ਵਾਲੇ ਅਨੇਕਾਂ ਹੀ ਹਨ, ਮੈਂ ਤੇਰੇ ਚਿੱਤ ਵਿਚ ਨਹੀਂ ਆ ਸਕਦੀ ।੨।"},{"gurmukhi":"ਜਿਨਿਪਿਰੁਰਾਵਿਆਸਾਭਲੀਸੁਹਾਗਣਿ॥","meaning":"ਜਿਸ ਜੀਵ-ਇਸਤ੍ਰੀ ਨੇ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਹਿਰਦੇ ਵਿਚ ਵਸਾ ਲਿਆ, ਉਹ ਨੇਕ ਹੈ, ਉਹ ਭਾਗਾਂ ਵਾਲੀ ਹੈ, ਉਸ ਸੁਹਾਗਣ ਵਾਲੇ ਗੁਣ ਮੇਰੇ ਅੰਦਰ ਨਹੀਂ ਹਨ ।"},{"gurmukhi":"ਸੇਮੈਗੁਣਨਾਹੀਹਉਕਿਆਕਰੀਦੁਹਾਗਣਿ॥੩॥","meaning":"ਮੈਂ ਛੁੱਟੜ (ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਮਿਲਣ ਲਈ) ਕੀਹ ਕਰ ਸਕਦੀ ਹਾਂ? ।੩।"},{"gurmukhi":"ਨਿਤਸੁਹਾਗਣਿਸਦਾਪਿਰੁਰਾਵੈ॥","meaning":"ਜੇਹੜੀ ਜੀਵ-ਇਸਤ੍ਰੀ ਸਦਾ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਹਿਰਦੇ ਵਿਚ ਵਸਾਈ ਰੱਖਦੀ ਹੈ ਉਹ ਸਦਾ ਭਾਗਾਂ ਵਾਲੀ ਹੈ ।"},{"gurmukhi":"ਮੈਕਰਮਹੀਣਕਬਹੀਗਲਿਲਾਵੈ॥੪॥","meaning":"ਮੇਰੇ ਵਰਗੀ ਮੰਦ-ਭਾਗਣ ਨੂੰ ਉਹ ਕਦੇ (ਕਿਸਮਤ ਨਾਲ) ਹੀ ਆਪਣੇ ਗਲ ਨਾਲ ਲਾਂਦਾ ਹੈ ।੪।"},{"gurmukhi":"ਤੂਪਿਰੁਗੁਣਵੰਤਾਹਉਅਉਗੁਣਿਆਰਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ-ਪਤੀ! ਤੂੰ ਗੁਣਾਂ ਨਾਲ ਭਰਪੂਰ ਹੈਂ, ਪਰ ਮੈਂ ਅਉਗਣਾਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਹਾਂ ।"},{"gurmukhi":"ਮੈਨਿਰਗੁਣਬਖਸਿਨਾਨਕੁਵੇਚਾਰਾ॥੫॥੨॥","meaning":"(ਤੇਰੇ ਦਰ ਤੇ ਹੀ ਅਰਦਾਸ ਹੈ—) ਮੈਨੂੰ ਗੁਣ-ਹੀਨ ਨਿਮਾਣੇ ਨਾਨਕ ਨੂੰ ਬਖ਼ਸ਼ ਲੈ (ਤੇ, ਆਪਣੇ ਨਾਮ ਦੀ ਦਾਤਿ ਦੇਹ ।੫।੨।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (1, 'ਇਕਬਿਨਉਕਰਉਜੀਉਸੁਣਿਕੰਤਪਿਆਰੇ॥', '[{"gurmukhi":"","meaning":"ਹੇ ਪਿਆਰੇ ਕੰਤ ਜੀਉ! ਸੁਣ, ਮੈਂ ਇਕ ਬੇਨਤੀ ਕਰਦੀ ਹਾਂ ।"},{"gurmukhi":"ਮੇਰਾਮਨੁਤਨੁਮੋਹਿਲੀਆਜੀਉਦੇਖਿਚਲਤਤੁਮਾਰੇ॥","meaning":"ਤੇਰੇ ਕੌਤਕ-ਤਮਾਸ਼ੇ ਵੇਖ ਵੇਖ ਕੇ ਮੈਂ ਠੱਗੀ ਗਈ ਹਾਂ । (ਤੇਰੇ ਕੌਤਕ-ਤਮਾਸ਼ਿਆਂ ਨੇ) ਮੇਰਾ ਮਨ ਮੋਹ ਲਿਆ ਹੈ ਮੇਰਾ ਤਨ (ਹਰੇਕ ਇੰਦ੍ਰਾ) ਮੋਹ ਲਿਆ ਹੈ ।"},{"gurmukhi":"ਚਲਤਾਤੁਮਾਰੇਦੇਖਿਮੋਹੀਉਦਾਸਧਨਕਿਉਧੀਰਏ॥","meaning":"(ਪਰ ਹੁਣ ਇਹ) ਜੀਵ-ਇਸਤ੍ਰੀ (ਇਹਨਾਂ ਕੌਤਕ-ਤਮਾਸ਼ਿਆਂ ਤੋਂ) ਉਦਾਸ ਹੋ ਗਈ ਹੈ, (ਤੇਰੇ ਮਿਲਾਪ ਤੋਂ ਬਿਨਾ ਇਸ ਨੂੰ) ਧੀਰਜ ਨਹੀਂ ਆਉਂਦੀ ।"},{"gurmukhi":"ਗੁਣਵੰਤਨਾਹਦਇਆਲੁਬਾਲਾਸਰਬਗੁਣਭਰਪੂਰਏ॥","meaning":"ਹੇ ਸਭ ਗੁਣਾਂ ਦੇ ਮਾਲਕ ਖਸਮ! ਤੂੰ ਦਇਆ ਦਾ ਘਰ ਹੈਂ, ਤੂੰ ਸਦਾ-ਜਵਾਨ ਹੈਂ, ਤੂੰ ਸਾਰੇ ਗੁਣਾਂ ਨਾਲ ਭਰਪੂਰ ਹੈਂ ।"},{"gurmukhi":"ਪਿਰਦੋਸੁਨਾਹੀਸੁਖਹਦਾਤੇਹਉਵਿਛੁੜੀਬੁਰਿਆਰੇ॥","meaning":"ਹੇ ਸਾਰੇ ਸੁਖਾਂ ਦੇ ਦਾਤੇ ਪਤੀ! (ਤੇਰੇ ਵਿਚ ਕੋਈ) ਦੋਸ ਨਹੀਂ, ਮੈਂ ਮੰਦ-ਕਰਮਣ ਆਪ ਹੀ ਤੈਥੋਂ ਵਿੱਛੁੜੀ ਹੋਈ ਹਾਂ ।"},{"gurmukhi":"ਬਿਨਵੰਤਿਨਾਨਕਦਇਆਧਾਰਹੁਘਰਿਆਵਹੁਨਾਹਪਿਆਰੇ॥੨॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਹੇ ਪਿਆਰੇ ਪਤੀ! (ਇਹ ਜੀਵ-ਇਸਤ੍ਰੀ) ਬੇਨਤੀ ਕਰਦੀ ਹੈ, ਤੂੰ ਮਿਹਰ ਕਰ ਤੇ ਇਸ ਦੇ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਆ ਵੱਸ ।੨।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (2, 'ਗਉੜੀਪੂਰਬੀਰਵਿਦਾਸਜੀਉ', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਕੂਪੁਭਰਿਓਜੈਸੇਦਾਦਿਰਾਕਛੁਦੇਸੁਬਿਦੇਸੁਨਬੂਝ॥","meaning":"ਜਿਵੇਂ (ਕੋਈ) ਖੂਹ ਡੱਡੂਆਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਹੋਵੇ, (ਉਹਨਾਂ ਡੱਡੂਆਂ ਨੂੰ) ਕੋਈ ਵਾਕਫ਼ੀ ਨਹੀਂ ਹੁੰਦੀ (ਕਿ ਇਸ ਖੂਹ ਤੋਂ ਬਾਹਰ ਕੋਈ ਹੋਰ) ਦੇਸ ਪਰਦੇਸ ਭੀ ਹੈ;"},{"gurmukhi":"ਐਸੇਮੇਰਾਮਨੁਬਿਖਿਆਬਿਮੋਹਿਆਕਛੁਆਰਾਪਾਰੁਨਸੂਝ॥੧॥","meaning":"ਤਿਵੇਂ ਮੇਰਾ ਮਨ ਮਾਇਆ (ਦੇ ਖੂਹ) ਵਿਚ ਇਤਨਾ ਚੰਗੀ ਤਰ੍ਹਾਂ ਫਸਿਆ ਹੋਇਆ ਹੈ ਕਿ ਇਸ ਨੂੰ (ਮਾਇਆ ਦੇ ਖੂਹ ਵਿਚੋਂ ਨਿਕਲਣ ਲਈ) ਕੋਈ ਉਰਲਾ ਪਾਰਲਾ ਬੰਨਾ ਨਹੀਂ ਸੁੱਝਦਾ ।੧।"},{"gurmukhi":"ਸਗਲਭਵਨਕੇਨਾਇਕਾਇਕੁਛਿਨੁਦਰਸੁਦਿਖਾਇਜੀ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਸਾਰੇ ਭਵਨਾਂ ਦੇ ਸਰਦਾਰ! ਮੈਨੂੰ ਇਕ ਖਿਨ ਭਰ ਲਈ (ਹੀ) ਦੀਦਾਰ ਦੇਹ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਮਲਿਨਭਈਮਤਿਮਾਧਵਾਤੇਰੀਗਤਿਲਖੀਨਜਾਇ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੇਰੀ ਅਕਲ (ਵਿਕਾਰਾਂ ਨਾਲ) ਮੈਲੀ ਹੋਈ ਪਈ ਹੈ, (ਇਸ ਵਾਸਤੇ) ਮੈਨੂੰ ਤੇਰੀ ਗਤੀ ਦੀ ਪਛਾਣ ਨਹੀਂ ਆਉਂਦੀ (ਭਾਵ, ਮੈਨੂੰ ਸਮਝ ਨਹੀਂ ਪੈਂਦੀ ਕਿ ਤੂੰ ਕਿਹੋ ਜਿਹਾ ਹੈਂ) ।"},{"gurmukhi":"ਕਰਹੁਕ੍ਰਿਪਾਭ੍ਰਮੁਚੂਕਈਮੈਸੁਮਤਿਦੇਹੁਸਮਝਾਇ॥੨॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੇਹਰ ਕਰ, ਮੈਨੂੰ ਸੁਚੱਜੀ ਮੱਤ ਸਮਝਾ, (ਤਾਕਿ) ਮੇਰੀ ਭਟਕਣਾ ਮੁੱਕ ਜਾਏ ।੨।"},{"gurmukhi":"ਜੋਗੀਸਰਪਾਵਹਿਨਹੀਤੁਅਗੁਣਕਥਨੁਅਪਾਰ॥","meaning":"(ਹੇ ਪ੍ਰਭੂ!) ਵੱਡੇ ਵੱਡੇ ਜੋਗੀ (ਭੀ) ਤੇਰੇ ਬੇਅੰਤ ਗੁਣਾਂ ਦਾ ਅੰਤ ਨਹੀਂ ਪਾ ਸਕਦੇ,"},{"gurmukhi":"ਪ੍ਰੇਮਭਗਤਿਕੈਕਾਰਣੈਕਹੁਰਵਿਦਾਸਚਮਾਰ॥੩॥੧॥","meaning":"(ਪਰ) ਹੇ ਰਵਿਦਾਸ ਚਮਾਰ! ਤੂੰ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰ, ਤਾਕਿ ਤੈਨੂੰ ਪੇ੍ਰੇਮ ਤੇ ਭਗਤੀ ਦੀ ਦਾਤਿ ਮਿਲ ਸਕੇ ।੩।੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (3, 'ਸਲੋਕਮਹਲਾ੯॥', '[{"gurmukhi":"ਗੁਨਗੋਬਿੰਦਗਾਇਓਨਹੀਜਨਮੁਅਕਾਰਥਕੀਨੁ॥","meaning":"ਹੇ ਭਾਈ! ਜੇ ਤੂੰ ਪਰਮਾਤਮਾ ਦੇ ਗੁਣ ਕਦੇ ਨਹੀਂ ਗਾਏ, ਤਾਂ ਤੂੰ ਆਪਣਾ ਮਨੁੱਖਾ ਜਨਮ ਨਿਕੰਮਾ ਕਰ ਲਿਆ ।"},{"gurmukhi":"ਕਹੁਨਾਨਕਹਰਿਭਜੁਮਨਾਜਿਹਬਿਧਿਜਲਕਉਮੀਨੁ॥੧॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਹੇ ਮਨ! ਪਰਮਾਤਮਾ ਦਾ ਭਜਨ ਕਰਿਆ ਕਰ (ਤੇ, ਉਸ ਨੂੰ ਇਉਂ ਜ਼ਿੰਦਗੀ ਦਾ ਆਸਰਾ ਬਣਾ) ਜਿਵੇਂ ਪਾਣੀ ਨੂੰ ਮੱਛੀ (ਆਪਣੀ ਜਿੰਦ ਦਾ ਆਸਰਾ ਬਣਾਈ ਰੱਖਦੀ ਹੈ) ।੧।"},{"gurmukhi":"ਬਿਖਿਅਨਸਿਉਕਾਹੇਰਚਿਓਨਿਮਖਨਹੋਹਿਉਦਾਸੁ॥","meaning":"ਹੇ ਭਾਈ! ਤੂੰ ਵਿਸ਼ਿਆਂ ਨਾਲ ਕਿਉਂ (ਇਤਨਾ) ਮਸਤ ਰਹਿੰਦਾ ਹੈਂ? ਤੂੰ ਅੱਖ ਝਮਕਣ ਜਿਤਨੇ ਸਮੇ ਲਈ ਭੀ ਵਿਸ਼ਿਆਂ ਤੋਂ ਚਿੱਤ ਨਹੀਂ ਹਟਾਂਦਾ ।"},{"gurmukhi":"ਕਹੁਨਾਨਕਭਜੁਹਰਿਮਨਾਪਰੈਨਜਮਕੀਫਾਸ॥੨॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਹੇ ਮਨ! ਪਰਮਾਤਮਾ ਦਾ ਭਜਨ ਕਰਿਆ ਕਰ । (ਭਜਨ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਜਮਾਂ ਦੀ ਫਾਹੀ (ਗਲ ਵਿਚ) ਨਹੀਂ ਪੈਂਦੀ ।੨।"},{"gurmukhi":"ਤਰਨਾਪੋਇਉਹੀਗਇਓਲੀਓਜਰਾਤਨੁਜੀਤਿ॥","meaning":"ਹੇ ਭਾਈ! (ਤੇਰੀ) ਜੁਆਨੀ ਬੇ-ਪਰਵਾਹੀ ਵਿਚ ਹੀ ਲੰਘ ਗਈ, (ਹੁਣ) ਬੁਢੇਪੇ ਨੇ ਤੇਰੇ ਸਰੀਰ ਨੂੰ ਜਿੱਤ ਲਿਆ ਹੈ ।"},{"gurmukhi":"ਕਹੁਨਾਨਕਭਜੁਹਰਿਮਨਾਅਉਧਜਾਤੁਹੈਬੀਤਿ॥੩॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਹੇ ਮਨ! ਪਰਮਾਤਮਾ ਦਾ ਭਜਨ ਕਰਿਆ ਕਰ । ਉਮਰ ਲੰਘਦੀ ਜਾ ਰਹੀ ਹੈ ।੩।"},{"gurmukhi":"ਬਿਰਧਿਭਇਓਸੂਝੈਨਹੀਕਾਲੁਪਹੂਚਿਓਆਨਿ॥","meaning":"ਆਖ—ਹੇ ਝੱਲੇ ਮਨੁੱਖ! ਤੂੰ ਕਿਉਂ ਪਰਮਾਤਮਾ ਦਾ ਭਜਨ ਨਹੀਂ ਕਰਦਾ? (ਵੇਖ, ਤੂੰ ਹੁਣ) ਬੁੱਢਾ ਹੋ ਗਿਆ ਹੈ"},{"gurmukhi":"ਕਹੁਨਾਨਕਨਰਬਾਵਰੇਕਿਉਨਭਜੈਭਗਵਾਨੁ॥੪॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ (ਪਰ ਤੈਨੂੰ ਅਜੇ ਭੀ ਇਹ) ਸਮਝ ਨਹੀਂ ਆ ਰਹੀ ਕਿ ਮੌਤ (ਸਿਰ ਤੇ) ਆ ਪਹੁੰਚੀ ਹੈ ।੪।"},{"gurmukhi":"ਧਨੁਦਾਰਾਸੰਪਤਿਸਗਲਜਿਨਿਅਪੁਨੀਕਰਿਮਾਨਿ॥","meaning":"(ਆਖ—ਹੇ ਭਾਈ!) ਧਨ, ਇਸਤ੍ਰੀ, ਸਾਰੀ ਜਾਇਦਾਦ—(ਇਸ ਨੂੰ) ਆਪਣੀ ਕਰ ਕੇ ਨਾਹ ਮੰਨ ।"},{"gurmukhi":"ਇਨਮੈਕਛੁਸੰਗੀਨਹੀਨਾਨਕਸਾਚੀਜਾਨਿ॥੫॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—ਹੇ ਭਾਈ!) ਇਹ ਗੱਲ ਸੱਚੀ ਸਮਝ ਕਿ ਇਹਨਾਂ ਸਾਰਿਆਂ ਵਿਚੋਂ ਕੋਈ ਇੱਕ ਭੀ ਤੇਰਾ ਸਾਥੀ ਨਹੀਂ ਬਣ ਸਕਦਾ ।੫।"},{"gurmukhi":"ਪਤਿਤਉਧਾਰਨਭੈਹਰਨਹਰਿਅਨਾਥਕੇਨਾਥ॥","meaning":"ਹੇ ਭਾਈ! ਪ੍ਰਭੂ ਜੀ ਵਿਕਾਰੀਆਂ ਨੂੰ ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਾਣ ਵਾਲੇ ਹਨ, ਸਾਰੇ ਡਰ ਦੂਰ ਕਰਨ ਵਾਲੇ ਹਨ, ਅਤੇ ਨਿਖਸਮਿਆਂ ਦੇ ਖਸਮ ਹਨ ।"},{"gurmukhi":"ਕਹੁਨਾਨਕਤਿਹਜਾਨੀਐਸਦਾਬਸਤੁਤੁਮਸਾਥਿ॥੬॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—(ਹੇ ਭਾਈ!) ਉਸ (ਪ੍ਰਭੂ) ਨੂੰ (ਇਉਂ) ਸਮਝਣਾ ਚਾਹੀਦਾ ਹੈ ਕਿ ਉਹ ਸਦਾ ਤੇਰੇ ਨਾਲ ਵੱਸਦਾ ਹੈ ।੬।"},{"gurmukhi":"ਤਨੁਧਨੁਜਿਹਤੋਕਉਦੀਓਤਾਂਸਿਉਨੇਹੁਨਕੀਨ॥","meaning":"ਹੇ ਝੱਲੇ ਮਨੁੱਖ! ਜਿਸ (ਪਰਮਾਤਮਾ) ਨੇ ਤੈਨੂੰ ਸਰੀਰ ਦਿੱਤਾ, ਧਨ ਦਿੱਤਾ, ਤੂੰ ਉਸ ਨਾਲ ਪਿਆਰ ਨਾਹ ਪਾਇਆ ।"},{"gurmukhi":"ਕਹੁਨਾਨਕਨਰਬਾਵਰੇਅਬਕਿਉਡੋਲਤਦੀਨ॥੭॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ— ਫਿਰ ਹੁਣ ਆਤੁਰ ਹੋ ਕੇ ਘਬਰਾਇਆ ਕਿਉਂ ਫਿਰਦਾ ਹੈਂ (ਭਾਵ, ਉਸ ਹਰੀ ਨੂੰ ਯਾਦ ਕਰਨ ਤੋਂ ਬਿਨਾ ਘਬਰਾਣਾ ਤਾਂ ਹੋਇਆ ਹੀ) ।੭।"},{"gurmukhi":"ਤਨੁਧਨੁਸੰਪੈਸੁਖਦੀਓਅਰੁਜਿਹਨੀਕੇਧਾਮ॥","meaning":"ਜਿਸ (ਪਰਮਾਤਮਾ) ਨੇ ਸਰੀਰ ਦਿੱਤਾ, ਧਨ ਦਿੱਤਾ, ਜਾਇਦਾਦ ਦਿੱਤੀ, ਸੁਖ ਦਿੱਤੇ ਅਤੇ ਸੋਹਣੇ ਘਰ ਦਿੱਤੇ,"},{"gurmukhi":"ਕਹੁਨਾਨਕਸੁਨੁਰੇਮਨਾਸਿਮਰਤਕਾਹਿਨਰਾਮੁ॥੮॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਹੇ ਮਨ! ਸੁਣ, ਉਸ ਪਰਮਾਤਮਾ ਦਾ ਤੂੰ ਸਿਮਰਨ ਕਿਉਂ ਨਹੀਂ ਕਰਦਾ? ।੮।"},{"gurmukhi":"ਸਭਸੁਖਦਾਤਾਰਾਮੁਹੈਦੂਸਰਨਾਹਿਨਕੋਇ॥","meaning":"ਪਰਮਾਤਮਾ (ਹੀ) ਸਾਰੇ ਸੁਖ ਦੇਣ ਵਾਲਾ ਹੈ, (ਉਸ ਦੇ ਬਰਾਬਰ ਦਾ ਹੋਰ) ਕੋਈ ਦੂਜਾ ਨਹੀਂ ਹੈ,"},{"gurmukhi":"ਕਹੁਨਾਨਕਸੁਨਿਰੇਮਨਾਤਿਹਸਿਮਰਤਗਤਿਹੋਇ॥੯॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਹੇ ਮਨ! ਉਸ (ਦਾ ਨਾਮ) ਸਿਮਰਦਿਆਂ ਉੱਚੀ ਆਤਮਕ ਅਵਸਥਾ (ਭੀ) ਪ੍ਰਾਪਤ ਹੋ ਜਾਂਦੀ ਹੈ ।੯।"},{"gurmukhi":"ਜਿਹਸਿਮਰਤਗਤਿਪਾਈਐਤਿਹਭਜੁਰੇਤੈਮੀਤ॥","meaning":"ਹੇ ਮਿੱਤਰ! ਤੂੰ ਉਸ ਪਰਮਾਤਮਾ ਦਾ ਭਜਨ ਕਰਿਆ ਕਰ, ਜਿਸ ਦਾ ਨਾਮ ਸਿਮਰਦਿਆਂ ਉੱਚੀ ਆਤਮਕ ਅਵਸਥਾ ਪ੍ਰਾਪਤ ਹੁੰਦੀ ਹੈ ।"},{"gurmukhi":"ਕਹੁਨਾਨਕਸੁਨੁਰੇਮਨਾਅਉਧਘਟਤਹੈਨੀਤ॥੧੦॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਹੇ ਮਨ! ਸੁਣ, ਉਮਰ ਸਦਾ ਘਟਦੀ ਜਾ ਰਹੀ ਹੈ (ਪਰਮਾਤਮਾ ਦਾ ਸਿਮਰਨ ਨਾਹ ਵਿਸਾਰ) ।੧੦।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (4, 'ਸ੍ਰੀਕਾਲਜੀਕੀਉਸਤਤਿ॥', '[{"gurmukhi":"","meaning":"ਸ੍ਰੀ ਕਾਲ ਜੀ ਦੀ ਉਸਤਤ:"},{"gurmukhi":"ਤ੍ਰਿਭੰਗੀਛੰਦ॥","meaning":""},{"gurmukhi":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ:","meaning":""},{"gurmukhi":"ਖਗਖੰਡਬਿਹੰਡੰਖਲਦਲਖੰਡੰਅਤਿਰਣਮੰਡੰਬਰਬੰਡੰ॥","meaning":"ਤਲਵਾਰ ਚੰਗੀ ਤਰਾ ਟੁਕੜੇ ਟੁਕੜੇ ਕਰਦੀ ਹੈ, ਦੁਸ਼ਟਾ ਦੇ ਦਲਾ ਨੂੰ ਨਸ਼ਟ ਕਰਦੀ ਹੈ, ਯੁੱਧ ਨੂੰ ਸੁਸਜਤਿ ਕਰਦੀ ਹੈ, (ਅਜਿਹੀ) ਬਲਵਾਨ ਹੈ।"},{"gurmukhi":"ਭੁਜਦੰਡਅਖੰਡੰਤੇਜਪ੍ਰਚੰਡੰਜੋਤਿਅਮੰਡੰਭਾਨਪ੍ਰਭੰ॥","meaning":"ਇਹ ਅਖੰਡ ਤੇਜ ਵਾਲੀ ਭੁਜਦੰਡ ਹੈ, ਪ੍ਰਚੰਡ ਤੇਜ ਵਾਲੀ ਹੈ, ਅਤੇ ਸੂਰਜ ਦੀ ਸ਼ੋਭਾ ਦੀ ਜੋਤਿ ਨੂੰ ਫਿਕਿਆ ਕਰ ਦਿੰਦੀ ਹੈ।"},{"gurmukhi":"ਸੁਖਸੰਤਾਕਰਣੰਦੁਰਮਤਿਦਰਣੰਕਿਲਬਿਖਹਰਣੰਅਸਿਸਰਣੰ॥","meaning":"(ਇਹ) ਸੰਤਾ ਨੂੰ ਸੁਖ ਦੇਣ ਵਾਲੀ, ਮਾੜੀ ਬੁੱਧੀ ਨੂੰ ਦਲਣ ਵਾਲੀ, ਪਾਪਾ ਦਾ ਨਾਸ਼ ਕਰਨ ਵਾਲੀ ਹੈ, (ਮੈਂ) ਇਸ ਦੀ ਸ਼ਰਨ ਵਿਚ ਹਾ।"},{"gurmukhi":"ਜੈਜੈਜਗਕਾਰਣਸ੍ਰਿਸਟਿਉਬਾਰਣਮਮਪ੍ਰਤਿਪਾਰਣਜੈਤੇਗੰ॥੨॥","meaning":"ਹੇ ਜਗ ਦਾ ਕਾਰਨ ਸਰੂਪ! ਤੇਰੀ ਜੈ-ਜੈਕਾਰ ਹੋਵੇ, (ਕਿਉਕਿ ਤੂੰ) ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ ਉਬਾਰਨ ਵਾਲੀ ਅਤੇ ਮੇਰੀ ਪਾਲਣਾ ਕਰਨ ਵਾਲੀ ਹੈਂ, (ਤਾ ਤੇ ਤੇਰੀ) ਹੇ ਤੇਗ! ਜੈ ਜੈ ਹੋਵੇ ॥੨॥"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (5, 'ਆਸਾਵਰੀਮਹਲਾ੪॥', '[{"gurmukhi":"ਮਾਈਮੋਰੋਪ੍ਰੀਤਮੁਰਾਮੁਬਤਾਵਹੁਰੀਮਾਈ॥","meaning":"ਹੇ ਮਾਂ! ਮੈਨੂੰ ਦੱਸ ਪਿਆਰਾ ਰਾਮ ਕਿਥੇ ਹੈ,"},{"gurmukhi":"ਹਉਹਰਿਬਿਨੁਖਿਨੁਪਲੁਰਹਿਨਸਕਉਜੈਸੇਕਰਹਲੁਬੇਲਿਰੀਝਾਈ॥੧॥ਰਹਾਉ॥","meaning":"ਉਸ ਨੂੰ ਵੇਖ ਕੇ ਮੇਰਾ ਮਨ ਇਉਂ ਖ਼ੁਸ਼ ਹੁੰਦਾ ਹੈ ਜਿਵੇਂ ਊਂਠ ਦਾ ਬੱਚਾ ਵੇਲਾਂ ਵੇਖ ਵੇਖ ਕੇ ਖ਼ੁਸ਼ ਹੁੰਦਾ ਹੈ । ਮੈਂ ਉਸ ਹਰੀ (ਦੇ ਦਰਸਨ) ਤੋਂ ਬਿਨਾ ਇਕ ਖਿਨ ਭੀ, ਇਕ ਪਲ ਭੀ (ਸੁਖੀ) ਨਹੀਂ ਰਹਿ ਸਕਦਾ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਹਮਰਾਮਨੁਬੈਰਾਗਬਿਰਕਤੁਭਇਓਹਰਿਦਰਸਨਮੀਤਕੈਤਾਈ॥","meaning":"(ਹੇ ਮਾਂ!) ਮਿੱਤਰ ਪ੍ਰਭੂ ਦੇ ਦਰਸਨ ਦੀ ਖ਼ਾਤਰ ਮੇਰਾ ਮਨ ਉਤਾਵਲਾ ਹੋ ਰਿਹਾ ਹੈ, ਮੇਰਾ ਮਨ (ਦੁਨੀਆ ਵਲੋਂ) ਉਪਰਾਮ ਹੋਇਆ ਪਿਆ ਹੈ"},{"gurmukhi":"ਜੈਸੇਅਲਿਕਮਲਾਬਿਨੁਰਹਿਨਸਕੈਤੈਸੇਮੋਹਿਹਰਿਬਿਨੁਰਹਨੁਨਜਾਈ॥੧॥","meaning":"ਜਿਵੇਂ ਭੌਰਾ ਕੌਲ-ਫੁੱਲ ਤੋਂ ਬਿਨਾ ਨਹੀਂ ਰਹਿ ਸਕਦਾ, ਤਿਵੇਂ ਮੈਥੋਂ ਭੀ ਪਰਮਾਤਮਾ (ਦੇ ਦਰਸਨ) ਤੋਂ ਬਿਨਾ ਰਿਹਾ ਨਹੀਂ ਜਾ ਸਕਦਾ ।੧।"},{"gurmukhi":"ਰਾਖੁਸਰਣਿਜਗਦੀਸੁਰਪਿਆਰੇਮੋਹਿਸਰਧਾਪੂਰਿਹਰਿਗੁਸਾਈ॥","meaning":"ਹੇ ਜਗਤ ਦੇ ਮਾਲਕ! ਹੇ ਪਿਆਰੇ! ਹੇ ਹਰੀ! ਹੇ ਧਰਤੀ ਦੇ ਖਸਮ! ਮੈਨੂੰ ਆਪਣੀ ਸਰਨ ਵਿਚ ਰੱਖ, ਮੇਰੀ ਇਹ ਤਾਂਘ ਪੂਰੀ ਕਰ ।"},{"gurmukhi":"ਜਨਨਾਨਕਕੈਮਨਿਅਨਦੁਹੋਤਹੈਹਰਿਦਰਸਨੁਨਿਮਖਦਿਖਾਈ॥੨॥੩੯॥੧੩॥੧੫॥੬੭॥","meaning":"(ਜਦੋਂ ਤੇਰਾ ਦਰਸਨ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਤੇਰੇ) ਦਾਸ ਨਾਨਕ ਦੇ ਮਨ ਵਿਚ ਚਾਉ ਪੈਦਾ ਹੋ ਜਾਂਦਾ ਹੈ, ਹੇ ਹਰੀ! (ਮੈਨੂੰ ਨਾਨਕ ਨੂੰ) ਅੱਖ ਝਮਕਣ ਜਿਤਨੇ ਸਮੇ ਵਾਸਤੇ ਹੀ ਆਪਣਾ ਦਰਸਨ ਦੇਹ ।੨।੩੯।੧੩।੧੫।੬੭।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (6, 'ਤੂੰਮੇਰੋਮੇਰੁਪਰਬਤੁਸੁਆਮੀਓਟਗਹੀਮੈਤੇਰੀ॥', '[{"gurmukhi":"","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ (ਹੀ) ਮੇਰਾ ਸਭ ਤੋਂ ਵੱਡਾ ਆਸਰਾ ਹੈਂ । ਮੈਂ ਤੇਰੀ ਹੀ ਓਟ ਫੜੀ ਹੈ (ਕਿਸੇ ਤੀਰਥ ਉੱਤੇ ਵੱਸਣ ਦਾ ਤਕੀਆ ਮੈਂ ਨਹੀਂ ਤੱਕਿਆ) ਤੂੰ ਸਦਾ ਅਡੋਲ ਰਹਿਣ ਵਾਲਾ ਹੈਂ"},{"gurmukhi":"ਨਾਤੁਮਡੋਲਹੁਨਾਹਮਗਿਰਤੇਰਖਿਲੀਨੀਹਰਿਮੇਰੀ॥੧॥","meaning":"(ਤੇਰਾ ਲੜ ਫੜ ਕੇ) ਮੈਂ ਭੀ ਨਹੀਂ ਡੋਲਦਾ, ਕਿਉਂਕਿ ਤੂੰ ਆਪ ਮੇਰੀ ਲਾਜ ਰੱਖ ਲਈ ਹੈ ।੧।"},{"gurmukhi":"ਅਬਤਬਜਬਕਬਤੁਹੀਤੁਹੀ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਸਦਾ ਲਈ ਤੂੰ ਹੀ ਤੂੰ ਹੀ ਮੇਰਾ ਸਹਾਰਾ ਹੈਂ ।"},{"gurmukhi":"ਹਮਤੁਅਪਰਸਾਦਿਸੁਖੀਸਦਹੀ॥੧॥ਰਹਾਉ॥","meaning":"ਤੇਰੀ ਮਿਹਰ ਨਾਲ ਮੈਂ ਸਦਾ ਹੀ ਸੁਖੀ ਹਾਂ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਤੋਰੇਭਰੋਸੇਮਗਹਰਬਸਿਓਮੇਰੇਤਨਕੀਤਪਤਿਬੁਝਾਈ॥","meaning":"(ਲੋਕ ਆਖਦੇ ਹਨ ਮਗਹਰ ਸਰਾਪੀ ਹੋਈ ਧਰਤੀ ਹੈ, ਪਰ) ਮੈਂ ਤੇਰੇ ਉੱਤੇ ਸ਼ਰਧਾ ਧਾਰ ਕੇ ਮਗਹਰ ਜਾ ਵੱਸਿਆ, (ਤੂੰ ਮਿਹਰ ਕੀਤੀ ਤੇ) ਮੇਰੇ ਸਰੀਰ ਦੀ (ਵਿਕਾਰਾਂ ਦੀ) ਤਪਸ਼ (ਮਗਹਰ ਵਿਚ ਹੀ) ਬੁਝਾ ਦਿੱਤੀ ।"},{"gurmukhi":"ਪਹਿਲੇਦਰਸਨੁਮਗਹਰਪਾਇਓਫੁਨਿਕਾਸੀਬਸੇਆਈ॥੨॥","meaning":"ਮੈਂ, ਹੇ ਪ੍ਰਭੂ! ਤੇਰਾ ਦੀਦਾਰ ਪਹਿਲਾਂ ਮਗਹਰ ਵਿਚ ਰਹਿੰਦਿਆਂ ਹੀ ਕੀਤਾ ਸੀ, ਤੇ ਫੇਰ ਮੈਂ ਕਾਸ਼ੀ ਵਿਚ ਆ ਵੱਸਿਆ ।੨।"},{"gurmukhi":"ਜੈਸਾਮਗਹਰੁਤੈਸੀਕਾਸੀਹਮਏਕੈਕਰਿਜਾਨੀ॥","meaning":"ਜਿਵੇਂ ਕਿਸੇ ਕੰਗਾਲ ਨੂੰ ਧਨ ਮਿਲ ਜਾਏ, (ਤਿਵੇਂ) ਮੈਨੂੰ ਕੰਗਾਲ ਨੂੰ ਤੇਰਾ ਨਾਮ ਧਨ ਮਿਲ ਗਿਆ ਹੈ, (ਉਸ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਮੈਂ ਮਗਹਰ ਤੇ ਕਾਸ਼ੀ ਦੋਹਾਂ ਨੂੰ ਇਕੋ ਜਿਹਾ ਹੀ ਸਮਝਿਆ ਹੈ ।"},{"gurmukhi":"ਹਮਨਿਰਧਨਜਿਉਇਹੁਧਨੁਪਾਇਆਮਰਤੇਫੂਟਿਗੁਮਾਨੀ॥੩॥","meaning":"ਪਰ (ਜਿਨ੍ਹਾਂ ਨੂੰ ਕਾਸ਼ੀ ਤੀਰਥ ਤੇ ਵੱਸਣ ਦਾ ਮਾਣ ਹੈ ਉਹ) ਹੰਕਾਰੀ ਹੰਕਾਰ ਵਿਚ ਦੁੱਖੀ ਹੁੰਦੇ ਹਨ ।੩।"},{"gurmukhi":"ਕਰੈਗੁਮਾਨੁਚੁਭਹਿਤਿਸੁਸੂਲਾਕੋਕਾਢਨਕਉਨਾਹੀ॥","meaning":"ਜੋ ਮਨੁੱਖ ਮਾਣ ਕਰਦਾ ਹੈ (ਮਾਣ ਚਾਹੇ ਕਿਸੇ ਗੱਲ ਦਾ ਹੋਵੇ) ਉਸ ਨੂੰ (ਇਉਂ ਹੁੰਦਾ ਹੈ ਜਿਵੇਂ) ਸੂਲਾਂ ਚੁੱਭਦੀਆਂ ਹਨ । ਕੋਈ ਉਹਨਾਂ ਦੀਆਂ ਇਹ ਸੂਲਾਂ ਪੁੱਟ ਨਹੀਂ ਸਕਦਾ ।"},{"gurmukhi":"ਅਜੈਸੁਚੋਭਕਉਬਿਲਲਬਿਲਾਤੇਨਰਕੇਘੋਰਪਚਾਹੀ॥੪॥","meaning":"ਸਾਰੀ ਉਮਰ (ਉਹ ਹੰਕਾਰੀ) ਉਹਨਾਂ ਚੋਭਾਂ ਦੇ ਮਾਰੇ ਵਿਲਕਦੇ ਹਨ, ਮਾਨੋ, ਘੋਰ ਨਰਕ ਵਿਚ ਸੜ ਰਹੇ ਹਨ ।੪।"},{"gurmukhi":"ਕਵਨੁਨਰਕੁਕਿਆਸੁਰਗੁਬਿਚਾਰਾਸੰਤਨਦੋਊਰਾਦੇ॥","meaning":"(ਇਹ ਲੋਕ ਆਖਦੇ ਹਨ ਕਿ ਕਾਸ਼ੀ ਵਿਚ ਰਹਿਣ ਵਾਲਾ ਸੁਰਗ ਮਾਣਦਾ ਹੈ, ਪਰ) ਨਰਕ ਕੀਹ, ਤੇ, ਵਿਚਾਰਾ ਸੁਰਗ ਕੀਹ? ਸੰਤਾਂ ਨੇ ਦੋਵੇਂ ਹੀ ਰੱਦ ਕਰ ਦਿੱਤੇ ਹਨ;"},{"gurmukhi":"ਹਮਕਾਹੂਕੀਕਾਣਿਨਕਢਤੇਅਪਨੇਗੁਰਪਰਸਾਦੇ॥੫॥","meaning":"ਕਿਉਂਕਿ ਸੰਤ ਆਪਣੇ ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ (ਨਾਹ ਸੁਰਗ ਤੇ ਨਾਹ ਨਰਕ) ਕਿਸੇ ਦੇ ਭੀ ਮੁਥਾਜ ਨਹੀਂ ਹਨ ।੫।"},{"gurmukhi":"ਅਬਤਉਜਾਇਚਢੇਸਿੰਘਾਸਨਿਮਿਲੇਹੈਸਾਰਿੰਗਪਾਨੀ॥","meaning":"(ਆਪਣੇ ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ) ਮੈਂ ਹੁਣ ਉੱਚੇ ਆਤਮਕ ਟਿਕਾਣੇ ਤੇ ਅੱਪੜ ਗਿਆ ਹਾਂ, ਜਿੱਥੇ ਮੈਨੂੰ ਪਰਮਾਤਮਾ ਮਿਲ ਪਿਆ ਹੈ ।"},{"gurmukhi":"ਰਾਮਕਬੀਰਾਏਕਭਏਹੈਕੋਇਨਸਕੈਪਛਾਨੀ॥੬॥੩॥","meaning":"ਮੈਂ ਕਬੀਰ ਅਤੇ ਮੇਰਾ ਰਾਮ ਇੱਕ-ਰੂਪ ਹੋ ਗਏ ਹਾਂ, ਕੋਈ ਸਾਡੇ ਵਿਚ ਫ਼ਰਕ ਨਹੀ ਦੱਸ ਸਕਦਾ ।੬।੩।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (7, 'ਵਡਹੰਸੁਮਹਲਾ੫॥', '[{"gurmukhi":"ਤੂਬੇਅੰਤੁਕੋਵਿਰਲਾਜਾਣੈ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਅੰਤ ਨਹੀਂ ਪੈ ਸਕਦਾ, ਕੋਈ ਵਿਰਲਾ ਮਨੁੱਖ ਤੇਰੇ ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਪਾਂਦਾ ਹੈ ।"},{"gurmukhi":"ਗੁਰਪ੍ਰਸਾਦਿਕੋਸਬਦਿਪਛਾਣੈ॥੧॥","meaning":"ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਵਿਚ ਜੁੜ ਕੇ ਕੋਈ ਵਿਰਲਾ ਤੇਰੇ ਨਾਲ ਜਾਣ-ਪਛਾਣ ਪਾਂਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਸੇਵਕਕੀਅਰਦਾਸਿਪਿਆਰੇ॥","meaning":"ਹੇ ਪਿਆਰੇ ਪ੍ਰਭੂ! ਮੈਂ ਸੇਵਕ ਦੀ (ਤੇਰੇ ਦਰ ਤੇ) ਅਰਦਾਸ ਹੈ,"},{"gurmukhi":"ਜਪਿਜੀਵਾਪ੍ਰਭਚਰਣਤੁਮਾਰੇ॥੧॥ਰਹਾਉ॥","meaning":"(ਮੇਹਰ ਕਰ) ਹੇ ਪ੍ਰਭੂ! ਤੇਰੇ ਚਰਨ ਹਿਰਦੇ ਵਿਚ ਵਸਾ ਕੇ ਮੈਂ ਆਤਮਕ ਜੀਵਨ ਪ੍ਰਾਪਤ ਕਰਾਂ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਦਇਆਲਪੁਰਖਮੇਰੇਪ੍ਰਭਦਾਤੇ॥","meaning":"ਹੇ ਮੇਰੇ ਦਾਤੇ ਪ੍ਰਭੂ! ਹੇ ਦਇਆ ਦੇ ਘਰ ਅਕਾਲ ਪੁਰਖ!"},{"gurmukhi":"ਜਿਸਹਿਜਨਾਵਹੁਤਿਨਹਿਤੁਮਜਾਤੇ॥੨॥","meaning":"ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਤੂੰ ਆਪ ਸੂਝ ਬਖ਼ਸ਼ਦਾ ਹੈਂ, ਉਸੇ ਨੇ ਹੀ ਤੇਰੇ ਨਾਲ ਸਾਂਝ ਪਾਈ ਹੈ ।੨।"},{"gurmukhi":"ਸਦਾਸਦਾਜਾਈਬਲਿਹਾਰੀ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੈਂ ਸਦਾ ਹੀ ਸਦਾ ਹੀ ਤੈਥੋਂ ਸਦਕੇ ਜਾਂਦਾ ਹਾਂ ।"},{"gurmukhi":"ਇਤਉਤਦੇਖਉਓਟਤੁਮਾਰੀ॥੩॥","meaning":"ਇਸ ਲੋਕ ਵਿਚ ਤੇ ਪਰਲੋਕ ਵਿਚ ਮੈਂ ਤੇਰਾ ਹੀ ਆਸਰਾ ਤੱਕਦਾ ਹਾਂ ।੩।"},{"gurmukhi":"ਮੋਹਿਨਿਰਗੁਣਗੁਣੁਕਿਛੂਨਜਾਤਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੈਂ ਗੁਣ-ਹੀਣ ਹਾਂ, ਮੈਂ ਤੇਰਾ ਗੁਣ (ਉਪਕਾਰ) ਕੁਝ ਭੀ ਨਹੀਂ ਸਾਂ ਸਮਝ ਸਕਿਆ ।"},{"gurmukhi":"ਨਾਨਕਸਾਧੂਦੇਖਿਮਨੁਰਾਤਾ॥੪॥੩॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—ਹੇ ਪ੍ਰਭੂ!) ਗੁਰੂ ਦਾ ਦਰਸਨ ਕਰ ਕੇ ਮੇਰਾ ਮਨ (ਤੇਰੇ ਪ੍ਰੇਮ ਵਿਚ) ਰੰਗਿਆ ਗਿਆ ਹੈ ।੪।੩।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (8, 'ੴਸਤਿਨਾਮੁਕਰਤਾਪੁਰਖੁਨਿਰਭਉਨਿਰਵੈਰੁਅਕਾਲਮੂਰਤਿਅਜੂਨੀਸੈਭੰਗੁਰਪ੍ਰਸਾਦਿ॥', '[{"gurmukhi":"ਰਾਗੁਜੈਜਾਵੰਤੀਮਹਲਾ੯॥","meaning":""},{"gurmukhi":"ਰਾਮੁਸਿਮਰਿਰਾਮੁਸਿਮਰਿਇਹੈਤੇਰੈਕਾਜਿਹੈ॥","meaning":"ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ (ਦਾ ਨਾਮ) ਸਿਮਰਿਆ ਕਰ, ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰਿਆ ਕਰ । ਇਹ (ਸਿਮਰਨ) ਹੀ ਤੇਰੇ ਕੰਮ ਵਿਚ (ਆਉਣ ਵਾਲਾ) ਹੈ ।"},{"gurmukhi":"ਮਾਇਆਕੋਸੰਗੁਤਿਆਗੁਪ੍ਰਭਜੂਕੀਸਰਨਿਲਾਗੁ॥","meaning":"ਹੇ ਭਾਈ! ਮਾਇਆ ਦਾ ਮੋਹ ਛੱਡ ਦੇਹ, ਪਰਮਾਤਮਾ ਦੀ ਸਰਨ ਪਿਆ ਰਹੁ ।"},{"gurmukhi":"ਜਗਤਸੁਖਮਾਨੁਮਿਥਿਆਝੂਠੋਸਭਸਾਜੁਹੈ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਭਾਈ! ਦੁਨੀਆ ਦੇ ਸੁਖਾਂ ਨੂੰ ਨਾਸਵੰਤ ਸਮਝ । ਜਗਤ ਦਾ ਇਹ ਸਾਰਾ ਪਸਾਰਾ (ਹੀ) ਸਾਥ ਛੱਡ ਜਾਣ ਵਾਲਾ ਹੈ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਸੁਪਨੇਜਿਉਧਨੁਪਛਾਨੁਕਾਹੇਪਰਿਕਰਤਮਾਨੁ॥","meaning":"ਹੇ ਭਾਈ! ਇਸ ਧਨ ਨੂੰ ਸੁਪਨੇ (ਵਿਚ ਮਿਲੇ ਪਦਾਰਥਾਂ) ਵਾਂਗ ਸਮਝ (ਜਾਗ ਖੁਲ੍ਹਦਿਆਂ ਹੀ ਉਹ ਪਦਾਰਥ ਲੋਪ ਹੋ ਜਾਂਦੇ ਹਨ । ਦੱਸ,) ਤੂੰ ਕਾਹਦੇ ਉੱਤੇ ਅਹੰਕਾਰ ਕਰਦਾ ਹੈਂ?"},{"gurmukhi":"ਬਾਰੂਕੀਭੀਤਿਜੈਸੇਬਸੁਧਾਕੋਰਾਜੁਹੈ॥੧॥","meaning":"(ਸਾਰੀ) ਧਰਤੀ ਦਾ ਰਾਜ (ਭੀ) ਰੇਤ ਦੀ ਕੰਧ ਵਰਗਾ ਹੀ ਹੈ ।੧।"},{"gurmukhi":"ਨਾਨਕੁਜਨੁਕਹਤੁਬਾਤਬਿਨਸਿਜੈਹੈਤੇਰੋਗਾਤੁ॥","meaning":"ਹੇ ਭਾਈ! ਦਾਸ ਨਾਨਕ (ਤੈਨੂੰ ਇਹ) ਗੱਲ ਦੱਸਦਾ ਹੈ ਕਿ ਤੇਰਾ (ਤਾਂ ਇਹ ਆਪਣਾ ਮਿਥਿਆ ਹੋਇਆ) ਸਰੀਰ (ਭੀ) ਨਾਸ ਹੋ ਜਾਇਗਾ ।"},{"gurmukhi":"ਛਿਨੁਛਿਨੁਕਰਿਗਇਓਕਾਲੁਤੈਸੇਜਾਤੁਆਜੁਹੈ॥੨॥੧॥","meaning":"(ਵੇਖ, ਜਿਵੇਂ ਤੇਰੀ ਉਮਰ ਦਾ) ਕੱਲ (ਦਾ ਦਿਨ) ਛਿਨ ਛਿਨ ਕਰ ਕੇ ਬੀਤ ਗਿਆ ਹੈ, ਤਿਵੇਂ ਅੱਜ (ਦਾ ਦਿਨ ਭੀ) ਲੰਘਦਾ ਜਾ ਰਿਹਾ ਹੈ ।੨।੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (9, 'ਧਨਾਸਰੀਮਹਲਾ੫ਘਰੁ੭', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਹਰਿਏਕੁਸਿਮਰਿਏਕੁਸਿਮਰਿਏਕੁਸਿਮਰਿਪਿਆਰੇ॥","meaning":"ਹੇ ਪਿਆਰੇ! ਸਦਾ ਹੀ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰਿਆ ਕਰ ।"},{"gurmukhi":"ਕਲਿਕਲੇਸਲੋਭਮੋਹਮਹਾਭਉਜਲੁਤਾਰੇ॥ਰਹਾਉ॥","meaning":"ਇਹ ਸਿਮਰਨ) ਇਸ ਵੱਡੇ ਭਿਆਨਕ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ ਪਾਰ ਲੰਘਾ ਲੈਂਦਾ ਹੈ ਜਿਸ ਵਿਚ ਬੇਅੰਤ ਸੰਸਾਰਕ ਝਗੜੇ ਹਨ, ਜਿਸ ਵਿਚ ਲੋਭ ਮੋਹ (ਦੀਆਂ ਲਹਿਰਾਂ ਉਠ ਰਹੀਆਂ) ਹਨ ।ਰਹਾਉ"},{"gurmukhi":"ਸਾਸਿਸਾਸਿਨਿਮਖਨਿਮਖਦਿਨਸੁਰੈਨਿਚਿਤਾਰੇ॥","meaning":"ਹੇ ਭਾਈ! ਦਿਨ ਰਾਤ ਛਿਨ ਛਿਨ ਹਰੇਕ ਸਾਹ ਦੇ ਨਾਲ (ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਚੇਤੇ ਕਰਦਾ ਰਹੁ ।"},{"gurmukhi":"ਸਾਧਸੰਗਜਪਿਨਿਸੰਗਮਨਿਨਿਧਾਨੁਧਾਰੇ॥੧॥","meaning":"ਸਾਧ ਸੰਗਤਿ ਵਿਚ (ਬੈਠ ਕੇ) ਝਾਕਾ ਲਾਹ ਕੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਜਪਿਆ ਕਰ । ਇਹ ਨਾਮ-ਖ਼ਜ਼ਾਨਾ ਆਪਣੇ ਮਨ ਵਿਚ ਵਸਾਈ ਰੱਖ ।੧।"},{"gurmukhi":"ਚਰਨਕਮਲਨਮਸਕਾਰਗੁਨਗੋਬਿਦਬੀਚਾਰੇ॥","meaning":"ਹੇ ਪਿਆਰੇ! ਪਰਮਾਤਮਾ ਦੇ ਕੋਮਲ ਚਰਨਾਂ ਉਤੇ ਆਪਣਾ ਸਿਰ ਨਿਵਾਈ ਰੱਖ । ਗੋਬਿੰਦ ਦੇ ਗੁਣ ਆਪਣੇ ਸੋਚ-ਮੰਡਲ ਵਿਚ ਵਸਾ"},{"gurmukhi":"ਸਾਧਜਨਾਕੀਰੇਨਨਾਨਕਮੰਗਲਸੂਖਸਧਾਰੇ॥੨॥੧॥੩੧॥","meaning":"ਹੇ ਨਾਨਕ! ਸੰਤ ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ (ਆਪਣੇ ਮੱਥੇ ਉਤੇ ਲਾਇਆ ਕਰ, ਇਹ ਚਰਨ-ਧੂੜ) ਆਤਮਕ ਖ਼ੁਸ਼ੀਆਂ ਤੇ ਆਤਮਕ ਆਨੰਦ ਦੇਂਦੀ ਹੈ ।੨।੧।੩੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (10, 'ਸੋਰਠਿਮਹਲਾ੫॥', '[{"gurmukhi":"ਗੁਰਕਾਸਬਦੁਰਖਵਾਰੇ॥","meaning":"ਹੇ ਭਾਈ! ਵਿਕਾਰਾਂ ਦੇ ਟਾਕਰੇ ਤੇ) ਗੁਰੂ ਦਾ ਸ਼ਬਦ ਹੀ ਅਸਾਂ ਜੀਵਾਂ ਦਾ ਰਾਖਾ ਹੈ"},{"gurmukhi":"ਚਉਕੀਚਉਗਿਰਦਹਮਾਰੇ॥","meaning":"ਸ਼ਬਦ ਹੀ (ਸਾਨੂੰ ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਾਣ ਲਈ) ਸਾਡੇ ਚੁਫੇਰੇ ਪਹਿਰਾ ਹੈ"},{"gurmukhi":"ਰਾਮਨਾਮਿਮਨੁਲਾਗਾ॥","meaning":"ਗੁਰ-ਸ਼ਬਦ ਦੀ ਬਰਕਤਿ ਨਾਲ ਜਿਸ ਮਨੁੱਖ ਦਾ) ਮਨ ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਵਿਚ ਜੁੜਦਾ ਹੈ,"},{"gurmukhi":"ਜਮੁਲਜਾਇਕਰਿਭਾਗਾ॥੧॥","meaning":"ਉਸ ਪਾਸੋਂ (ਵਿਕਾਰ ਤਾਂ ਕਿਤੇ ਰਹੇ) ਜਮ (ਭੀ) ਸ਼ਰਮਿੰਦਾ ਹੋ ਕੇ ਭੱਜ ਜਾਂਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਪ੍ਰਭਜੀਤੂਮੇਰੋਸੁਖਦਾਤਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ ਜੀ! ਮੇਰੇ ਵਾਸਤੇ ਤਾਂ ਤੂੰ ਹੀ ਸੁਖਾਂ ਦਾ ਦਾਤਾ ਹੈਂ"},{"gurmukhi":"ਬੰਧਨਕਾਟਿਕਰੇਮਨੁਨਿਰਮਲੁਪੂਰਨਪੁਰਖੁਬਿਧਾਤਾ॥ਰਹਾਉ॥","meaning":"(ਹੇ ਭਾਈ! ਜੇਹੜਾ ਮਨੁੱਖ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਵਿਚ ਮਨ ਜੋੜਦਾ ਹੈ) ਸਰਬ-ਵਿਆਪਕ ਸਿਰਜਣਹਾਰ ਪ੍ਰਭੂ (ਉਸ ਦੇ ਮਾਇਆ ਦੇ ਮੋਹ ਆਦਿਕ ਦੇ ਸਾਰੇ) ਬੰਧਨ ਕੱਟ ਕੇ ਉਸ ਦੇ ਮਨ ਨੂੰ ਪਵਿਤ੍ਰ ਕਰ ਦੇਂਦਾ ਹੈ ।ਰਹਾਉ"},{"gurmukhi":"ਨਾਨਕਪ੍ਰਭੁਅਬਿਨਾਸੀ॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਅਬਿਨਾਸ਼ੀ ਪ੍ਰਭੂ"},{"gurmukhi":"ਤਾਕੀਸੇਵਨਬਿਰਥੀਜਾਸੀ॥","meaning":"(ਐਸਾ ਉਦਾਰ-ਚਿੱਤ ਹੈ ਕਿ) ਉਸ ਦੀ ਕੀਤੀ ਹੋਈ ਸੇਵਾ-ਭਗਤੀ ਖ਼ਾਲੀ ਨਹੀਂ ਜਾਂਦੀ"},{"gurmukhi":"ਅਨਦਕਰਹਿਤੇਰੇਦਾਸਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੇਰੇ ਸੇਵਕ (ਸਦਾ) ਆਤਮਕ ਆਨੰਦ ਮਾਣਦੇ ਹਨ,"},{"gurmukhi":"ਜਪਿਪੂਰਨਹੋਈਆਸਾ॥੨॥੪॥੬੮॥","meaning":"ਤੇਰਾ ਨਾਮ ਜਪ ਕੇ ਉਹਨਾਂ ਦੀ ਹਰੇਕ ਮਨੋ-ਕਾਮਨਾ ਪੂਰੀ ਹੋ ਜਾਂਦੀ ਹੈ ।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (11, 'ਕੇਦਾਰਾਮਹਲਾ੫॥', '[{"gurmukhi":"ਹਰਿਹਰਿਹਰਿਗੁਨਗਾਵਹੁ॥","meaning":"ਹੇ ਭਾਈ! ਸਦਾ ਪਰਮਾਤਮਾ ਦੇ ਗੁਣ ਗਾਂਦੇ ਰਿਹਾ ਕਰੋ ।"},{"gurmukhi":"ਕਰਹੁਕ੍ਰਿਪਾਗੋਪਾਲਗੋਬਿਦੇਅਪਨਾਨਾਮੁਜਪਾਵਹੁ॥ਰਹਾਉ॥","meaning":"ਹੇ ਗੋਪਾਲ! ਹੇ ਗੋਬਿੰਦ! (ਮੇਰੇ ਉਤੇ) ਮਿਹਰ ਕਰ, ਮੈਨੂੰ ਆਪਣਾ ਨਾਮ ਜਪਣ ਵਿਚ ਸਹਾਇਤਾ ਕਰ ।ਰਹਾਉ।"},{"gurmukhi":"ਕਾਢਿਲੀਏਪ੍ਰਭਆਨਬਿਖੈਤੇਸਾਧਸੰਗਿਮਨੁਲਾਵਹੁ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਮਨੁੱਖਾਂ ਦਾ ਮਨ ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਲਾਂਦਾ ਹੈਂ, ਉਹਨਾਂ ਨੂੰ ਤੂੰ ਹੋਰ ਹੋਰ ਵਿਸ਼ਿਆਂ ਵਿਚੋਂ ਕੱਢ ਲਿਆ ਹੈ ।"},{"gurmukhi":"ਭ੍ਰਮੁਭਉਮੋਹੁਕਟਿਓਗੁਰਬਚਨੀਅਪਨਾਦਰਸੁਦਿਖਾਵਹੁ॥੧॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੂੰ ਆਪਣਾ ਦਰਸਨ ਦੇਂਦਾ ਹੈਂ, ਗੁਰੂ ਦੇ ਬਚਨਾਂ ਦੀ ਰਾਹੀਂ ਉਹਨਾਂ ਦਾ ਭਰਮ ਉਹਨਾਂ ਦਾ ਡਰ ਉਹਨਾਂ ਦਾ ਮੋਹ ਕੱਟਿਆ ਜਾਂਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਸਭਕੀਰੇਨਹੋਇਮਨੁਮੇਰਾਅਹੰਬੁਧਿਤਜਾਵਹੁ॥","meaning":"ਹੇ ਦਇਆਲ ਪ੍ਰਭੂ! (ਮਿਹਰ ਕਰ, ਮੈਨੂੰ) ਆਪਣੀ ਭਗਤੀ (ਦੀ ਦਾਤਿ) ਬਖ਼ਸ਼ (ਮਿਹਰ ਕਰ, ਮੇਰੇ ਅੰਦਰੋਂ) ਹਉਮੈ ਦੂਰ ਕਰਾ, ਮੇਰਾ ਮਨ ਸਭਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਹੋਇਆ ਰਹੇ ।"},{"gurmukhi":"ਅਪਨੀਭਗਤਿਦੇਹਿਦਇਆਲਾਵਡਭਾਗੀਨਾਨਕਹਰਿਪਾਵਹੁ॥੨॥੪॥੬॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—ਹੇ ਭਾਈ!) ਤੁਸੀਂ ਵੱਡੇ ਭਾਗਾਂ ਨਾਲ (ਹੀ) ਪਰਮਾਤਮਾ ਦਾ ਮਿਲਾਪ ਕਰ ਸਕਦੇ ਹੋ ।੨।੪।੬।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (12, 'ਆਸਾਮਹਲਾ੫ਤਿਪਦੇ॥', '[{"gurmukhi":"ਓਹਾਪ੍ਰੇਮਪਿਰੀ॥੧॥ਰਹਾਉ॥","meaning":"(ਹੇ ਭਾਈ! ਮੈਨੂੰ ਤਾਂ) ਪਿਆਰੇ (ਪ੍ਰਭੂ) ਦਾ ਉਹ ਪ੍ਰੇਮ ਹੀ (ਚਾਹੀਦਾ ਹੈ) ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਕਨਿਕਮਾਣਿਕਗਜਮੋਤੀਅਨਲਾਲਨਨਹਨਾਹਨਹੀ॥੧॥","meaning":"(ਹੇ ਭਾਈ! ਪ੍ਰਭੂ ਦੇ ਪਿਆਰ ਦੇ ਟਾਕਰੇ ਤੇ) ਸੋਨਾ, ਮੋਤੀ, ਵੱਡੇ ਵੱਡੇ ਮੋਤੀ, ਹੀਰੇ-ਲਾਲ—ਮੈਨੂੰ ਇਹਨਾਂ ਵਿਚੋਂ ਕੋਈ ਭੀ ਚੀਜ਼ ਨਹੀਂ ਚਾਹੀਦੀ, ਨਹੀਂ ਚਾਹੀਦੀ, ।੧।"},{"gurmukhi":"ਰਾਜਨਭਾਗਨਹੁਕਮਨਸਾਦਨ॥","meaning":"(ਹੇ ਭਾਈ! ਪ੍ਰਭੂ-ਪਿਆਰ ਦੇ ਥਾਂ) ਨਾਹ ਰਾਜ, ਨਾਹ ਧਨ-ਪਦਾਰਥ, ਨਾਹ ਹੁਕੂਮਤ ਨਾਹ ਸੁਆਦਲੇ ਖਾਣੇ—"},{"gurmukhi":"ਕਿਛੁਕਿਛੁਨਚਾਹੀ॥੨॥","meaning":"ਮੈਨੂੰ ਕਿਸੇ ਚੀਜ਼ ਦੀ ਭੀ ਲੋੜ ਨਹੀਂ ।੨।"},{"gurmukhi":"ਚਰਨਨਸਰਨਨਸੰਤਨਬੰਦਨ॥","meaning":"ਹੇ ਭਾਈ! ਸੰਤ ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਸਰਨ, ਸੰਤ ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਤੇ ਨਮਸਕਾਰ—"},{"gurmukhi":"ਸੁਖੋਸੁਖੁਪਾਹੀ॥","meaning":"ਇਸ ਵਿਚ ਮੈਂ ਸੁਖ ਹੀ ਸੁਖ ਅਨੁਭਵ ਕਰਦਾ ਹਾਂ ।"},{"gurmukhi":"ਨਾਨਕਤਪਤਿਹਰੀ॥","meaning":"ਹੇ ਨਾਨਕ! ਜੇ ਪਿਆਰੇ ਪ੍ਰਭੂ ਦਾ ਪ੍ਰੇਮ ਮਿਲ ਜਾਏ"},{"gurmukhi":"ਮਿਲੇਪ੍ਰੇਮਪਿਰੀ॥੩॥੩॥੧੪੩॥","meaning":"ਤਾਂ ਉਹ ਮਨ ਵਿਚੋਂ ਤ੍ਰਿਸ਼ਨਾ ਦੀ ਸੜਨ ਦੂਰ ਕਰ ਦੇਂਦਾ ਹੈ ।੩।੩।੧੪੩।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (13, 'ਸੂਹੀਮਹਲਾ੫ਘਰੁ੩', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਸੇਵਾਥੋਰੀਮਾਗਨੁਬਹੁਤਾ॥","meaning":"ਹੇ ਭਾਈ! ਇਹ ਮੂਰਖ ਕੰਮ ਤਾਂ ਥੋੜਾ ਕਰਦਾ ਹੈ, ਪਰ ਉਸ ਦੇ ਇਵਜ਼ ਵਿਚ ਇਸ ਦੀ ਮੰਗ ਬਹੁਤ ਜ਼ਿਆਦਾ ਹੈ"},{"gurmukhi":"ਮਹਲੁਨਪਾਵੈਕਹਤੋਪਹੁਤਾ॥੧॥","meaning":"ਪ੍ਰਭੂ ਦੇ ਚਰਨਾਂ ਤਕ ਪਹੁੰਚ ਤਾਂ ਹਾਸਲ ਨਹੀਂ ਕਰ ਸਕਦਾ, ਪਰ ਆਖਦਾ ਹੈ ਕਿ ਮੈਂ (ਪ੍ਰਭੂ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ) ਪਹੁੰਚਿਆ ਹੋਇਆ ਹਾਂ ।੧।"},{"gurmukhi":"ਜੋਪ੍ਰਿਅਮਾਨੇਤਿਨਕੀਰੀਸਾ॥","meaning":"ਹੇ ਭਾਈ! ਝੂਠੇ ਮੂਰਖ ਮਨੁੱਖ ਦੇ ਹਠ ਦੀ ਗੱਲ (ਸੁਣ)"},{"gurmukhi":"ਕੂੜੇਮੂਰਖਕੀਹਾਠੀਸਾ॥੧॥ਰਹਾਉ॥","meaning":"ਇਹ ਉਹਨਾਂ ਦੀ ਰੀਸ ਕਰਦਾ ਹੈ ਜੇਹੜੇ ਪਿਆਰੇ ਪ੍ਰਭੂ ਦੇ ਦਰ ਤੋਂ ਸਤਕਾਰ ਹਾਸਲ ਕਰ ਚੁਕੇ ਹਨ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਭੇਖਦਿਖਾਵੈਸਚੁਨਕਮਾਵੈ॥","meaning":"(ਹੇ ਭਾਈ! ਝੂਠਾ ਮੂਰਖ ਹੋਰਨਾਂ ਨੂੰ ਆਪਣੇ ਧਰਮੀ ਹੋਣ ਦੇ ਨਿਰੇ) ਭੇਖ ਵਿਖਾ ਰਿਹਾ ਹੈ, ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਸਿਮਰਨ ਦੀ ਕਮਾਈ ਨਹੀਂ ਕਰਦਾ"},{"gurmukhi":"ਕਹਤੋਮਹਲੀਨਿਕਟਿਨਆਵੈ॥੨॥","meaning":"ਮੂੰਹੋਂ ਆਖਦਾ ਹੈ ਕਿ ਮੈਂ ਹਜ਼ੂਰੀ ਵਿਚ ਪਹੁੰਚਿਆ ਹੋਇਆ ਹਾਂ, ਪਰ (ਪ੍ਰਭੂ-ਚਰਨਾਂ ਦੇ ਕਿਤੇ) ਨੇੜੇ ਭੀ ਨਹੀਂ ਢੁਕਿਆ ।੨।"},{"gurmukhi":"ਅਤੀਤੁਸਦਾਏਮਾਇਆਕਾਮਾਤਾ॥","meaning":"ਹੇ ਭਾਈ! ਵੇਖ ਮੂਰਖ ਦੀ ਹਠ ਦੀ ਗੱਲ! ਇਹ ਆਪਣੇ ਆਪ ਨੂੰ) ਤਿਆਗੀ ਅਖਵਾਂਦਾ ਹੈ ਪਰ ਮਾਇਆ (ਦੀ ਲਾਲਸਾ) ਵਿਚ ਮਸਤ ਰਹਿੰਦਾ ਹੈ"},{"gurmukhi":"ਮਨਿਨਹੀਪ੍ਰੀਤਿਕਹੈਮੁਖਿਰਾਤਾ॥੩॥","meaning":"ਇਸ ਦੇ) ਮਨ ਵਿਚ (ਪ੍ਰਭੂ-ਚਰਨਾਂ ਦਾ) ਪਿਆਰ ਨਹੀਂ ਹੈ, ਪਰ ਮੂੰਹੋਂ ਆਖਦਾ ਹੈ ਕਿ ਮੈਂ (ਪ੍ਰਭੂ ਦੇ ਪ੍ਰੇਮ-ਰੰਗ ਵਿਚ) ਰੰਗਿਆ ਹੋਇਆ ਹਾਂ ।੩।"},{"gurmukhi":"ਕਹੁਨਾਨਕਪ੍ਰਭਬਿਨਉਸੁਨੀਜੈ॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਹੇ ਪ੍ਰਭੂ! ਮੇਰੀ ਬੇਨਤੀ ਸੁਣ (ਜੀਵ ਵਿਚਾਰਾ ਕੁਝ ਕਰਨ-ਜੋਗਾ ਨਹੀਂ, ਇਹ) ਮੰਦ-ਕਰਮੀ ਹੈ, ਨਿਰਦਈ ਹੈ"},{"gurmukhi":"ਕੁਚਲੁਕਠੋਰੁਕਾਮੀਮੁਕਤੁਕੀਜੈ॥੪॥","meaning":"ਵਸ਼ਈ ਹੈ (ਫਿਰ ਭੀ ਤੇਰਾ) ਹੈ ਇਸ ਨੂੰ ਇਹਨਾਂ ਵਿਕਾਰਾਂ ਤੋਂ ਖ਼ਲਾਸੀ ਬਖ਼ਸ਼ ।੪।"},{"gurmukhi":"ਦਰਸਨਦੇਖੇਕੀਵਡਿਆਈ॥","meaning":"ਹੇ ਪੁਰਖ ਪ੍ਰਭੂ! ਤੂੰ ਸਭ ਸੁਖ ਦੇਣ-ਜੋਗ ਹੈਂ, ਤੂੰ ਪਿਆਰ-ਭਰਪੂਰ ਹੈਂ"},{"gurmukhi":"ਤੁਮ੍ਹਸੁਖਦਾਤੇਪੁਰਖਸੁਭਾਈ॥੧॥ਰਹਾਉਦੂਜਾ॥੧॥੭॥","meaning":"ਅਸਾਂ ਜੀਵਾਂ ਨੂੰ) ਇਹ ਵਡਿਆਈ ਬਖ਼ਸ਼ ਕਿ ਤੇਰਾ ਦਰਸਨ ਕਰ ਸਕੀਏ ।੧।ਰਹਾਉ ਦੂਜਾ ।੧।੭।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (14, 'ਸੂਹੀਮਹਲਾ੪॥', '[{"gurmukhi":"ਕੀਤਾਕਰਣਾਸਰਬਰਜਾਈਕਿਛੁਕੀਚੈਜੇਕਰਿਸਕੀਐ॥","meaning":"ਹੇ ਭਾਈ! ਜੋ ਕੁਝ ਜਗਤ ਵਿਚ ਬਣਿਆ ਹੈ ਜੋ ਕੁਝ ਕਰ ਰਿਹਾ ਹੈ, ਇਹ ਸਭ ਰਜ਼ਾ ਦਾ ਮਾਲਕ ਪਰਮਾਤਮਾ ਕਰ ਰਿਹਾ ਹੈ । ਅਸੀ ਜੀਵ (ਤਾਂ ਹੀ) ਕੁਝ ਕਰੀਏ, ਜੇ ਕਰ ਸਕਦੇ ਹੋਵੀਏ ।"},{"gurmukhi":"ਆਪਣਾਕੀਤਾਕਿਛੂਨਹੋਵੈਜਿਉਹਰਿਭਾਵੈਤਿਉਰਖੀਐ॥੧॥","meaning":"ਅਸਾਂ ਜੀਵਾਂ ਦਾ ਕੀਤਾ ਕੁਝ ਨਹੀਂ ਹੋ ਸਕਦਾ । ਜਿਵੇਂ ਪਰਮਾਤਮਾ ਨੂੰ ਚੰਗਾ ਲੱਗਦਾ ਹੈ, ਤਿਵੇਂ ਜੀਵਾਂ ਨੂੰ ਰੱਖਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਮੇਰੇਹਰਿਜੀਉਸਭੁਕੋਤੇਰੈਵਸਿ॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ ਜੀ! ਹਰੇਕ ਜੀਵ ਤੇਰੇ ਵੱਸ ਵਿਚ ਹੈ ।"},{"gurmukhi":"ਅਸਾਜੋਰੁਨਾਹੀਜੇਕਿਛੁਕਰਿਹਮਸਾਕਹਜਿਉਭਾਵੈਤਿਵੈਬਖਸਿ॥੧॥ਰਹਾਉ॥","meaning":"ਅਸਾਂ ਜੀਵਾਂ ਵਿਚ ਕੋਈ ਸਮਰਥਾ ਨਹੀਂ ਹੈ ਕਿ (ਤੈਥੋਂ ਬਾਹਰਾ) ਕੁਝ ਕਰ ਸਕੀਏ । ਹੇ ਪ੍ਰਭੂ! ਜਿਵੇਂ ਤੈਨੂੰ ਚੰਗਾ ਲੱਗੇ, ਸਾਡੇ ਉਤੇ ਮੇਹਰ ਕਰ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਸਭੁਜੀਉਪਿੰਡੁਦੀਆਤੁਧੁਆਪੇਤੁਧੁਆਪੇਕਾਰੈਲਾਇਆ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਇਹ ਜਿੰਦ, ਇਹ ਸਰੀਰ, ਸਭ ਕੁਝ (ਹਰੇਕ ਜੀਵ ਨੂੰ) ਤੂੰ ਆਪ ਹੀ ਦਿੱਤਾ ਹੈ, ਤੂੰ ਆਪ ਹੀ (ਹਰੇਕ ਜੀਵ ­ਨੂੰ) ਕੰਮ ਵਿਚ ਲਾਇਆ ਹੋਇਆ ਹੈ ।"},{"gurmukhi":"ਜੇਹਾਤੂੰਹੁਕਮੁਕਰਹਿਤੇਹੇਕੋਕਰਮਕਮਾਵੈਜੇਹਾਤੁਧੁਧੁਰਿਲਿਖਿਪਾਇਆ॥੨॥","meaning":"ਜਿਹੋ ਜਿਹਾ ਹੁਕਮ ਤੂੰ ਕਰਦਾ ਹੈਂ, ਜੀਵ ਉਹੋ ਜਿਹਾ ਹੀ ਕੰਮ ਕਰਦਾ ਹੈ (ਜੀਵ ਉਹੋ ਜਿਹਾ ਬਣਦਾ ਹੈ) ਜਿਹੋ ਜਿਹਾ ਤੂੰ ਧੁਰ ਦਰਗਾਹ ਤੋਂ (ਉਸ ਦੇ ਮੱਥੇ ਉਤੇ) ਲੇਖ ਲਿਖ ਕੇ ਰੱਖ ਦਿੱਤਾ ਹੈ ।੨।"},{"gurmukhi":"ਪੰਚਤਤੁਕਰਿਤੁਧੁਸ੍ਰਿਸਟਿਸਭਸਾਜੀਕੋਈਛੇਵਾਕਰਿਉਜੇਕਿਛੁਕੀਤਾਹੋਵੈ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਪੰਜ ਤੱਤ ਬਣਾ ਕੇ ਸਾਰੀ ਦੁਨੀਆ ਪੈਦਾ ਕੀਤੀ ਹੈ । ਜੇ (ਤੈਥੋਂ ਬਾਹਰਾ) ਜੀਵ ਪਾਸੋਂ ਕੁਝ ਹੋ ਸਕਦਾ ਹੋਵੇ, ਤਾਂ ਉਹ ਬੇਸ਼ੱਕ ਛੇਵਾਂ ਤੱਤ ਬਣਾ ਕੇ ਵਿਖਾ ਦੇਵੇ ।"},{"gurmukhi":"ਇਕਨਾਸਤਿਗੁਰੁਮੇਲਿਤੂੰਬੁਝਾਵਹਿਇਕਿਮਨਮੁਖਿਕਰਹਿਸਿਰੋਵੈ॥੩॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਕਈ ਜੀਵਾਂ ਨੂੰ ਤੂੰ ਗੁਰੂ ਮਿਲਾ ਕੇ ਆਤਮਕ ਜੀਵਨ ਦੀ ਸੂਝ ਬਖ਼ਸ਼ਦਾ ਹੈਂ । ਕਈ ਜੀਵਾਂ ਨੂੰ ਤੂੰ ਆਪਣੇ ਹੀ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਨ ਵਾਲਾ ਬਣਾ ਦੇਂਦਾ ਹੈਂ । ਫਿਰ ਉਹ (ਆਪਣੇ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਨ ਵਾਲਾ ਮਨੁੱਖ) ਦੁੱਖੀ ਹੁੰਦਾ ਰਹਿੰਦਾ ਹੈ ।੩।"},{"gurmukhi":"ਹਰਿਕੀਵਡਿਆਈਹਉਆਖਿਨਸਾਕਾਹਉਮੂਰਖੁਮੁਗਧੁਨੀਚਾਣੁ॥","meaning":"ਹੇ ਭਾਈ! ਮੈਂ (ਤਾਂ) ਮੂਰਖ ਹਾਂ, ਨੀਵੇਂ ਜੀਵਨ ਵਾਲਾ ਹਾਂ, ਮੈਂ ਪਰਮਾਤਮਾ ਦੀ ਬਜ਼ੁਰਗੀ ਬਿਆਨ ਨਹੀਂ ਕਰ ਸਕਦਾ ।"},{"gurmukhi":"ਜਨਨਾਨਕਕਉਹਰਿਬਖਸਿਲੈਮੇਰੇਸੁਆਮੀਸਰਣਾਗਤਿਪਇਆਅਜਾਣੁ॥੪॥੪॥੧੫॥੨੪॥","meaning":"ਹੇ ਹਰੀ! ਦਾਸ ਨਾਨਕ ਉਤੇ ਮੇਹਰ ਕਰ, (ਇਹ) ਅੰਞਾਣ ਦਾਸ ਤੇਰੀ ਸਰਨ ਆ ਪਿਆ ਹੈ ।੪।੪।੧੫।੨੪।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (15, 'ਬਿਲਾਵਲੁਮਹਲਾ੫॥', '[{"gurmukhi":"ਗੁਰਿਪੂਰੈਮੇਰੀਰਾਖਿਲਈ॥","meaning":"ਹੇ ਭਾਈ! (ਵਿਕਾਰਾਂ ਦੇ ਟਾਕਰੇ ਤੇ) ਪੂਰੇ ਗੁਰੂ ਨੇ ਮੇਰੀ ਇੱਜ਼ਤ ਰੱਖ ਲਈ ਹੈ ।"},{"gurmukhi":"ਅੰਮ੍ਰਿਤਨਾਮੁਰਿਦੇਮਹਿਦੀਨੋਜਨਮਜਨਮਕੀਮੈਲੁਗਈ॥੧॥ਰਹਾਉ॥","meaning":"ਗੁਰੂ ਨੇ ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲਾ ਹਰਿ-ਨਾਮ ਮੇਰੇ ਹਿਰਦੇ ਵਿਚ ਵਸਾ ਦਿੱਤਾ ਹੈ, (ਉਸ ਨਾਮ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਅਨੇਕਾਂ ਜਨਮਾਂ ਦੇ ਕੀਤੇ ਕਰਮਾਂ ਦੀ ਮੈਲ ਮੇਰੇ ਮਨ ਵਿਚੋਂ ਦੂਰ ਹੋ ਗਈ ਹੈ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਨਿਵਰੇਦੂਤਦੁਸਟਬੈਰਾਈਗੁਰਪੂਰੇਕਾਜਪਿਆਜਾਪੁ॥","meaning":"ਹੇ ਭਾਈ! ਪੂਰੇ ਗੁਰੂ ਦਾ ਦੱਸਿਆ ਹੋਇਆ ਹਰਿ-ਨਾਮ ਦਾ ਜਾਪ ਜਦੋਂ ਤੋਂ ਮੈਂ ਜਪਣਾ ਸ਼ੁਰੂ ਕੀਤਾ ਹੈ, (ਕਾਮਾਦਿਕ) ਸਾਰੇ ਵੈਰੀ ਦੁਰਜਨ ਨੱਸ ਗਏ ਹਨ ।"},{"gurmukhi":"ਕਹਾਕਰੈਕੋਈਬੇਚਾਰਾਪ੍ਰਭਮੇਰੇਕਾਬਡਪਰਤਾਪੁ॥੧॥","meaning":"ਮੇਰੇ ਪ੍ਰਭੂ ਦੀ ਬੜੀ ਤਾਕਤ ਹੈ, ਹੁਣ (ਇਹਨਾਂ ਵਿਚੋਂ) ਕੋਈ ਭੀ ਮੇਰਾ ਕੁਝ ਵਿਗਾੜ ਨਹੀਂ ਸਕਦਾ ।੧।"},{"gurmukhi":"ਸਿਮਰਿਸਿਮਰਿਸਿਮਰਿਸੁਖੁਪਾਇਆਚਰਨਕਮਲਰਖੁਮਨਮਾਹੀ॥","meaning":"(ਹੇ ਭਾਈ! ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਪਰਮਾਤਮਾ ਦੇ ਸੋਹਣੇ ਚਰਨ) ਮੇਰੇ ਮਨ ਵਿਚ ਆਸਰਾ ਬਣ ਗਏ ਹਨ, ਉਸ ਦਾ ਨਾਮ (ਹਰ ਵੇਲੇ) ਸਿਮਰ ਸਿਮਰ ਕੇ ਮੈਂ ਆਤਮਕ ਆਨੰਦ ਪ੍ਰਾਪਤ ਕੀਤਾ ਹੈ ।"},{"gurmukhi":"ਤਾਕੀਸਰਨਿਪਰਿਓਨਾਨਕਦਾਸੁਜਾਤੇਊਪਰਿਕੋਨਾਹੀ॥੨॥੧੨॥੯੮॥","meaning":"ਹੇ ਭਾਈ! (ਪ੍ਰਭੂ ਦਾ) ਦਾਸ ਨਾਨਕ ਉਸ (ਪ੍ਰਭੂ) ਦੀ ਸਰਨ ਪੈ ਗਿਆ ਹੈ ਜਿਸ ਤੋਂ ਵੱਡਾ ਹੋਰ ਕੋਈ ਨਹੀਂ ।੨।੧੨।੯੮।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (16, 'ਸੂਹੀਮਹਲਾ੫॥', '[{"gurmukhi":"ਪਾਰਬ੍ਰਹਮਪਰਮੇਸਰਸਤਿਗੁਰਆਪੇਕਰਣੈਹਾਰਾ॥","meaning":"ਹੇ ਪਰਮਾਤਮਾ! ਹੇ ਪਰਮੇਸਰ! ਹੇ ਸਤਿਗੁਰ! ਤੂੰ ਆਪ ਹੀ ਸਭ ਕੁਝ ਕਰਨ ਦੇ ਸਮਰਥ ਹੈਂ"},{"gurmukhi":"ਚਰਣਧੂੜਿਤੇਰੀਸੇਵਕੁਮਾਗੈਤੇਰੇਦਰਸਨਕਉਬਲਿਹਾਰਾ॥੧॥","meaning":"(ਤੇਰਾ) ਦਾਸ (ਤੇਰੇ ਪਾਸੋਂ) ਤੇਰੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਮੰਗਦਾ ਹੈ, ਤੇਰੇ ਦਰਸਨ ਤੋਂ ਸਦਕੇ ਜਾਂਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਮੇਰੇਰਾਮਰਾਇਜਿਉਰਾਖਹਿਤਿਉਰਹੀਐ॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ-ਪਾਤਿਸ਼ਾਹ! ਤੂੰ ਜਿਵੇਂ (ਅਸਾਂ ਜੀਵਾਂ ਨੂੰ) ਰੱਖਦਾ ਹੈਂ, ਤਿਵੇਂ ਹੀ ਰਿਹਾ ਜਾ ਸਕਦਾ ਹੈ"},{"gurmukhi":"ਤੁਧੁਭਾਵੈਤਾਨਾਮੁਜਪਾਵਹਿਸੁਖੁਤੇਰਾਦਿਤਾਲਹੀਐ॥੧॥ਰਹਾਉ॥","meaning":"ਜੇ ਤੈਨੂੰ ਚੰਗਾ ਲੱਗੇ ਤਾਂ ਤੂੰ (ਅਸਾਂ ਜੀਵਾਂ ਪਾਸੋਂ ਆਪਣਾ) ਨਾਮ ਜਪਾਂਦਾ ਹੈਂ, ਤੇਰਾ ਹੀ ਬਖ਼ਸ਼ਿਆ ਹੋਇਆ ਸੁਖ ਅਸੀ ਲੈ ਸਕਦੇ ਹਾਂ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਮੁਕਤਿਭੁਗਤਿਜੁਗਤਿਤੇਰੀਸੇਵਾਜਿਸੁਤੂੰਆਪਿਕਰਾਇਹਿ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੇਰੀ ਸੇਵਾ-ਭਗਤੀ ਵਿਚ ਹੀ (ਵਿਕਾਰਾਂ ਤੋਂ) ਖ਼ਲਾਸੀ ਹੈ, ਸੰਸਾਰ ਦੇ ਸੁਖ ਹਨ, ਸੁਚੱਜੀ ਜੀਵਨ-ਜਾਚ ਹੈ (ਪਰ ਤੇਰੀ ਭਗਤੀ ਉਹੀ ਕਰਦਾ ਹੈ) ਜਿਸ ਪਾਸੋਂ ਤੂੰ ਆਪ ਕਰਾਂਦਾ ਹੈਂ"},{"gurmukhi":"ਤਹਾਬੈਕੁੰਠੁਜਹਕੀਰਤਨੁਤੇਰਾਤੂੰਆਪੇਸਰਧਾਲਾਇਹਿ॥੨॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜਿਸ ਥਾਂ ਤੇਰੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਹੋ ਰਹੀ ਹੋਵੇ, (ਮੇਰੇ ਵਾਸਤੇ) ਉਹੀ ਥਾਂ ਬੈਕੁੰਠ ਹੈ, ਤੰੂੰ ਆਪ ਹੀ (ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰਨ ਦੀ) ਸਰਧਾ (ਸਾਡੇ ਅੰਦਰ) ਪੈਦਾ ਕਰਦਾ ਹੈਂ ।੨।"},{"gurmukhi":"ਸਿਮਰਿਸਿਮਰਿਸਿਮਰਿਨਾਮੁਜੀਵਾਤਨੁਮਨੁਹੋਇਨਿਹਾਲਾ॥","meaning":"ਹੇ ਦੀਨਾਂ ਉਤੇ ਦਇਆ ਕਰਨ ਵਾਲੇ ਮੇਰੇ ਸਤਿਗੁਰ! (ਮੇਹਰ ਕਰ) ਮੈਂ ਤੇਰਾ ਨਾਮ ਜਪ ਜਪ ਕੇ ਆਤਮਕ ਜੀਵਨ ਹਾਸਲ ਕਰਦਾ ਰਹਾਂ, ਮੇਰਾ ਮਨ ਮੇਰਾ ਤਨ (ਤੇਰੇ ਨਾਮ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਖਿੜਿਆ ਰਹੇ"},{"gurmukhi":"ਚਰਣਕਮਲਤੇਰੇਧੋਇਧੋਇਪੀਵਾਮੇਰੇਸਤਿਗੁਰਦੀਨਦਇਆਲਾ॥੩॥","meaning":"ਮੇਹਰ ਕਰ) ਮੈਂ ਸਦਾ ਤੇਰੇ ਸੋਹਣੇ ਚਰਨ ਧੋ ਧੋ ਕੇ ਪੀਂਦਾ ਰਹਾਂ ।੩।"},{"gurmukhi":"ਕੁਰਬਾਣੁਜਾਈਉਸੁਵੇਲਾਸੁਹਾਵੀਜਿਤੁਤੁਮਰੈਦੁਆਰੈਆਇਆ॥","meaning":"(ਹੇ ਸਤਿਗੁਰੂ!) ਮੈਂ ਉਸ ਸੋਹਣੀ ਘੜੀ ਤੋਂ ਸਦਕੇ ਜਾਂਦਾ ਹਾਂ, ਜਦੋਂ ਮੈਂ ਤੇਰੇ ਦਰ ਤੇ ਆ ਡਿੱਗਾ"},{"gurmukhi":"ਨਾਨਕਕਉਪ੍ਰਭਭਏਕ੍ਰਿਪਾਲਾਸਤਿਗੁਰੁਪੂਰਾਪਾਇਆ॥੪॥੮॥੫੫॥","meaning":"ਹੇ ਭਾਈ! ਜਦੋਂ (ਦਾਸ) ਨਾਨਕ ਉਤੇ ਪ੍ਰਭੂ ਜੀ ਦਇਆਵਾਨ ਹੋਏ, ਤਦੋਂ (ਨਾਨਕ ਨੂੰ) ਪੂਰਾ ਗੁਰੂ ਮਿਲ ਪਿਆ ।੪।੮।੫੫।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (17, 'ਪਉੜੀ॥', '[{"gurmukhi":"ਮੇਲਿਲੈਹੁਦਇਆਲਢਹਿਪਏਦੁਆਰਿਆ॥","meaning":"ਹੇ ਦਿਆਲ! ਮੈਂ ਤੇਰੇ ਦਰ ਤੇ ਆ ਡਿੱਗਾ ਹਾਂ, ਮੈਨੂੰ (ਆਪਣੇ ਚਰਨਾਂ ਵਿਚ) ਜੋੜ ਲੈ"},{"gurmukhi":"ਰਖਿਲੇਵਹੁਦੀਨਦਇਆਲਭ੍ਰਮਤਬਹੁਹਾਰਿਆ॥","meaning":"। ਹੇ ਦੀਨਾਂ ਤੇ ਦਇਆ ਕਰਨ ਵਾਲੇ! ਮੈਨੂੰ ਰੱਖ ਲੈ, ਮੈਂ ਭਟਕਦਾ ਭਟਕਦਾ ਹੁਣ ਬੜਾ ਥੱਕ ਗਿਆ ਹਾਂ"},{"gurmukhi":"ਭਗਤਿਵਛਲੁਤੇਰਾਬਿਰਦੁਹਰਿਪਤਿਤਉਧਾਰਿਆ॥","meaning":"ਭਗਤੀ ਨੂੰ ਪਿਆਰ ਕਰਨਾ ਤੇ ਡਿੱਗਿਆਂ ਨੂੰ ਬਚਾਉਣਾ—ਇਹ ਤੇਰਾ ਮੁੱਢ ਕਦੀਮਾਂ ਦਾ ਸੁਭਾਉ ਹੈ"},{"gurmukhi":"ਤੁਝਬਿਨੁਨਾਹੀਕੋਇਬਿਨਉਮੋਹਿਸਾਰਿਆ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੈਥੋਂ ਬਿਨਾ ਹੋਰ ਕੋਈ ਨਹੀਂ ਜੋ ਮੇਰੀ ਇਸ ਬੇਨਤੀ ਨੂੰ ਸਿਰੇ ਚਾੜ੍ਹ ਸਕ"},{"gurmukhi":"ਕਰੁਗਹਿਲੇਹੁਦਇਆਲਸਾਗਰਸੰਸਾਰਿਆ॥੧੬॥","meaning":"ਹੇ ਦਿਆਲ! ਮੇਰਾ ਹੱਥ ਫੜ ਲੈ (ਤੇ ਮੈਨੂੰ) ਸੰਸਾਰ-ਸਮੁੰਦਰ ਵਿਚੋਂ (ਬਚਾ ਲੈ) ।੧੬।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (18, 'ਬਿਲਾਵਲੁਮਹਲਾ੫॥', '[{"gurmukhi":"ਤੁਮ੍ਹਸਮਰਥਾਕਾਰਨਕਰਨ॥","meaning":"ਹੇ ਮੇਰੇ ਗੋਬਿੰਦ! ਹੇ ਮੇਰੇ ਸਭ ਤੋਂ ਵੱਡੇ (ਮਾਲਕ)! ਤੂੰ ਸਭ ਤਾਕਤਾਂ ਦਾ ਮਾਲਕ ਹੈਂ, ਤੂੰ ਜਗਤ ਦਾ ਰਚਨਹਾਰ ਹੈਂ,"},{"gurmukhi":"ਢਾਕਨਢਾਕਿਗੋਬਿਦਗੁਰਮੇਰੇਮੋਹਿਅਪਰਾਧੀਸਰਨਚਰਨ॥੧॥ਰਹਾਉ॥","meaning":"ਮੇਰਾ ਪਰਦਾ ਢੱਕ ਲੈ, ਮੈਂ ਪਾਪੀ ਤੇਰੇ ਚਰਨਾਂ ਦੀ ਸਰਨ ਆਇਆ ਹਾਂ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਜੋਜੋਕੀਨੋਸੋਤੁਮ੍ਹਜਾਨਿਓਪੇਖਿਓਠਉਰਨਾਹੀਕਛੁਢੀਠਮੁਕਰਨ॥","meaning":"ਜੋ ਕੁਝ ਮੈਂ ਨਿੱਤ ਕਰਦਾ ਰਹਿੰਦਾ ਹਾਂ, ਹੇ ਪ੍ਰਭੂ! ਉਹ ਤੂੰ ਸਭ ਕੁਝ ਜਾਣਦਾ ਹੈਂ ਅਤੇ ਵੇਖਦਾ ਹੈਂ, (ਇਹਨਾਂ ਕਰਤੂਤਾਂ ਤੋਂ) ਮੈਨੂੰ ਢੀਠ ਨੂੰ ਮੁੱਕਰਨ ਦੀ ਕੋਈ ਗੁੰਜੈਸ਼ ਨਹੀਂ, (ਫਿਰ ਭੀ ਮੈਂ ਕਰੀ ਭੀ ਜਾਂਦਾ ਹਾਂ, ਤੇ ਲੁਕਾਂਦਾ ਭੀ ਹਾਂ) ।"},{"gurmukhi":"ਬਡਪਰਤਾਪੁਸੁਨਿਓਪ੍ਰਭਤੁਮ੍ਹਰੋਕੋਟਿਅਘਾਤੇਰੋਨਾਮਹਰਨ॥੧॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੈਂ ਸੁਣਿਆ ਹੈ ਕਿ ਤੂੰ ਬੜੀ ਸਮਰੱਥਾ ਵਾਲਾ ਹੈਂ, ਤੇਰਾ ਨਾਮ ਕੋ੍ਰੜਾਂ ਪਾਪ ਦੂਰ ਕਰ ਸਕਦਾ ਹੈ (ਮੈਨੂੰ ਭੀ ਆਪਣਾ ਨਾਮ ਬਖ਼ਸ਼) ।੧।"},{"gurmukhi":"ਹਮਰੋਸਹਾਉਸਦਾਸਦਭੂਲਨਤੁਮ੍ਹਰੋਬਿਰਦੁਪਤਿਤਉਧਰਨ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਅਸਾਂ ਜੀਵ ਦਾ ਸੁਭਾਉ ਹੀ ਹੈ ਨਿੱਤ ਭੁੱਲਾਂ ਕਰਦੇ ਰਹਿਣਾ । ਤੇਰਾ ਮੁੱਢ-ਕਦੀਮਾਂ ਦਾ ਸੁਭਾਉ ਹੈ ਵਿਕਾਰੀਆਂ ਨੂੰ ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਾਣਾ ।"},{"gurmukhi":"ਕਰੁਣਾਮੈਕਿਰਪਾਲਕ੍ਰਿਪਾਨਿਧਿਜੀਵਨਪਦਨਾਨਕਹਰਿਦਰਸਨ॥੨॥੨॥੧੧੮॥","meaning":"ਹੇ ਤਰਸ ਦੇ ਸੋਮੇ! ਹੇ ਕਿਰਪਾਲ! ਹੇ ਕਿਰਪਾ ਦੇ ਖ਼ਜ਼ਾਨੇ! ਨਾਨਕ ਨੂੰ ਆਪਣਾ ਦਰਸਨ ਦੇਹ, ਤੇਰਾ ਦਰਸਨ ਉੱਚੇ ਆਤਮਕ ਜੀਵਨ ਦਾ ਦਰਜਾ ਬਖ਼ਸ਼ਣ ਵਾਲਾ ਹੈ ।੨।੨।੧੧੮।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (19, 'ਚੰਡੀਦੀਵਾਰ॥', '[{"gurmukhi":"ਚੰਡੀ ਦੀ ਵਾਰ:","meaning":""},{"gurmukhi":"ੴਵਾਹਿਗੁਰੂਜੀਕੀਫਤਹ॥","meaning":"ੴ ਸ੍ਰੀ ਵਾਹਿਗੁਰੂ ਜੀ ਕੀ ਫਤਹ:"},{"gurmukhi":"ਸ੍ਰੀਭਗਉਤੀਜੀਸਹਾਇ॥","meaning":"ਸ੍ਰੀ ਭਗਉਤੀ ਜੀ ਸਹਾਇ:"},{"gurmukhi":"ਵਾਰਸ੍ਰੀਭਗਉਤੀਜੀਕੀ॥","meaning":"ਹੁਣ ਵਾਰ ਸ੍ਰੀ ਭਗਉਤੀ ਜੀ ਕੀ ਲਿਖਦੇ ਹਾ:"},{"gurmukhi":"ਪਾਤਿਸਾਹੀ੧੦॥","meaning":""},{"gurmukhi":"ਪਾਤਸ਼ਾਹੀ ੧੦:","meaning":""},{"gurmukhi":"ਪਉੜੀ॥","meaning":""},{"gurmukhi":"ਪਉੜੀ:","meaning":""},{"gurmukhi":"ਪ੍ਰਿਥਮਭਗੌਤੀਸਿਮਰਿਕੈਗੁਰਨਾਨਕਲਈਂਧਿਆਇ॥","meaning":"(ਸਭ ਤੋਂ) ਪਹਿਲਾ ਭਗੌਤੀ ਨੂੰ ਸਿਮਰਦਾ ਹਾ ਅਤੇ ਫਿਰ ਗੁਰੂ ਨਾਨਕ ਦੇਵ ਨੂੰ ਯਾਦ ਕਰਦਾ ਹਾ।"},{"gurmukhi":"ਫਿਰਅੰਗਦਗੁਰਤੇਅਮਰਦਾਸੁਰਾਮਦਾਸੈਹੋਈਂਸਹਾਇ॥","meaning":"(ਫਿਰ) ਗੁਰੂ ਅੰਗਦ, (ਗੁਰੂ) ਅਮਰਦਾਸ ਅਤੇ (ਗੁਰੂ) ਰਾਮਦਾਸ (ਨੂੰ ਸਿਮਰਦਾ ਹਾ ਕਿ ਮੇਰੇ) ਸਹਾਈ ਹੋਣ।"},{"gurmukhi":"ਅਰਜਨਹਰਿਗੋਬਿੰਦਨੋਸਿਮਰੌਸ੍ਰੀਹਰਿਰਾਇ॥","meaning":"(ਗੁਰੂ) ਅਰਜਨ ਦੇਵ, (ਗੁਰੂ) ਹਰਿਗੋਬਿੰਦ ਅਤੇ (ਗੁਰੂ) ਸ੍ਰੀ ਹਰਿ ਰਾਇ ਨੂੰ ਸਿਮਰਦਾ ਹਾ।"},{"gurmukhi":"ਸ੍ਰੀਹਰਿਕ੍ਰਿਸ਼ਨਧਿਆਈਐਜਿਸੁਡਿਠੇਸਭਿਦੁਖਿਜਾਇ॥","meaning":"(ਫਿਰ ਗੁਰੂ) ਸ੍ਰੀ ਹਰਿਕ੍ਰਿਸ਼ਨ ਨੂੰ ਆਰਾਧਦਾ ਹਾ ਜਿਨ੍ਰਹਾ ਦੇ ਦਰਸ਼ਨ ਕਰਨ ਨਾਲ ਸਾਰੇ ਦੁਖ ਦੂਰ ਹੋ ਜਾਦੇ ਹਨ।"},{"gurmukhi":"ਤੇਗਬਹਾਦਰਸਿਮਰਿਐਘਰਿਨਉਨਿਧਿਆਵੈਧਾਇ॥","meaning":"(ਗੁਰੂ) ਤੇਗ ਬਹਾਦਰ ਦੇ ਸਿਮਰਨ ਨਾਲ ਨੌ ਨਿੱਧਾ (ਖ਼ਜ਼ਾਨੇ) (ਘਰ ਵਿਚ) ਭਜਦੀਆਂ ਚਲੀਆਂ ਆਉਾਂਦੀਆਂ ਹਨ।"},{"gurmukhi":"ਸਭਥਾਈਂਹੋਇਸਹਾਇ॥੧॥","meaning":"(ਸਾਰੇ ਗੁਰੂ ਮੈਨੂੰ) ਸਭ ਥਾਈਂ ਸਹਾਇਕ ਹੋਣ ॥੧॥"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (20, 'ਕਾਨੜਾਮਹਲਾ੫॥', '[{"gurmukhi":"ਕੀਰਤਿਪ੍ਰਭਕੀਗਾਉਮੇਰੀਰਸਨਾਂ॥","meaning":"ਹੇ ਮੇਰੀ ਜੀਭ! ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੇ ਗੀਤ ਗਾਇਆ ਕਰ"},{"gurmukhi":"ਅਨਿਕਬਾਰਕਰਿਬੰਦਨਸੰਤਨਊਹਾਂਚਰਨਗੋਬਿੰਦਜੀਕੇਬਸਨਾ॥੧॥ਰਹਾਉ॥","meaning":"। ਹੇ ਭਾਈ! ਸੰਤ-ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਉਤੇ ਅਨੇਕਾਂ ਵਾਰੀ ਨਮਸਕਾਰ ਕਰਿਆ ਕਰ, ਸੰਤ ਜਨਾਂ ਦੇ ਹਿਰਦੇ ਵਿਚ ਸਦਾ ਪਰਮਾਤਮਾ ਦੇ ਚਰਨ ਵੱਸਦੇ ਹਨ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਅਨਿਕਭਾਂਤਿਕਰਿਦੁਆਰੁਨਪਾਵਉ॥","meaning":"ਹੇ ਭਾਈ! ਅਨੇਕਾਂ ਢੰਗ ਵਰਤ ਕੇ ਭੀ ਮੈਂ ਪਰਮਾਤਮਾ ਦਾ ਦਰ ਨਹੀਂ ਲੱਭ ਸਕਦਾ"},{"gurmukhi":"ਹੋਇਕ੍ਰਿਪਾਲੁਤਹਰਿਹਰਿਧਿਆਵਉ॥੧॥","meaning":"। ਜੇ ਪਰਮਾਤਮਾ ਆਪ ਹੀ ਦਇਵਾਨ ਹੋਵੇ ਤਾਂ ਮੈਂ ਉਸ ਦਾ ਧਿਆਨ ਧਰ ਸਕਦਾ ਹਾਂ ।੧।"},{"gurmukhi":"ਕੋਟਿਕਰਮਕਰਿਦੇਹਨਸੋਧਾ॥","meaning":"ਹੇ ਭਾਈ! (ਤੀਰਥ-ਯਾਤ੍ਰਾ ਆਦਿਕ) ਕੋ੍ਰੜਾਂ ਹੀ (ਮਿਥੇ ਹੋਏ ਧਾਰਮਿਕ) ਕਰਮ ਕਰ ਕੇ (ਮਨੁੱਖ ਦਾ) ਸਰੀਰ ਪਵਿੱਤਰ ਨਹੀਂ ਹੋ ਸਕਦਾ"},{"gurmukhi":"ਸਾਧਸੰਗਤਿਮਹਿਮਨੁਪਰਬੋਧਾ॥੨॥","meaning":"ਮਨੁੱਖ ਦਾ ਮਨ ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਹੀ (ਮਾਇਆ ਦੇ ਮੋਹ ਦੀ ਨੀਂਦ ਵਿਚੋਂ) ਜਾਗਦਾ ਹੈ ।੨।"},{"gurmukhi":"ਤ੍ਰਿਸਨਨਬੂਝੀਬਹੁਰੰਗਮਾਇਆ॥","meaning":"ਹੇ ਭਾਈ! (ਕੋ੍ਰੜਾਂ ਕਰਮ ਕਰ ਕੇ ਭੀ ਇਸ) ਬਹੁ-ਰੰਗੀ ਮਾਇਆ ਦੀ ਤ੍ਰਿਸ਼ਨਾ ਨਹੀਂ ਮਿਟਦੀ"},{"gurmukhi":"ਨਾਮੁਲੈਤਸਰਬਸੁਖਪਾਇਆ॥੩॥","meaning":"ਪਰ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰਦਿਆਂ ਸਾਰੇ ਸੁਖ ਮਿਲ ਜਾਂਦੇ ਹਨ ।੩।"},{"gurmukhi":"ਪਾਰਬ੍ਰਹਮਜਬਭਏਦਇਆਲ॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—(ਹੇ ਭਾਈ!) ਜਦੋਂ (ਕਿਸੇ ਪ੍ਰਾਣੀ ਉੱਤੇ) ਪ੍ਰਭੂ ਜੀ ਦਇਆਵਾਨ ਹੁੰਦੇ ਹਨ,"},{"gurmukhi":"ਕਹੁਨਾਨਕਤਉਛੂਟੇਜੰਜਾਲ॥੪॥੩॥","meaning":"ਤਦੋਂ (ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰ ਕੇ ਉਸ ਮਨੁੱਖ ਦੀਆਂ) ਮਾਇਆ ਦੇ ਮੋਹ ਦੀਆਂ (ਸਾਰੀਆਂ) ਫਾਹੀਆਂ ਟੁੱਟ ਜਾਂਦੀਆਂ ਹਨ ।੪।੩।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (21, 'ਸੋਰਠਿਮਹਲਾ੫॥', '[{"gurmukhi":"ਸੁਨਹੁਬਿਨੰਤੀਠਾਕੁਰਮੇਰੇਜੀਅਜੰਤਤੇਰੇਧਾਰੇ॥","meaning":"ਹੇ ਮੇਰੇ ਠਾਕੁਰ! ਹੇ ਸਭ ਕੁਝ ਕਰ ਸਕਣ ਤੇ ਕਰਾ ਸਕਣ ਵਾਲੇ ਪ੍ਰਭੂ! (ਮੇਰੀ) ਬੇਨਤੀ ਸੁਣ । ਸਾਰੇ ਨਿੱਕੇ ਵੱਡੇ ਜੀਵ ਤੇਰੇ ਹੀ ਆਸਰੇ ਹਨ"},{"gurmukhi":"ਰਾਖੁਪੈਜਨਾਮਅਪੁਨੇਕੀਕਰਨਕਰਾਵਨਹਾਰੇ॥੧॥","meaning":"ਅਸੀ ਜੀਵ ਤੇਰੇ ਹੀ ਆਸਰੇ ਹਾਂ) ਤੂੰ ਆਪਣੇ (ਇਸ) ਨਾਮ ਦੀ ਲਾਜ ਰੱਖ (ਤੇ, ਸਾਡੇ ਮਾਇਆ ਦੇ ਬੰਧਨ ਕੱਟ)"},{"gurmukhi":"ਪ੍ਰਭਜੀਉਖਸਮਾਨਾਕਰਿਪਿਆਰੇ॥","meaning":"ਹੇ ਪਿਆਰੇ ਪ੍ਰਭੂ ਜੀ! (ਤੂੰ ਸਾਡਾ ਖਸਮ ਹੈਂ) ਖਸਮ ਵਾਲਾ ਫ਼ਰਜ਼ ਪੂਰਾ ਕਰ"},{"gurmukhi":"ਬੁਰੇਭਲੇਹਮਥਾਰੇ॥ਰਹਾਉ॥","meaning":"(ਚਾਹੇ ਅਸੀ) ਭੈੜੇ ਹਾਂ (ਚਾਹੇ ਅਸੀ) ਚੰਗੇ ਹਾਂ, ਅਸੀ ਤੇਰੇ ਹੀ ਹਾਂ (ਸਾਡੇ ਵਿਕਾਰਾਂ ਦੇ ਬੰਧਨ ਕੱਟ ਦੇ) ।ਰਹਾਉ।"},{"gurmukhi":"ਸੁਣੀਪੁਕਾਰਸਮਰਥਸੁਆਮੀਬੰਧਨਕਾਟਿਸਵਾਰੇ॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—ਹੇ ਭਾਈ! ਜਿਨ੍ਹਾਂ ਸੇਵਕਾਂ ਦੀ) ਪੁਕਾਰ ਸਭ ਤਾਕਤਾਂ ਦੇ ਮਾਲਕ ਪ੍ਰਭੂ ਨੇ ਸੁਣ ਲਈ, ਉਹਨਾਂ ਦੇ (ਮਾਇਆ ਦੇ) ਬੰਧਨ ਕੱਟ ਕੇ ਪ੍ਰਭੂ ਨੇ ਉਹਨਾਂ ਦੇ ਜੀਵਨ ਸੋਹਣੇ ਬਣਾ ਦਿੱਤੇ"},{"gurmukhi":"ਪਹਿਰਿਸਿਰਪਾਉਸੇਵਕਜਨਮੇਲੇਨਾਨਕਪ੍ਰਗਟਪਹਾਰੇ॥੨॥੨੯॥੯੩॥","meaning":"ਉਹਨਾਂ ਸੇਵਕਾਂ ਨੂੰ ਦਾਸਾਂ ਨੂੰ ਆਦਰ-ਮਾਣ ਦੇ ਕੇ ਆਪਣੇ ਚਰਨਾਂ ਵਿਚ ਮਿਲਾ ਲਿਆ, ਤੇ, ਸੰਸਾਰ ਵਿਚ ਉੱਘੇ ਕਰ ਦਿੱਤਾ ।੨।੨੯।੯੩।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (22, 'ਬਿਲਾਵਲੁ॥', '[{"gurmukhi":"ਗ੍ਰਿਹੁਤਜਿਬਨਖੰਡਜਾਈਐਚੁਨਿਖਾਈਐਕੰਦਾ॥","meaning":"ਜੇ ਗ੍ਰਿਹਸਤ ਤਿਆਗ ਕੇ ਜੰਗਲਾਂ ਵਿਚ ਚਲੇ ਜਾਈਏ, ਤੇ ਗਾਜਰ ਮੂਲੀ ਆਦਿਕ ਖਾ ਕੇ ਗੁਜ਼ਾਰਾ ਕਰੀਏ,"},{"gurmukhi":"ਅਜਹੁਬਿਕਾਰਨਛੋਡਈਪਾਪੀਮਨੁਮੰਦਾ॥੧॥","meaning":"ਤਾਂ ਭੀ ਇਹ ਪਾਪੀ ਚੰਦਰਾ ਮਨ ਵਿਕਾਰ ਨਹੀਂ ਛੱਡਦਾ ।੧।"},{"gurmukhi":"ਕਿਉਛੂਟਉਕੈਸੇਤਰਉਭਵਜਲਨਿਧਿਭਾਰੀ॥","meaning":"ਮੈਂ ਕਿਵੇਂ ਇਹਨਾਂ ਤੋਂ ਖ਼ਲਾਸੀ ਕਰਾਵਾਂ? ਇਹ ਸੰਸਾਰ ਬੜਾ ਵੱਡਾ ਸਮੁੰਦਰ ਹੈ, ਮੈਂ ਕਿਵੇਂ ਇਸ ਤੋਂ ਪਾਰ ਲੰਘਾਂ?"},{"gurmukhi":"ਰਾਖੁਰਾਖੁਮੇਰੇਬੀਠੁਲਾਜਨੁਸਰਨਿਤੁਮ੍ਹਾਰੀ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ! ਮੈਂ ਤੇਰਾ ਦਾਸ ਤੇਰੀ ਸ਼ਰਨ ਆਇਆ ਹਾਂ, ਮੈਨੂੰ (ਇਹਨਾਂ ਵਿਕਾਰਾਂ ਤੋਂ) ਬਚਾ । ੧।ਰਹਾਉ।"},{"gurmukhi":"ਬਿਖੈਬਿਖੈਕੀਬਾਸਨਾਤਜੀਅਨਹਜਾਈ॥","meaning":"ਹੇ ਮੇਰੇ ਬੀਠਲ! ਮੈਥੋਂ ਇਹਨਾਂ ਅਨੇਕਾਂ ਕਿਸਮਾਂ ਦੇ ਵਿਸ਼ਿਆਂ ਦੇ ਚਸਕੇ ਛੱਡੇ ਨਹੀਂ ਜਾ ਸਕਦੇ ।"},{"gurmukhi":"ਅਨਿਕਜਤਨਕਰਿਰਾਖੀਐਫਿਰਿਫਿਰਿਲਪਟਾਈ॥੨॥","meaning":"ਕਈ ਜਤਨ ਕਰ ਕੇ ਇਸ ਮਨ ਨੂੰ ਰੋਕੀਦਾ ਹੈ, ਪਰ ਇਹ ਮੁੜ ਮੁੜ ਵਿਸ਼ਿਆਂ ਦੀਆਂ ਵਾਸ਼ਨਾਂ ਨੂੰ ਜਾ ਚੰਬੜਦਾ ਹੈ ।੨।"},{"gurmukhi":"ਜਰਾਜੀਵਨਜੋਬਨੁਗਇਆਕਿਛੁਕੀਆਨਨੀਕਾ॥","meaning":"ਬੁਢੇਪਾ ਆ ਗਿਆ ਹੈ, ਜੁਆਨੀ ਦੀ ਉਮਰ ਲੰਘ ਗਈ ਹੈ, ਪਰ ਮੈਂ ਹੁਣ ਤਕ ਕੋਈ ਚੰਗਾ ਕੰੰਮ ਨਹੀਂ ਕੀਤਾ ।"},{"gurmukhi":"ਇਹੁਜੀਅਰਾਨਿਰਮੋਲਕੋਕਉਡੀਲਗਿਮੀਕਾ॥੩॥","meaning":"ਮੇਰੀ ਇਹ ਜਿੰਦ ਅਮੋਲਕ ਸੀ, ਪਰ ਮੈਂ ਇਸ ਨੂੰ ਕੌਡੀ ਦੇ ਬਰਾਬਰ ਕਰ ਦਿੱਤਾ ਹੈ ।੩।"},{"gurmukhi":"ਕਹੁਕਬੀਰਮੇਰੇਮਾਧਵਾਤੂਸਰਬਬਿਆਪੀ॥","meaning":"ਹੇ ਕਬੀਰ! (ਆਪਣੇ ਪ੍ਰਭੂ ਅੱਗੇ ਇਉਂ) ਬੇਨਤੀ ਕਰ—ਹੇ ਪਿਆਰੇ ਪ੍ਰਭੂ! ਤੂੰ ਸਭ ਜੀਆਂ ਵਿਚ ਵਿਆਪਕ ਹੈਂ ।"},{"gurmukhi":"ਤੁਮਸਮਸਰਿਨਾਹੀਦਇਆਲੁਮੋਹਿਸਮਸਰਿਪਾਪੀ॥੪॥੩॥","meaning":"ਤੇਰੇ ਜੇਡਾ ਕੋਈ ਦਇਆ ਕਰਨ ਵਾਲਾ ਨਹੀਂ, ਤੇ ਮੇਰੇ ਵਰਗਾ ਕੋਈ ਪਾਪੀ ਨਹੀਂ (ਸੋ, ਮੈਨੂੰ ਤੂੰ ਆਪ ਹੀ ਇਹਨਾਂ ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਾ) ।੪।੩।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (23, 'ਰਾਗੁਧਨਾਸਰੀਮਹਲਾ੫', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਹਾਹਾਪ੍ਰਭਰਾਖਿਲੇਹੁ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਸਾਨੂੰ ਬਚਾ ਲੈ, ਸਾਨੂੰ ਬਚਾ ਲੈ"},{"gurmukhi":"ਹਮਤੇਕਿਛੂਨਹੋਇਮੇਰੇਸ੍ਵਾਮੀਕਰਿਕਿਰਪਾਅਪੁਨਾਨਾਮੁਦੇਹੁ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਮੇਰੇ ਮਾਲਕ! (ਇਹਨਾਂ ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਣ ਲਈ) ਅਸਾਂ ਜੀਵਾਂ ਪਾਸੋਂ ਕੁਝ ਨਹੀਂ ਹੋ ਸਕਦਾ! ਮੇਹਰ ਕਰ, ਆਪਣਾ ਨਾਮ ਬਖ਼ਸ਼ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਅਗਨਿਕੁਟੰਬਸਾਗਰਸੰਸਾਰ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਇਹ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਪਰਵਾਰ (ਦੇ ਮੋਹ) ਦੀ ਅੱਗ (ਨਾਲ ਭਰਿਆ ਹੋਇਆ) ਹੈ"},{"gurmukhi":"ਭਰਮਮੋਹਅਗਿਆਨਅੰਧਾਰ॥੧॥","meaning":"ਭਟਕਣਾ, ਮਾਇਆ ਦਾ ਮੋਹ, ਆਤਮਕ ਜੀਵਨ ਵਲੋਂ ਬੇ-ਸਮਝੀ—ਇਹ ਸਾਰੇ ਘੱੁਪ ਹਨੇਰੇ ਪਏ ਹੋਏ ਹਨ ।੧।"},{"gurmukhi":"ਊਚਨੀਚਸੂਖਦੂਖ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਦੁਨੀਆ ਦੇ ਸੁਖ ਮਿਲਣ ਤੇ ਜੀਵ ਨੂੰ ਅਹੰਕਾਰ ਪੈਦਾ ਹੋ ਜਾਂਦਾ ਹੈ, ਦੁੱਖ ਮਿਲਣ ਤੇ ਨਿੱਘਰੀ ਹੋਈ ਹਾਲਤ ਬਣ ਜਾਂਦੀ ਹੈ ।"},{"gurmukhi":"ਧ੍ਰਾਪਸਿਨਾਹੀਤ੍ਰਿਸਨਾਭੂਖ॥੨॥","meaning":"ਜੀਵ (ਮਾਇਆ ਵਲੋਂ ਕਿਸੇ ਵੇਲੇ) ਰੱਜਦਾ ਨਹੀਂ, ਇਸ ਨੂੰ ਮਾਇਆ ਦੀ ਤ੍ਰੇਹ ਮਾਇਆ ਦੀ ਭੱੁਖ ਚੰਬੜੀ ਰਹਿੰਦੀ ਹੈ ।੨।"},{"gurmukhi":"ਮਨਿਬਾਸਨਾਰਚਿਬਿਖੈਬਿਆਧਿ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜੀਵ ਆਪਣੇ ਮਨ ਵਿਚ ਵਾਸਨਾ ਖੜੀਆਂ ਕਰ ਕੇ ਵਿਸ਼ੇ-ਵਿਕਾਰਾਂ ਦੇ ਕਾਰਨ ਰੋਗ ਸਹੇੜ ਲੈਂਦਾ ਹੈ"},{"gurmukhi":"ਪੰਚਦੂਤਸੰਗਿਮਹਾਅਸਾਧ॥੩॥","meaning":"ਇਹ ਵੱਡੇ ਆਕੀ (ਕਾਮਾਦਿਕ) ਪੰਜ ਵੈਰੀ ਇਸ ਦੇ ਨਾਲ ਚੰਬੜੇ ਰਹਿੰਦੇ ਹਨ ।੩।"},{"gurmukhi":"ਜੀਅਜਹਾਨੁਪ੍ਰਾਨਧਨੁਤੇਰਾ॥","meaning":"ਇਹ ਸਾਰੇ ਜੀਵ, ਇਹ ਜਗਤ, ਇਹ ਧਨ, ਜੀਵਾਂ ਦੇ ਪ੍ਰਾਣ—ਇਹ ਸਭ ਕੁਝ ਤੇਰਾ ਹੀ ਰਚਿਆ ਹੋਇਆ ਹੈ (ਤੂੰ ਹੀ ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਾਣ ਦੇ ਸਮਰਥ ਹੈਂ) ।੪।੧।੧੯।"},{"gurmukhi":"ਨਾਨਕਜਾਨੁਸਦਾਹਰਿਨੇਰਾ॥੪॥੧॥੧੯॥","meaning":"ਹੇ ਨਾਨਕ! (ਜੇ ਇਹਨਾਂ ਵੈਰੀਆਂ ਤੋਂ ਬਚਣਾ ਹੈ, ਤਾਂ) ਪਰਮਾਤਮਾ ਨੂੰ ਸਦਾ ਆਪਣੇ ਅੰਗ-ਸੰਗ ਵੱਸਦਾ ਸਮਝ (ਉਸ ਦੇ ਅੱਗੇ ਅਰਦਾਸ ਕਰਿਆ ਕਰ—ਹੇ ਪ੍ਰਭੂ!)"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (24, 'ਸੋਰਠਿਮਹਲਾ੫॥', '[{"gurmukhi":"ਹਮਸੰਤਨਕੀਰੇਨੁਪਿਆਰੇਹਮਸੰਤਨਕੀਸਰਣਾ॥","meaning":"ਹੇ ਪਿਆਰੇ ਪ੍ਰਭੂ! (ਮੇਹਰ ਕਰ) ਮੈਂ ਤੇਰੇ ਸੰਤ ਜਨਾਂ ਦੀ ਚਰਨ-ਧੂੜ ਬਣਿਆ ਰਹਾਂ, ਸੰਤ ਜਨਾਂ ਦੀ ਸਰਨ ਪਿਆ ਰਹਾਂ ।"},{"gurmukhi":"ਸੰਤਹਮਾਰੀਓਟਸਤਾਣੀਸੰਤਹਮਾਰਾਗਹਣਾ॥੧॥","meaning":"ਸੰਤ ਹੀ ਮੇਰਾ ਤਕੜਾ ਸਹਾਰਾ ਹਨ, ਸੰਤ ਜਨ ਹੀ ਮੇਰੇ ਜੀਵਨ ਨੂੰ ਸੋਹਣਾ ਬਣਾਣ ਵਾਲੇ ਹਨ ।੧।"},{"gurmukhi":"ਹਮਸੰਤਨਸਿਉਬਣਿਆਈ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੇਰੇ ਸੰਤਾਂ ਨਾਲ ਮੇਰੀ ਪ੍ਰੀਤਿ ਬਣ ਗਈ ਹੈ ।"},{"gurmukhi":"ਪੂਰਬਿਲਿਖਿਆਪਾਈ॥","meaning":"ਪਿਛਲੇ ਲਿਖੇ ਲੇਖ ਅਨੁਸਾਰ ਇਹ ਪ੍ਰਾਪਤੀ ਹੋਈ ਹੈ ।"},{"gurmukhi":"ਇਹੁਮਨੁਤੇਰਾਭਾਈ॥ਰਹਾਉ॥","meaning":"ਹੁਣ ਮੇਰਾ ਇਹ ਮਨ ਤੇਰਾ ਪ੍ਰੇਮੀ ਬਣ ਗਿਆ ਹੈ ।ਰਹਾਉ।"},{"gurmukhi":"ਸੰਤਨਸਿਉਮੇਰੀਲੇਵਾਦੇਵੀਸੰਤਨਸਿਉਬਿਉਹਾਰਾ॥","meaning":"(ਹੇ ਪ੍ਰਭੂ! ਤੇਰੀ ਮੇਹਰ ਨਾਲ) ਸੰਤ ਜਨਾਂ ਨਾਲ ਹੀ ਮੇਰਾ ਲੈਣ-ਦੇਣ ਤੇ ਵਰਤਣ-ਵਿਹਾਰ ਹੈ ।"},{"gurmukhi":"ਸੰਤਨਸਿਉਹਮਲਾਹਾਖਾਟਿਆਹਰਿਭਗਤਿਭਰੇਭੰਡਾਰਾ॥੨॥","meaning":"ਸੰਤ ਜਨਾਂ ਨਾਲ ਰਹਿ ਕੇ ਮੈਂ ਇਹ ਲਾਭ ਖੱਟਿਆ ਹੈ ਕਿ ਮੇਰੇ ਅੰਦਰ ਭਗਤੀ ਦੇ ਖ਼ਜ਼ਾਨੇ ਭਰ ਗਏ ਹਨ ।੨।"},{"gurmukhi":"ਸੰਤਨਮੋਕਉਪੂੰਜੀਸਉਪੀਤਉਉਤਰਿਆਮਨਕਾਧੋਖਾ॥","meaning":"ਹੇ ਭਾਈ! ਜਦੋਂ ਤੋਂ ਸੰਤ ਜਨਾਂ ਨੇ ਮੈਨੂੰ ਪਰਮਾਤਮਾ ਦੀ ਭਗਤੀ ਦੀ ਰਾਸਿ-ਪੂੰਜੀ ਦਿੱਤੀ ਹੈ, ਤਦੋਂ ਤੋਂ ਮੇਰੇ ਮਨ ਦਾ ਚਿੰਤਾ-ਫ਼ਿਕਰ ਲਹਿ ਗਿਆ ਹੈ ।"},{"gurmukhi":"ਧਰਮਰਾਇਅਬਕਹਾਕਰੈਗੋਜਉਫਾਟਿਓਸਗਲੋਲੇਖਾ॥੩॥","meaning":"(ਮੇਰੇ ਜਨਮਾਂ ਜਨਮਾਂਤਰਾਂ ਦੇ ਕੀਤੇ ਕਰਮਾਂ ਦਾ) ਸਾਰਾ ਹੀ ਹਿਸਾਬ ਦਾ ਕਾਗਜ਼ ਪਾਟ ਚੁਕਾ ਹੈ । ਹੁਣ ਧਰਮਰਾਜ ਮੈਥੋਂ ਕੋਈ ਪੁੱਛ ਨਹੀਂ ਕਰੇਗਾ ।੩।"},{"gurmukhi":"ਮਹਾਅਨੰਦਭਏਸੁਖੁਪਾਇਆਸੰਤਨਕੈਪਰਸਾਦੇ॥","meaning":"ਹੇ ਭਾਈ! ਸੰਤ ਜਨਾਂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਮੇਰੇ ਅੰਦਰ ਬੜਾ ਆਤਮਕ ਆਨੰਦ ਬਣਿਆ ਪਿਆ ਹੈ ।"},{"gurmukhi":"ਕਹੁਨਾਨਕਹਰਿਸਿਉਮਨੁਮਾਨਿਆਰੰਗਿਰਤੇਬਿਸਮਾਦੇ॥੪॥੮॥੧੯॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਮੇਰਾ ਮਨ ਪਰਮਾਤਮਾ ਨਾਲ ਪਤੀਜ ਗਿਆ ਹੈ, ਅਸਚਰਜ ਪ੍ਰਭੂ ਦੇ ਪ੍ਰੇਮ-ਰੰਗ ਵਿਚ ਮੈਂ ਰੰਗਿਆ ਗਿਆ ਹਾਂ ।੪।੮।੧੯।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (25, 'ਸਲੋਕਮਃ੨॥', '[{"gurmukhi":"ਕਿਸਹੀਕੋਈਕੋਇਮੰਞੁਨਿਮਾਣੀਇਕੁਤੂ॥","meaning":"ਕਿਸੇ ਦਾ ਕੋਈ (ਮਿਥਿਆ) ਆਸਰਾ ਹੈ, ਕਿਸੇ ਦਾ ਕੋਈ ਆਸਰਾ ਹੈ, ਮੈਂ ਨਿਮਾਣੀ ਦਾ ਇਕ ਤੂੰ ਹੀ ਤੂੰ ਹੈਂ ।"},{"gurmukhi":"ਕਿਉਨਮਰੀਜੈਰੋਇਜਾਲਗੁਚਿਤਿਨਆਵਹੀ॥੧॥","meaning":"ਜਦ ਤਕ ਤੂੰ ਮੇਰੇ ਚਿੱਤ ਵਿਚ ਨਾਹ ਵਸੇਂ, ਕਿਉਂ ਨ ਰੋ ਕੇ ਮਰਾਂ? (ਤੈਨੂੰ ਵਿਸਾਰ ਕੇ ਦੁੱਖਾਂ ਵਿਚ ਹੀ ਖਪੀਦਾ ਹੈ) ।੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (26, 'ਗਉੜੀਮਾਝਮਹਲਾ੫॥', '[{"gurmukhi":"ਸੁਣਿਸੁਣਿਸਾਜਨਮਨਮਿਤਪਿਆਰੇਜੀਉ॥","meaning":"ਹੇ ਮੇਰੇ ਪਿਆਰੇ ਸੱਜਣ ਪ੍ਰਭੂ! ਹੇ ਮੇਰੇ ਮਨ ਦੇ ਮਿੱਤਰ ਪ੍ਰਭੂ! ਹੇ ਮੇਰੀ ਜਿੰਦ ਦੇ ਆਸਰੇ ਪ੍ਰਭੂ! (ਮੇਰੀ ਬੇਨਤੀ) ਧਿਆਨ ਨਾਲ ਸੁਣ ।"},{"gurmukhi":"ਮਨੁਤਨੁਤੇਰਾਇਹੁਜੀਉਭਿਵਾਰੇਜੀਉ॥","meaning":"(ਮੇਰਾ ਇਹ) ਮਨ ਤੇਰਾ ਦਿੱਤਾ ਹੋਇਆ ਹੈ, (ਮੇਰਾ ਇਹ) ਸਰੀਰ ਤੇਰਾ ਦਿੱਤਾ ਹੋਇਆ ਹੈ, ਮੇਰੀ ਇਹ ਜਿੰਦ ਭੀ ਤੇਰੀ ਹੀ ਦਿੱਤੀ ਹੋਈ ਹੈ ।"},{"gurmukhi":"ਵਿਸਰੁਨਾਹੀਪ੍ਰਭਪ੍ਰਾਣਅਧਾਰੇਜੀਉ॥","meaning":"ਮੈਂ (ਇਹ ਸਭ ਕੁਝ ਤੈਥੋਂ) ਕੁਰਬਾਨ ਕਰਦਾ ਹਾਂ, ਮੈਨੂੰ ਭੁਲ ਨਾਹ,"},{"gurmukhi":"ਸਦਾਤੇਰੀਸਰਣਾਈਜੀਉ॥੧॥","meaning":"ਮੈਂ ਸਦਾ ਤੇਰੀ ਸਰਨ ਪਿਆ ਰਹਾਂ ।੧।"},{"gurmukhi":"ਜਿਸੁਮਿਲਿਐਮਨੁਜੀਵੈਭਾਈਜੀਉ॥","meaning":"ਹੇ ਭਾਈ! ਜਿਸ ਹਰਿ-ਪ੍ਰਭੂ ਨੂੰ ਮਿਲਿਆਂ ਆਤਮਕ ਜੀਵਨ ਲੱਭ ਪੈਂਦਾ ਹੈ"},{"gurmukhi":"ਗੁਰਪਰਸਾਦੀਸੋਹਰਿਹਰਿਪਾਈਜੀਉ॥","meaning":"ਉਹ ਹਰਿ-ਪ੍ਰਭੂ ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਹੀ ਮਿਲ ਸਕਦਾ ਹੈ ।"},{"gurmukhi":"ਸਭਕਿਛੁਪ੍ਰਭਕਾਪ੍ਰਭਕੀਆਜਾਈਜੀਉ॥","meaning":"(ਹੇ ਭਾਈ! ਮੇਰਾ ਮਨ ਤਨ) ਸਭ ਕੁਝ ਪ੍ਰਭੂ ਦਾ ਹੀ ਦਿੱਤਾ ਹੋਇਆ ਹੈ, (ਜਗਤ ਦੀਆਂ) ਸਾਰੀਆਂ ਥਾਵਾਂ ਪ੍ਰਭੂ ਦੀਆਂ ਹੀ ਹਨ,"},{"gurmukhi":"ਪ੍ਰਭਕਉਸਦਬਲਿਜਾਈਜੀਉ॥੨॥","meaning":"ਮੈਂ ਸਦਾ ਉਸ ਪ੍ਰਭੂ ਤੋਂ ਹੀ ਸਦਕੇ ਜਾਂਦਾ ਹਾਂ ।੨।"},{"gurmukhi":"ਏਹੁਨਿਧਾਨੁਜਪੈਵਡਭਾਗੀਜੀਉ॥","meaning":"(ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ ਦਾ) ਇਹ (ਨਾਮ ਸਾਰੇ ਪਦਾਰਥਾਂ ਦਾ) ਖ਼ਜ਼ਾਨਾ (ਹੈ ਕੋਈ) ਭਾਗਾਂ ਵਾਲਾ ਮਨੁੱਖ ਇਹ ਨਾਮ (ਜਪਦਾ ਹੈ,"},{"gurmukhi":"ਨਾਮਨਿਰੰਜਨਏਕਲਿਵਲਾਗੀਜੀਉ॥","meaning":"ਪਵਿੱਤ੍ਰ-ਸਰੂਪ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਨਾਲ (ਉਸ ਵਡਭਾਗੀ ਮਨੁੱਖ ਦੀ) ਲਗਨ ਲੱਗ ਜਾਂਦੀ ਹੈ ।"},{"gurmukhi":"ਗੁਰੁਪੂਰਾਪਾਇਆਸਭੁਦੁਖੁਮਿਟਾਇਆਜੀਉ॥","meaning":"ਉਹ ਹਰੇਕ ਕਿਸਮ ਦਾ ਦੁੱਖ ਦੂਰ ਕਰ ਲੈਂਦਾ ਹੈ,"},{"gurmukhi":"ਆਠਪਹਰਗੁਣਗਾਇਆਜੀਉ॥੩॥","meaning":"ਉਹ ਅੱਠੇ ਪਹਿਰ ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੇ ਗੀਤ ਗਾਂਦਾ ਰਹਿੰਦਾ ਹੈ ।੩।"},{"gurmukhi":"ਰਤਨਪਦਾਰਥਹਰਿਨਾਮੁਤੁਮਾਰਾਜੀਉ॥","meaning":"(ਹੇ ਮੇਰੇ ਪਿਆਰੇ ਸੱਜਣ ਪ੍ਰਭੂ! ਹੇ ਹਰੀ! ਤੇਰਾ ਨਾਮ ਕੀਮਤੀ ਪਦਾਰਥਾਂ (ਦਾ ਸੋਮਾ) ਹੈ ।"},{"gurmukhi":"ਤੂੰਸਚਾਸਾਹੁਭਗਤੁਵਣਜਾਰਾਜੀਉ॥","meaning":"ਹੇ ਹਰੀ! ਤੂੰ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ (ਉਹਨਾਂ ਰਤਨ-ਪਦਾਰਥਾਂ ਦਾ) ਸਾਹੂਕਾਰ ਹੈਂ, ਤੇਰਾ ਭਗਤ (ਉਹਨਾਂ ਰਤਨ ਪਦਾਰਥਾਂ ਦਾ) ਵਣਜ ਕਰਨ ਵਾਲਾ ਹੈ ।"},{"gurmukhi":"ਹਰਿਧਨੁਰਾਸਿਸਚੁਵਾਪਾਰਾਜੀਉ॥","meaning":"ਹੇ ਹਰੀ! ਤੇਰਾ ਨਾਮ-ਧਨ (ਤੇਰੇ ਭਗਤ ਦਾ) ਸਰਮਾਇਆ ਹੈ, ਤੇਰਾ ਭਗਤ ਇਹੀ ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਵਣਜ ਕਰਦਾ ਹੈ ।"},{"gurmukhi":"ਜਨਨਾਨਕਸਦਬਲਿਹਾਰਾਜੀਉ॥੪॥੩॥੧੬੮॥","meaning":"ਹੇ ਦਾਸ ਨਾਨਕ! (ਆਖ—ਹੇ ਹਰੀ!) ਮੈਂ (ਤੈਥੋਂ ਤੇ ਤੇਰੇ ਭਗਤ ਤੋਂ) ਸਦਾ ਕੁਰਬਾਨ ਜਾਂਦਾ ਹਾਂ ।੪।੩।੧੬੮।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (27, 'ਗਉੜੀਛੰਤਮਹਲਾ੧॥', '[{"gurmukhi":"ਸੁਣਿਨਾਹਪ੍ਰਭੂਜੀਉਏਕਲੜੀਬਨਮਾਹੇ॥","meaning":"ਹੇ ਪ੍ਰਭੂ ਖਸਮ ਜੀ! (ਮੇਰੀ ਬੇਨਤੀ) ਸੁਣੋ । (ਤੈਥੋਂ ਬਿਨਾ) ਮੈਂ ਜੀਵ-ਇਸਤ੍ਰੀ ਇਸ ਸੰਸਾਰ-ਜੰਗਲ ਵਿਚ ਇਕੱਲੀ ਹਾਂ ।"},{"gurmukhi":"ਕਿਉਧੀਰੈਗੀਨਾਹਬਿਨਾਪ੍ਰਭਵੇਪਰਵਾਹੇ॥","meaning":"ਹੇ ਬੇ-ਪ੍ਰਵਾਹ ਪ੍ਰਭੂ! ਤੈਂ ਖਸਮ ਤੋਂ ਬਿਨਾਂ ਮੇਰੀ ਜਿੰਦ ਧੀਰਜ ਨਹੀਂ ਫੜ ਸਕਦੀ ।"},{"gurmukhi":"ਧਨਨਾਹਬਾਝਹੁਰਹਿਨਸਾਕੈਬਿਖਮਰੈਣਿਘਣੇਰੀਆ॥","meaning":"ਜੀਵ-ਇਸਤ੍ਰੀ ਪ੍ਰਭੂ-ਪਤੀ ਤੋਂ ਬਿਨਾ ਰਹਿ ਨਹੀਂ ਸਕਦੀ (ਖਸਮ-ਪ੍ਰਭੂ ਤੋਂ ਬਿਨਾ ਇਸ ਦੀ) ਜ਼ਿੰਦਗੀ ਦੀ ਰਾਤ ਬਹੁਤ ਹੀ ਔਖੀ ਗੁਜ਼ਰਦੀ ਹੈ ।"},{"gurmukhi":"ਨਹਨੀਦਆਵੈਪ੍ਰੇਮੁਭਾਵੈਸੁਣਿਬੇਨੰਤੀਮੇਰੀਆ॥","meaning":"ਹੇ ਖਸਮ-ਪ੍ਰਭੂ! ਮੇਰੀ ਬੇਨਤੀ ਸੁਣ, ਮੈਨੂੰ ਤੇਰਾ ਪਿਆਰ ਚੰਗਾ ਲੱਗਦਾ ਹੈ (ਤੇਰੇ ਵਿਛੋੜੈ ਵਿਚ) ਮੈਨੂੰ ਸ਼ਾਂਤੀ ਨਹੀਂ ਆ ਸਕਦੀ ।"},{"gurmukhi":"ਬਾਝਹੁਪਿਆਰੇਕੋਇਨਸਾਰੇਏਕਲੜੀਕੁਰਲਾਏ॥","meaning":"ਪਿਆਰੇ ਪ੍ਰਭੂ-ਪਤੀ ਤੋਂ ਬਿਨਾ (ਇਸ ਜਿੰਦ ਦੀ) ਕੋਈ ਭੀ ਵਾਤ ਨਹੀਂ ਪੱੁਛਦਾ । ਇਹ ਇਕੱਲੀ ਹੀ (ਇਸ ਸੰਸਾਰ‑ਜੰਗਲ ਵਿਚ) ਕੂਕਦੀ ਹੈ,"},{"gurmukhi":"ਨਾਨਕਸਾਧਨਮਿਲੈਮਿਲਾਈਬਿਨੁਪ੍ਰੀਤਮਦੁਖੁਪਾਏ॥੧॥","meaning":"(ਪਰ) ਹੇ ਨਾਨਕ! ਜੀਵ-ਇਸਤ੍ਰੀ ਤਦੋਂ ਹੀ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਮਿਲ ਸਕਦੀ ਹੈ, ਜੇ ਇਸ ਨੂੰ ਗੁਰੂ ਮਿਲਾ ਦੇਵੇ, ਨਹੀਂ ਤਾਂ ਪ੍ਰੀਤਮ-ਪ੍ਰਭੂ ਤੋਂ ਬਿਨਾ ਦੁਖ ਹੀ ਦੁਖ ਸਹਾਰਦੀ ਹੈ ।੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (28, 'ਪਉੜੀ॥', '[{"gurmukhi":"ਗੁਰਸਿਖਾਂਮਨਿਹਰਿਪ੍ਰੀਤਿਹੈਗੁਰੁਪੂਜਣਆਵਹਿ॥","meaning":"ਗੁਰਸਿੱਖਾਂ ਦੇ ਮਨ ਵਿਚ ਹਰੀ ਦਾ ਪਿਆਰ ਹੁੰਦਾ ਹੈ ਤੇ (ਉਸ ਪਿਆਰ ਦਾ ਸਦਕਾ ਉਹ) ਆਪਣੇ ਸਤਿਗੁਰੂ ਦੀ ਸੇਵਾ ਕਰਨ ਆਉਂਦੇ ਹਨ"},{"gurmukhi":"ਹਰਿਨਾਮੁਵਣੰਜਹਿਰੰਗਸਿਉਲਾਹਾਹਰਿਨਾਮੁਲੈਜਾਵਹਿ॥","meaning":"(ਸਤਿਗੁਰੂ ਦੇ ਕੋਲ ਆ ਕੇ) ਪਿਆਰ ਨਾਲ ਹਰੀ-ਨਾਮ ਦਾ ਵਪਾਰ ਕਰਦੇ ਹਨ ਤੇ ਹਰੀ-ਨਾਮ ਦਾ ਲਾਭ ਖੱਟ ਕੇ ਲੈ ਜਾਂਦੇ ਹਨ ।"},{"gurmukhi":"ਗੁਰਸਿਖਾਕੇਮੁਖਉਜਲੇਹਰਿਦਰਗਹਭਾਵਹਿ॥","meaning":"(ਇਹੋ ਜਿਹੇ) ਗੁਰਸਿੱਖਾਂ ਦੇ ਮੂੰਹ ਉਜਲੇ ਹੁੰਦੇ ਹਨ ਤੇ ਹਰੀ ਦੀ ਦਰਗਾਹ ਵਿਚ ਉਹ ਪਿਆਰੇ ਲੱਗਦੇ ਹਨ ।"},{"gurmukhi":"ਗੁਰੁਸਤਿਗੁਰੁਬੋਹਲੁਹਰਿਨਾਮਕਾਵਡਭਾਗੀਸਿਖਗੁਣਸਾਂਝਕਰਾਵਹਿ॥","meaning":"ਗੁਰੂ ਸਤਿਗੁਰੂ ਹਰੀ ਦੇ ਨਾਮ ਦਾ (ਮਾਨੋ) ਬੋਹਲ ਹੈ, ਵੱਡੇ ਭਾਗਾਂ ਵਾਲੇ ਸਿੱਖ ਆ ਕੇ ਗੁਣਾਂ ਦੀ ਭਿਆਲੀ ਪਾਉਂਦੇ ਹਨ"},{"gurmukhi":"ਤਿਨਾਗੁਰਸਿਖਾਕੰਉਹਉਵਾਰਿਆਜੋਬਹਦਿਆਉਠਦਿਆਹਰਿਨਾਮੁਧਿਆਵਹਿ॥੧੧॥","meaning":"ਸਦਕੇ ਹਾਂ ਉਹਨਾਂ ਗੁਰਸਿੱਖਾਂ ਤੋਂ, ਜੋ ਬਹਦਿਆਂ ਉਠਦਿਆਂ (ਭਾਵ, ਹਰ ਵੇਲੇ) ਹਰੀ ਦਾ ਨਾਮ ਸਿਮਰਦੇ ਹਨ ।੧੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (29, 'ਵਡਹੰਸੁਮਹਲਾ੫॥', '[{"gurmukhi":"ਤੂਵਡਦਾਤਾਅੰਤਰਜਾਮੀ॥","meaning":"ਹੇ ਮੇਰੇ ਸੁਆਮੀ! ਹੇ ਸਰਬ-ਵਿਆਪਕ ਪ੍ਰਭੂ! ਤੂੰ ਸਭ ਤੋਂ ਵੱਡਾ ਦਾਤਾ ਹੈਂ"},{"gurmukhi":"ਸਭਮਹਿਰਵਿਆਪੂਰਨਪ੍ਰਭਸੁਆਮੀ॥੧॥","meaning":"ਤੂੰ (ਜੀਵਾਂ ਦੇ) ਦਿਲ ਦੀ ਜਾਣਨ ਵਾਲਾ ਹੈਂ, ਤੂੰ ਸਭ ਦੇ ਅੰਦਰ ਮੌਜੂਦ ਹੈਂ ।੧।"},{"gurmukhi":"ਮੇਰੇਪ੍ਰਭਪ੍ਰੀਤਮਨਾਮੁਅਧਾਰਾ॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰੀਤਮ ਪ੍ਰਭੂ! ਤੇਰਾ ਨਾਮ (ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ) ਆਸਰਾ ਹੈ ।"},{"gurmukhi":"ਹਉਸੁਣਿਸੁਣਿਜੀਵਾਨਾਮੁਤੁਮਾਰਾ॥੧॥ਰਹਾਉ॥","meaning":"ਤੇਰਾ ਨਾਮ ਸੁਣ ਸੁਣ ਕੇ ਮੈਂ ਆਤਮਕ ਜੀਵਨ ਹਾਸਲ ਕਰਦਾ ਹਾਂ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਤੇਰੀਸਰਣਿਸਤਿਗੁਰਮੇਰੇਪੂਰੇ॥","meaning":"ਹੇ ਮੇਰੇ ਪੂਰੇ ਸਤਿਗੁਰੂ! ਮੈਂ ਤੇਰੀ ਸਰਨ ਆਇਆ ਹਾਂ"},{"gurmukhi":"ਮਨੁਨਿਰਮਲੁਹੋਇਸੰਤਾਧੂਰੇ॥੨॥","meaning":"ਤੇਰੇ ਸੰਤ ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਨਾਲ ਮਨ ਪਵਿਤ੍ਰ ਹੋ ਜਾਂਦਾ ਹੈ (ਤੇ, ਪਰਮਾਤਮਾ ਦਾ ਦਰਸਨ ਹੁੰਦਾ ਹੈ) ।੨।"},{"gurmukhi":"ਚਰਨਕਮਲਹਿਰਦੈਉਰਿਧਾਰੇ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੈਂ ਤੇਰੇ ਦਰਸਨ ਤੋਂ ਕੁਰਬਾਨ ਜਾਂਦਾ ਹਾਂ"},{"gurmukhi":"ਤੇਰੇਦਰਸਨਕਉਜਾਈਬਲਿਹਾਰੇ॥੩॥","meaning":"ਤੇਰੇ ਸੋਹਣੇ ਕੋਮਲ ਚਰਨ ਮੈਂ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਟਿਕਾਏ ਹੋਏ ਹਨ ।੩।"},{"gurmukhi":"ਕਰਿਕਿਰਪਾਤੇਰੇਗੁਣਗਾਵਾ॥","meaning":"ਹੇ ਨਾਨਕ (ਆਖ—ਹੇ ਪ੍ਰਭੂ!) ਮੇਹਰ ਕਰ, ਮੈਂ ਤੇਰੇ ਗੁਣ ਗਾਂਦਾ ਰਹਾਂ"},{"gurmukhi":"ਨਾਨਕਨਾਮੁਜਪਤਸੁਖੁਪਾਵਾ॥੪॥੫॥","meaning":"ਤੇ, ਤੇਰਾ ਨਾਮ ਜਪਦਿਆਂ ਆਤਮਕ ਆਨੰਦ ਮਾਣਦਾ ਰਹਾਂ ।੪।੫।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (30, 'ਗਉੜੀਬੈਰਾਗਣਿਮਹਲਾ੪॥', '[{"gurmukhi":"ਹਮਰੈਮਨਿਚਿਤਿਹਰਿਆਸਨਿਤਕਿਉਦੇਖਾਹਰਿਦਰਸੁਤੁਮਾਰਾ॥","meaning":"ਹੇ ਹਰੀ ! ਮੇਰੇ ਮਨ ਵਿਚ ਚਿੱਤ ਵਿਚ ਸਦਾ ਇਹ ਆਸ ਰਹਿੰਦੀ ਹੈ ਕਿ ਮੈਂ ਕਿਸੇ ਤਰ੍ਹਾਂ ਤੇਰਾ ਦਰਸਨ ਕਰ ਸਕਾਂ ।"},{"gurmukhi":"ਜਿਨਿਪ੍ਰੀਤਿਲਾਈਸੋਜਾਣਤਾਹਮਰੈਮਨਿਚਿਤਿਹਰਿਬਹੁਤੁਪਿਆਰਾ॥","meaning":"(ਹੇ ਭਾਈ !) ਜਿਸ ਹਰੀ ਨੇ ਮੇਰੇ ਅੰਦਰ ਆਪਣਾ ਪਿਆਰ ਪੈਦਾ ਕੀਤਾ ਹੈ ਉਹੀ ਜਾਣਦਾ ਹੈ, ਮੈ­ਨੂੰ ਆਪਣੇ ਮਨ ਵਿਚ ਚਿੱਤ ਵਿਚ ਹਰੀ ਬਹੁਤ ਪਿਆਰਾ ਲੱਗ ਰਿਹਾ ਹੈ ।"},{"gurmukhi":"ਹਉਕੁਰਬਾਨੀਗੁਰਆਪਣੇਜਿਨਿਵਿਛੁੜਿਆਮੇਲਿਆਮੇਰਾਸਿਰਜਨਹਾਰਾ॥੧॥","meaning":"ਮੈਂ ਆਪਣੇ ਗੁਰੂ ਤੋਂ ਸਦਕੇ ਜਾਂਦਾ ਹਾਂ, ਜਿਸ ਨੇ ਮੈਨੂੰ ਮੇਰਾ ਵਿੱਛੁੜਿਆ ਹੋਇਆ ਸਿਰਜਣਹਾਰ ਹਰੀ ਮਿਲਾ ਦਿੱਤਾ ਹੈ ।੧।"},{"gurmukhi":"ਮੇਰੇਰਾਮਹਮਪਾਪੀਸਰਣਿਪਰੇਹਰਿਦੁਆਰਿ॥","meaning":"ਹੇ ਮੇਰੇ ਮਨ ! ਮੈਂ ਪਾਪੀ ਤੇਰੀ ਸਰਨ ਆਇਆ ਹਾਂ,"},{"gurmukhi":"ਮਤੁਨਿਰਗੁਣਹਮਮੇਲੈਕਬਹੂੰਅਪੁਨੀਕਿਰਪਾਧਾਰਿ॥੧॥ਰਹਾਉ॥","meaning":"ਤੇਰੇ ਦਰ ਤੇ ਆ ਡਿੱਗਾ ਹਾਂ ਕਿ ਸ਼ਾਇਦ (ਇਸ ਤਰ੍ਹਾਂ) ਤੂੰ ਆਪਣੀ ਮਿਹਰ ਕਰ ਕੇ ਮੈਨੂੰ ਗੁਣ-ਹੀਨ ਨੂੰ ਆਪਣੇ ਚਰਨਾਂ ਵਿਚ ਜੋੜ ਲਏਂ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਹਮਰੇਅਵਗੁਣਬਹੁਤੁਬਹੁਤੁਹੈਬਹੁਬਾਰਬਾਰਹਰਿਗਣਤਨਆਵੈ॥","meaning":"ਹੇ ਹਰੀ ! ਮੇਰੇ ਅੰਦਰ ਬੇਅੰਤ ਅਉਗਣ ਹਨ, ਗਿਣੇ ਨਹੀਂ ਜਾ ਸਕਦੇ, ਮੈਂ ਮੁੜ ਮੁੜ ਔਗਣ ਕਰਦਾ ਹਾਂ ।"},{"gurmukhi":"ਤੂੰਗੁਣਵੰਤਾਹਰਿਹਰਿਦਇਆਲੁਹਰਿਆਪੇਬਖਸਿਲੈਹਿਹਰਿਭਾਵੈ॥","meaning":"ਤੂੰ ਗੁਣਾਂ ਦਾ ਮਾਲਕ ਹੈਂ, ਦਇਆ ਦਾ ਘਰ ਹੈਂ ਜਦੋਂ ਤੇਰੀ ਰਜ਼ਾ ਹੁੰਦੀ ਹੈ ਤੂੰ ਆਪ ਹੀ ਬਖ਼ਸ਼ ਲੈਂਦਾ ਹੈਂ ।"},{"gurmukhi":"ਹਮਅਪਰਾਧੀਰਾਖੇਗੁਰਸੰਗਤੀਉਪਦੇਸੁਦੀਓਹਰਿਨਾਮੁਛਡਾਵੈ॥੨॥","meaning":"(ਹੇ ਭਾਈ !) ਸਾਡੇ ਵਰਗੇ ਪਾਪੀਆਂ ਨੂੰ ਹਰੀ ਗੁਰੂ ਦੀ ਸੰਗਤਿ ਵਿਚ ਰੱਖਦਾ ਹੈ, ਉਪਦੇਸ਼ ਦੇਂਦਾ ਹੈ, ਤੇ ਉਸ ਦਾ ਨਾਮ ਵਿਕਾਰਾਂ ਤੋਂ ਖ਼ਲਾਸੀ ਕਰਾ ਦੇਂਦਾ ਹੈ ।੨।"},{"gurmukhi":"ਤੁਮਰੇਗੁਣਕਿਆਕਹਾਮੇਰੇਸਤਿਗੁਰਾਜਬਗੁਰੁਬੋਲਹਤਬਬਿਸਮੁਹੋਇਜਾਇ॥","meaning":"ਹੇ ਮੇਰੇ ਸਤਿਗੁਰੂ ! ਮੈਂ ਤੇਰੇ ਗੁਣ ਕੀਹ ਕੀਹ ਦੱਸਾਂ ? ਜਦੋਂ ਮੈਂ ‘ਗੁਰੂ ਗੁਰੂ’ ਜਪਦਾ ਹਾਂ, ਮੇਰੀ ਅਸਚਰਜ ਆਤਮਕ ਹਾਲਤ ਬਣ ਜਾਂਦੀ ਹੈ ।"},{"gurmukhi":"ਹਮਜੈਸੇਅਪਰਾਧੀਅਵਰੁਕੋਈਰਾਖੈਜੈਸੇਹਮਸਤਿਗੁਰਿਰਾਖਿਲੀਏਛਡਾਇ॥","meaning":"ਸਾਡੇ ਵਰਗੇ ਪਾਪੀਆਂ ਨੂੰ ਜਿਵੇਂ ਸਤਿਗੁਰੂ ਨੇ ਰੱਖ ਲਿਆ ਹੈ (ਵਿਕਾਰਾਂ ਦੇ ਪੰਜੇ ਤੋਂ) ਛੁਡਾ ਲਿਆ ਹੈ ਹੋਰ ਕੌਣ (ਇਸ ਤਰ੍ਹਾਂ) ਰੱਖ ਸਕਦਾ ਹੈ ?"},{"gurmukhi":"ਤੂੰਗੁਰੁਪਿਤਾਤੂੰਹੈਗੁਰੁਮਾਤਾਤੂੰਗੁਰੁਬੰਧਪੁਮੇਰਾਸਖਾਸਖਾਇ॥੩॥","meaning":"ਤੂੰ ਹੀ ਮੇਰਾ ਗੁਰੂ ਹੈਂ, ਮੇਰਾ ਪਿਤਾ ਹੈਂ, ਮੇਰਾ ਰਿਸ਼ਤੇਦਾਰ ਹੈਂ, ਮੇਰਾ ਮਿੱਤਰ ਹੈਂ ।੩।"},{"gurmukhi":"ਜੋਹਮਰੀਬਿਧਿਹੋਤੀਮੇਰੇਸਤਿਗੁਰਾਸਾਬਿਧਿਤੁਮਹਰਿਜਾਣਹੁਆਪੇ॥","meaning":"ਹੇ ਮੇਰੇ ਸਤਿਗੁਰੂ ! ਹੇ ਮੇਰੇ ਹਰੀ ! ਜੇਹੜੀ ਮੇਰੀ ਹਾਲਤ ਹੁੰਦੀ ਸੀ ਉਹ ਹਾਲਤ ਤੂੰ ਆਪ ਹੀ ਜਾਣਦਾ ਹੈਂ ।"},{"gurmukhi":"ਹਮਰੁਲਤੇਫਿਰਤੇਕੋਈਬਾਤਨਪੂਛਤਾਗੁਰਸਤਿਗੁਰਸੰਗਿਕੀਰੇਹਮਥਾਪੇ॥","meaning":"ਮੈਂ ਰੁਲਦਾ ਫਿਰਦਾ ਸਾਂ ਕੋਈ ਮੇਰੀ ਵਾਤ ਨਹੀਂ ਸੀ ਪੁੱਛਦਾ ਤੂੰ ਮੈਨੂੰ ਕੀੜੇ ਨੂੰ ਗੁਰੂ ਸਤਿਗੁਰੂ ਦੇ ਚਰਨਾਂ ਵਿਚ ਲਿਆ ਕੇ ਵਡਿਆਈ ਬਖ਼ਸ਼ੀ ।"},{"gurmukhi":"ਧੰਨੁਧੰਨੁਗੁਰੂਨਾਨਕਜਨਕੇਰਾਜਿਤੁਮਿਲਿਐਚੂਕੇਸਭਿਸੋਗਸੰਤਾਪੇ॥੪॥੫॥੧੧॥੪੯॥","meaning":"(ਹੇ ਭਾਈ !) ਦਾਸ ਨਾਨਕ ਦਾ ਗੁਰੂ ਧੰਨ ਹੈ ਧੰਨ ਹੈ ਜਿਸ (ਗੁਰੂ) ਨੂੰ ਮਿਲ ਕੇ ਮੇਰੇ ਸਾਰੇ ਸੋਗ ਮੁੱਕ ਗਏ ਮੇਰੇ ਸਾਰੇ ਕਲੇਸ਼ ਦੂਰ ਹੋ ਗਏ ।੪।੫।੧੧।੪੯।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (31, 'ਆਸਾਮਹਲਾ੫॥', '[{"gurmukhi":"ਆਗੈਹੀਤੇਸਭੁਕਿਛੁਹੂਆਅਵਰੁਕਿਜਾਣੈਗਿਆਨਾ॥","meaning":"ਜੋ ਬਖ਼ਸ਼ਸ਼ ਮੇਰੇ ਉਤੇ ਹੋਈ ਹੈ ਧੁਰੋਂ ਹੀ ਹੋਈ ਹੈ—ਇਸ ਤੋਂ ਬਿਨਾ ਜੀਵ ਹੋਰ ਕੀ ਗਿਆਨ ਸਮਝ ਸਕਦਾ ਹੈ?"},{"gurmukhi":"ਭੂਲਚੂਕਅਪਨਾਬਾਰਿਕੁਬਖਸਿਆਪਾਰਬ੍ਰਹਮਭਗਵਾਨਾ॥੧॥","meaning":"ਮੇਰੀਆਂ ਅਨੇਕਾਂ ਭੁੱਲਾਂ ਚੁੱਕਾਂ ਵੇਖ ਕੇ ਭੀ ਪਾਰਬ੍ਰਹਮ ਭਗਵਾਨ ਨੇ ਮੈਨੂੰ ਆਪਣੇ ਬਾਲਕ ਨੂੰ ਬਖ਼ਸ਼ ਲਿਆ ਹੈ ।੧।"},{"gurmukhi":"ਸਤਿਗੁਰੁਮੇਰਾਸਦਾਦਇਆਲਾਮੋਹਿਦੀਨਕਉਰਾਖਿਲੀਆ॥","meaning":"(ਹੇ ਭਾਈ!) ਮੇਰਾ ਸਤਿਗੁਰੂ ਸਦਾ ਹੀ ਦਇਆਵਾਨ ਰਹਿੰਦਾ ਹੈ ਉਸ ਨੇ ਮੈਨੂੰ (ਆਤਮਕ ਜੀਵਨ ਦੇ ਸਰਮਾਏ ਵਲੋਂ) ਕੰਗਾਲ ਨੂੰ (ਆਤਮਕ ਮੌਤ ਲਿਆਉਣ ਵਾਲੇ ਰੋਗ ਤੋਂ) ਬਚਾ ਲਿਆ"},{"gurmukhi":"ਕਾਟਿਆਰੋਗੁਮਹਾਸੁਖੁਪਾਇਆਹਰਿਅੰਮ੍ਰਿਤੁਮੁਖਿਨਾਮੁਦੀਆ॥੧॥ਰਹਾਉ॥","meaning":"(ਸਤਿਗੁਰੂ ਨੇ) ਮੇਰੇ ਮੂੰਹ ਵਿਚ ਪਰਮਾਤਮਾ ਦਾ ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲਾ ਨਾਮ-ਜਲ ਪਾਇਆ (ਮੇਰਾ ਵਿਕਾਰਾਂ ਦਾ) ਰੋਗ ਕੱਟਿਆ ਗਿਆ, ਮੈਨੂੰ ਬੜਾ ਆਤਮਕ ਆਨੰਦ ਪ੍ਰਾਪਤ ਹੋਇਆ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਅਨਿਕਪਾਪਮੇਰੇਪਰਹਰਿਆਬੰਧਨਕਾਟੇਮੁਕਤਭਏ॥","meaning":"(ਹੇ ਭਾਈ!) ਗੁਰੂ ਨੇ ਮੇਰੇ ਅਨੇਕਾਂ ਪਾਪ ਦੂਰ ਕਰ ਦਿੱਤੇ ਹਨ, ਮੇਰੇ (ਮਾਇਆ ਦੇ ਮੋਹ ਦੇ) ਬੰਧਨ ਕੱਟ ਦਿੱਤੇ ਹਨ ਮੈਂ (ਮੋਹ ਦੇ ਬੰਧਨਾਂ ਤੋਂ) ਸੁਤੰਤਰ ਹੋ ਗਿਆ ਹਾਂ"},{"gurmukhi":"ਅੰਧਕੂਪਮਹਾਘੋਰਤੇਬਾਹਪਕਰਿਗੁਰਿਕਾਢਿਲੀਏ॥੨॥","meaning":"ਗੁਰੂ ਨੇ ਮੇਰੀ ਬਾਂਹ ਫੜ ਕੇ ਮੈਨੂੰ (ਮਾਇਆ ਦੇ ਮੋਹ ਦੇ) ਘੁੱਪ ਹਨੇਰੇ ਖੂਹ ਵਿਚੋਂ ਕੱਢ ਲਿਆ ਹੈ ।੨।"},{"gurmukhi":"ਨਿਰਭਉਭਏਸਗਲਭਉਮਿਟਿਆਰਾਖੇਰਾਖਨਹਾਰੇ॥","meaning":"(ਹੇ ਭਾਈ! ਵਿਕਾਰਾਂ ਤੋਂ) ਬਚਾ ਸਕਣ ਦੀ ਤਾਕਤ ਰੱਖਣ ਵਾਲੇ ਪਰਮਾਤਮਾ ਨੇ (ਮੈਨੂੰ ਵਿਕਾਰਾਂ ਤੋਂ) ਬਚਾ ਲਿਆ ਹੈ, ਹੁਣ (ਮਾਇਆ ਦੇ ਹੱਲਿਆਂ ਵਲੋਂ) ਬੇ-ਫ਼ਿਕਰ ਹਾਂ (ਇਸ ਪਾਸੇ ਵਲੋਂ) ਮੇਰਾ ਹਰੇਕ ਕਿਸਮ ਦਾ ਡਰ-ਖ਼ਤਰਾ ਮੁੱਕ ਗਿਆ ਹੈ"},{"gurmukhi":"ਐਸੀਦਾਤਿਤੇਰੀਪ੍ਰਭਮੇਰੇਕਾਰਜਸਗਲਸਵਾਰੇ॥੩॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ! ਤੇਰੀ ਅਜੇਹੀ ਬਖ਼ਸ਼ਸ਼ ਮੇਰੇ ਉੱਤੇ ਹੋਈ ਹੈ ਕਿ ਮੇਰੇ (ਆਤਮਕ ਜੀਵਨ ਦੇ) ਸਾਰੇ ਹੀ ਕਾਰਜ ਸਿਰੇ ਚੜ੍ਹ ਗਏ ਹਨ ।੩।"},{"gurmukhi":"ਗੁਣਨਿਧਾਨਸਾਹਿਬਮਨਿਮੇਲਾ॥","meaning":"ਗੁਣਾਂ ਦੇ ਖ਼ਜ਼ਾਨੇ ਮਾਲਕ-ਪ੍ਰਭੂ ਦਾ ਮੇਰੇ ਮਨ ਵਿਚ ਮਿਲਾਪ ਹੋ ਗਿਆ ਹੈ"},{"gurmukhi":"ਸਰਣਿਪਇਆਨਾਨਕਸੋੁਹੇਲਾ॥੪॥੯॥੪੮॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—ਹੇ ਭਾਈ!) (ਜਦੋਂ ਦਾ ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ) ਮੈਂ (ਉਸ ਦੀ) ਸਰਨ ਪਿਆ ਹਾਂ ਮੈਂ ਸੌਖਾ ਹੋ ਗਿਆ ਹਾਂ ।੪।੯।੪੮।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (32, 'ਗਉੜੀਬੈਰਾਗਣਿਮਹਲਾ੪॥', '[{"gurmukhi":"ਕੰਚਨਨਾਰੀਮਹਿਜੀਉਲੁਭਤੁਹੈਮੋਹੁਮੀਠਾਮਾਇਆ॥","meaning":"ਮੇਰੀ ਜਿੰਦ ਸੋਨੇ (ਦੇ ਮੋਹ) ਵਿਚ ਇਸਤ੍ਰੀ (ਦੇ ਮੋਹ) ਵਿਚ ਫਸੀ ਹੋਈ ਹੈ, ਮਾਇਆ ਦਾ ਮੋਹ ਮੈਨੂੰ ਮਿੱਠਾ ਲੱਗ ਰਿਹਾ ਹੈ ।"},{"gurmukhi":"ਘਰਮੰਦਰਘੋੜੇਖੁਸੀਮਨੁਅਨਰਸਿਲਾਇਆ॥","meaning":"ਘਰ, ਪੱਕੇ ਮਹਲ ਘੋੜੇ (ਵੇਖ ਵੇਖ ਕੇ) ਮੈਨੂੰ ਚਾਉ ਚੜ੍ਹਦਾ ਹੈ, ਮੇਰਾ ਮਨ ਹੋਰ ਹੋਰ (ਪਦਾਰਥਾਂ ਦੇ) ਰਸ ਵਿਚ ਲੱਗਾ ਹੋਇਆ ਹੈ ।"},{"gurmukhi":"ਹਰਿਪ੍ਰਭੁਚਿਤਿਨਆਵਈਕਿਉਛੂਟਾਮੇਰੇਹਰਿਰਾਇਆ॥੧॥","meaning":"ਹੇ ਮੇਰੇ ਹਰੀ ! ਹੇ ਮੇਰੇ ਰਾਜਨ ! (ਤੂੰ) ਪਰਮਾਤਮਾ ਕਦੇ ਮੇਰੇ ਚਿੱਤ ਵਿਚ ਨਹੀਂ ਆਉਂਦਾ । ਮੈਂ (ਇਸ ਮੋਹ ਵਿਚੋਂ) ਕਿਵੇਂ ਨਿਕਲਾਂ ? ।੧।"},{"gurmukhi":"ਮੇਰੇਰਾਮਇਹਨੀਚਕਰਮਹਰਿਮੇਰੇ॥","meaning":"ਹੇ ਮੇਰੇ ਰਾਮ ! ਮੇਰੇ ਹਰੀ ! ਮੇਰੇ ਇਹ ਨੀਚ ਕੰਮ ਹਨ ।"},{"gurmukhi":"ਗੁਣਵੰਤਾਹਰਿਹਰਿਦਇਆਲੁਕਰਿਕਿਰਪਾਬਖਸਿਅਵਗਣਸਭਿਮੇਰੇ॥੧॥ਰਹਾਉ॥","meaning":"ਪਰ ਤੂੰ ਗੁਣਾਂ ਦਾ ਮਾਲਕ ਹੈਂ, ਤੂੰ ਦਇਆ ਦਾ ਘਰ ਹੈਂ, ਮਿਹਰ ਕਰ ਤੇ ਮੇਰੇ ਸਾਰੇ ਅਉਗਣ ਬਖ਼ਸ਼ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਕਿਛੁਰੂਪੁਨਹੀਕਿਛੁਜਾਤਿਨਾਹੀਕਿਛੁਢੰਗੁਨਮੇਰਾ॥","meaning":"ਨਾਹ ਮੇਰਾ (ਸੁੰਦਰ) ਰੂਪ ਹੈ, ਨਾਹ ਮੇਰੀ ਉੱਚੀ ਜਾਤਿ ਹੈ, ਨਾਹ ਮੇਰੇ ਵਿਚ ਕੋਈ ਸੁਚੱਜ ਹੈ ।"},{"gurmukhi":"ਕਿਆਮੁਹੁਲੈਬੋਲਹਗੁਣਬਿਹੂਨਨਾਮੁਜਪਿਆਨਤੇਰਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ ! ਮੈਂ ਗੁਣਾਂ ਤੋਂ ਸੱਖਣਾ ਹਾਂ, ਮੈਂ ਤੇਰਾ ਨਾਮ ਨਹੀਂ ਜਪਿਆ, ਮੈਂ ਕੇਹੜਾ ਮੂੰਹ ਲੈ ਕੇ (ਤੇਰੇ ਸਾਹਮਣੇ) ਗੱਲ ਕਰਨ ਜੋਗਾ ਹਾਂ ?"},{"gurmukhi":"ਹਮਪਾਪੀਸੰਗਿਗੁਰਉਬਰੇਪੁੰਨੁਸਤਿਗੁਰਕੇਰਾ॥੨॥","meaning":"ਇਹ ਸਤਿਗੁਰੂ ਦੀ ਮਿਹਰ ਹੋਈ ਹੈ ਕਿ ਮੈਂ ਪਾਪੀ ਗੁਰੂ ਦੀ ਸੰਗਤਿ ਵਿਚ ਰਹਿ ਕੇ (ਪਾਪਾਂ ਤੋਂ) ਬਚ ਗਿਆ ਹਾਂ ।੨।"},{"gurmukhi":"ਸਭੁਜੀਉਪਿੰਡੁਮੁਖੁਨਕੁਦੀਆਵਰਤਣਕਉਪਾਣੀ॥","meaning":"ਇਹ ਜਿੰਦ ਇਹ ਸਰੀਰ ਇਹ ਮੂੰਹ ਇਹ ਨੱਕ ਆਦਿਕ ਅੰਗ ਇਹ ਸਭ ਕੁਝ ਪਰਮਾਤਮਾ ਨੇ ਮੈਨੂੰ ਦਿੱਤਾ ਹੈ, ਪਾਣੀ (ਹਵਾ ਅੱਗ ਆਦਿਕ) ਮੈਨੂੰ ਉਸ ਨੇ ਵਰਤਣ ਲਈ ਦਿੱਤੇ ਹਨ ।"},{"gurmukhi":"ਅੰਨੁਖਾਣਾਕਪੜੁਪੈਨਣੁਦੀਆਰਸਅਨਿਭੋਗਾਣੀ॥","meaning":"ਉਸ ਨੇ ਮੈਨੂੰ ਅੰਨ ਖਾਣ ਨੂੰ ਦਿੱਤਾ ਹੈ, ਕੱਪੜਾ ਪਹਿਨਣ ਨੂੰ ਦਿੱਤਾ ਹੈ, ਹੋਰ ਅਨੇਕਾਂ ਸੁਆਦਲੇ ਪਦਾਰਥ ਭੋਗਣ ਨੂੰ ਦਿੱਤੇ ਹਨ ।"},{"gurmukhi":"ਜਿਨਿਦੀਏਸੁਚਿਤਿਨਆਵਈਪਸੂਹਉਕਰਿਜਾਣੀ॥੩॥","meaning":"ਜਿਸ ਪਰਮਾਤਮਾ ਨੇ ਇਹ ਸਾਰੇ ਪਦਾਰਥ ਦਿੱਤੇ ਹਨ, ਉਹ ਮੈਨੂੰ ਕਦੇ ਚੇਤੇ ਭੀ ਨਹੀਂ ਆਉਂਦਾ ਹੈ । ਮੈਂ (ਮੂਰਖ-) ਪਸ਼ੂ ਆਪਣੇ ਆਪ ਨੂੰ ਵੱਡਾ ਕਰ ਕੇ ਜਾਣਦਾ ਹਾਂ ।੩।"},{"gurmukhi":"ਸਭੁਕੀਤਾਤੇਰਾਵਰਤਦਾਤੂੰਅੰਤਰਜਾਮੀ॥","meaning":"(ਹੇ ਪ੍ਰਭੂ ! ਸਾਡੇ ਜੀਵਾਂ ਦੇ ਵੱਸ ਭੀ ਕੀਹ ਹੈ ? ਜਗਤ ਵਿਚ ਜੋ ਕੁਝ ਹੋ ਰਿਹਾ ਹੈ) ਸਭ ਤੇਰਾ ਕੀਤਾ ਹੋ ਰਿਹਾ ਹੈ, ਤੂੰ ਹਰੇਕ ਜੀਵ ਦੇ ਦਿਲ ਦੀ ਜਾਣਦਾ ਹੈਂ"},{"gurmukhi":"ਹਮਜੰਤਵਿਚਾਰੇਕਿਆਕਰਹਸਭੁਖੇਲੁਤੁਮਸੁਆਮੀ॥","meaning":"ਅਸੀ ਨਿਮਾਣੇ ਜੀਵ (ਤੈਥੋਂ ਆਕੀ ਹੋ ਕੇ) ਕੀਹ ਕਰ ਸਕਦੇ ਹਾਂ ? ਹੇ ਸੁਆਮੀ ! ਇਹ ਸਾਰਾ ਤੇਰਾ ਹੀ ਖੇਲ ਹੋ ਰਿਹਾ ਹੈ ।"},{"gurmukhi":"ਜਨਨਾਨਕੁਹਾਟਿਵਿਹਾਝਿਆਹਰਿਗੁਲਮਗੁਲਾਮੀ॥੪॥੬॥੧੨॥੫੦॥","meaning":"(ਜਿਵੇਂ ਕੋਈ ਗ਼ੁਲਾਮ ਮੰਡੀ ਵਿਚੋਂ ਖ਼ਰੀਦਿਆ ਜਾਂਦਾ ਹੈ, ਤਿਵੇਂ) ਇਹ ਤੇਰਾ ਦਾਸ ਨਾਨਕ (ਤੇਰੀ ਸਾਧ-ਸੰਗਤਿ) ਹੱਟੀ ਵਿਚ (ਤੇਰੇ ਸੋਹਣੇ ਨਾਮ ਤੋਂ) ਵਿਕਿਆ ਹੋਇਆ ਹੈ, ਤੇਰੇ ਗ਼ੁਲਾਮਾਂ ਦਾ ਗ਼ੁਲਾਮ ਹੈ ।੪।੬।੧੨।੫੦।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (33, 'ਆਸਾਮਹਲਾ੫॥', '[{"gurmukhi":"ਅਪੁਨੇਸੇਵਕਕੀਆਪੇਰਾਖੈਆਪੇਨਾਮੁਜਪਾਵੈ॥","meaning":"ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ ਆਪਣੇ ਸੇਵਕ ਦੀ ਆਪ ਹੀ (ਹਰ ਥਾਂ) ਇੱਜ਼ਤ ਰੱਖਦਾ ਹੈ, ਆਪ ਹੀ ਉਸ ਪਾਸੋਂ ਆਪਣੇ ਨਾਮ ਦਾ ਸਿਮਰਨ ਕਰਾਂਦਾ ਹੈ ।"},{"gurmukhi":"ਜਹਜਹਕਾਜਕਿਰਤਿਸੇਵਕਕੀਤਹਾਤਹਾਉਠਿਧਾਵੈ॥੧॥","meaning":"ਸੇਵਕ ਨੂੰ ਜਿਥੇ ਜਿਥੇ ਕੋਈ ਕੰਮ-ਕਾਰ ਪਏ, ਉਥੇ ਉਥੇ ਪਰਮਾਤਮਾ (ਉਸ ਦਾ ਕੰਮ ਸਵਾਰਨ ਲਈ) ਉਸੇ ਵੇਲੇ ਜਾ ਪਹੁੰਚਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਸੇਵਕਕਉਨਿਕਟੀਹੋਇਦਿਖਾਵੈ॥","meaning":"ਭਾਈ! ਪਰਮਾਤਮਾ ਆਪਣੇ ਸੇਵਕ ਨੂੰ (ਉਸ ਦਾ) ਨਿਕਟ-ਵਰਤੀ ਹੋ ਕੇ ਵਿਖਾ ਦੇਂਦਾ ਹੈ"},{"gurmukhi":"ਜੋਜੋਕਹੈਠਾਕੁਰਪਹਿਸੇਵਕੁਤਤਕਾਲਹੋਇਆਵੈ॥੧॥ਰਹਾਉ॥","meaning":"(ਪਰਮਾਤਮਾ ਆਪਣੇ ਸੇਵਕ ਨੂੰ ਵਿਖਾ ਦੇਂਦਾ ਹੈ ਕਿ ਮੈਂ ਹਰ ਵੇਲੇ ਤੇਰੇ ਅੰਗ-ਸੰਗ ਰਹਿੰਦਾ ਹਾਂ, ਕਿਉਂਕਿ) ਜੋ ਕੁਝ ਸੇਵਕ ਪਰਮਾਤਮਾ ਪਾਸੋਂ ਮੰਗਦਾ ਹੈ ਉਹ ਮੰਗ ਉਸੇ ਵੇਲੇ ਪੂਰੀ ਹੋ ਜਾਂਦੀ ਹੈ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਤਿਸੁਸੇਵਕਕੈਹਉਬਲਿਹਾਰੀਜੋਅਪਨੇਪ੍ਰਭਭਾਵੈ॥","meaning":"ਉਸ (ਸੇਵਕ) ਦੀ ਸੋਭਾ ਸੁਣ ਕੇ (ਸੁਣਨ ਵਾਲੇ ਦਾ) ਮਨ ਖਿੜ ਆਉਂਦਾ ਹੈ (ਆਤਮਕ ਜੀਵਨ ਨਾਲ ਭਰਪੂਰ ਹੋ ਜਾਂਦਾ ਹੈ ਤੇ ਉਹ) ਉਸ ਸੇਵਕ ਦੇ ਚਰਨ ਛੁਹਣ ਲਈ ਆਉਂਦਾ ਹੈ"},{"gurmukhi":"ਤਿਸਕੀਸੋਇਸੁਣੀਮਨੁਹਰਿਆਤਿਸੁਨਾਨਕਪਰਸਣਿਆਵੈ॥੨॥੭॥੧੨੯॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਜੇਹੜਾ ਸੇਵਕ ਆਪਣੇ ਪਰਮਾਤਮਾ ਨੂੰ ਪਿਆਰਾ ਲੱਗਦਾ ਹੈ ਮੈਂ ਉਸ ਤੋਂ ਕੁਰਬਾਨ ਜਾਂਦਾ ਹਾਂ ।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (34, 'ਆਸਾਮਹਲਾ੫॥', '[{"gurmukhi":"ਜਾਤੂੰਸਾਹਿਬੁਤਾਭਉਕੇਹਾਹਉਤੁਧੁਬਿਨੁਕਿਸੁਸਾਲਾਹੀ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜੇ ਤੂੰ ਮਾਲਕ (ਮੇਰੇ ਸਿਰ ਉਤੇ ਹੱਥ ਰੱਖੀ ਰੱਖੇਂ, ਤਾਂ ਮੈਨੂੰ ਮਾਇਆ-ਜ਼ਹਰ ਤੋਂ) ਕੋਈ ਡਰ-ਖ਼ਤਰਾ ਨਹੀਂ ਹੋ ਸਕਦਾ, ਮੈਂ ਤੈਥੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਦੀ ਸ਼ਲਾਘਾ ਨਹੀਂ ਕਰਦਾ (ਮੈਂ ਤੈਥੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਨੂੰ ਮਾਇਆ-ਜ਼ਹਰ ਤੋਂ ਬਚਾਣ ਦੇ ਸਮਰਥ ਨਹੀਂ ਸਮਝਦਾ)"},{"gurmukhi":"ਏਕੁਤੂੰਤਾਸਭੁਕਿਛੁਹੈਮੈਤੁਧੁਬਿਨੁਦੂਜਾਨਾਹੀ॥੧॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜੇ ਇਕ ਤੂੰ ਹੀ ਮੇਰੇ ਵੱਲ ਰਹੇਂ ਤਾਂ ਹਰੇਕ ਲੋੜੀਂਦੀ ਸ਼ੈ ਮੇਰੇ ਪਾਸ ਹੈ, ਤੈਥੋਂ ਬਿਨਾ ਮੇਰਾ ਕੋਈ ਹੋਰ ਸਹਾਈ ਨਹੀਂ ਹੈ ।੧।"},{"gurmukhi":"ਬਾਬਾਬਿਖੁਦੇਖਿਆਸੰਸਾਰੁ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੈਂ ਵੇਖ ਲਿਆ ਹੈ ਕਿ ਸੰਸਾਰ (ਦਾ ਮੋਹ) ਜ਼ਹਰ ਹੈ (ਜੋ ਆਤਮਕ ਜੀਵਨ ਨੂੰ ਮਾਰ ਮੁਕਾਂਦਾ ਹੈ)"},{"gurmukhi":"ਰਖਿਆਕਰਹੁਗੁਸਾਈਮੇਰੇਮੈਨਾਮੁਤੇਰਾਆਧਾਰੁ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਮੇਰੇ ਖਸਮ-ਪ੍ਰਭੂ! (ਇਸ ਜ਼ਹਰ ਤੋਂ) ਮੈਨੂੰ ਬਚਾਈ ਰੱਖ, ਤੇਰਾ ਨਾਮ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਆਸਰਾ ਬਣਿਆ ਰਹੇ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਜਾਣਹਿਬਿਰਥਾਸਭਾਮਨਕੀਹੋਰੁਕਿਸੁਪਹਿਆਖਿਸੁਣਾਈਐ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਹੀ (ਹਰੇਕ ਜੀਵ ਦੇ) ਮਨ ਦੀ ਸਾਰੀ ਪੀੜਾ ਜਾਣਦਾ ਹੈਂ, ਤੈਥੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਨੂੰ ਆਪਣੇ ਮਨ ਦਾ ਦੁੱਖ-ਦਰਦ ਦੱਸਣਾ ਵਿਅਰਥ ਹੈ"},{"gurmukhi":"ਵਿਣੁਨਾਵੈਸਭੁਜਗੁਬਉਰਾਇਆਨਾਮੁਮਿਲੈਸੁਖੁਪਾਈਐ॥੨॥","meaning":"(ਹੇ ਭਾਈ!) ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਤੋਂ ਖੁੰਝ ਕੇ ਸਾਰਾ ਜਗਤ ਝੱਲਾ ਹੋਇਆ ਫਿਰਦਾ ਹੈ । ਜੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਪ੍ਰਾਪਤ ਹੋ ਜਾਏ ਤਾਂ ਆਤਮਕ ਆਨੰਦ ਮਾਣੀਦਾ ਹੈ ।੨।"},{"gurmukhi":"ਕਿਆਕਹੀਐਕਿਸੁਆਖਿਸੁਣਾਈਐਜਿਕਹਣਾਸੁਪ੍ਰਭਜੀਪਾਸਿ॥","meaning":"(ਹੇ ਭਾਈ! ਆਪਣੇ ਮਨ ਦਾ ਦੁੱਖ-ਦਰਦ) ਜੋ ਕੁਝ ਭੀ ਆਖਣਾ ਹੋਵੇ ਪਰਮਾਤਮਾ ਦੇ ਕੋਲ ਹੀ ਆਖਣਾ ਚਾਹੀਦਾ ਹੈ, ਉਸ ਤੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਨੂੰ ਕੁਝ ਨਹੀਂ ਕਹਿਣਾ ਚਾਹੀਦਾ (ਕਿਉਂਕਿ ਪਰਮਾਤਮਾ ਹੀ ਸਾਡੇ ਦੁੱਖ ਦੂਰ ਕਰਨ ਜੋਗਾ ਹੈ)"},{"gurmukhi":"ਸਭੁਕਿਛੁਕੀਤਾਤੇਰਾਵਰਤੈਸਦਾਸਦਾਤੇਰੀਆਸ॥੩॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜਗਤ ਵਿਚ ਜੋ ਕੁਝ ਹੋ ਰਿਹਾ ਹੈ ਸਭ ਕੁਝ ਤੇਰਾ ਕੀਤਾ ਹੀ ਹੋ ਰਿਹਾ ਹੈ । ਅਸਾਨੂੰ ਜੀਵਾਂ ਨੂੰ ਸਦਾ ਤੇਰੀ ਸਹਾਇਤਾ ਦੀ ਹੀ ਆਸ ਹੋ ਸਕਦੀ ਹੈ ।੩।"},{"gurmukhi":"ਜੇਦੇਹਿਵਡਿਆਈਤਾਤੇਰੀਵਡਿਆਈਇਤਉਤਤੁਝਹਿਧਿਆਉ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜੇ ਤੂੰ ਮੈਨੂੰ ਕੋਈ ਮਾਣ-ਵਡਿਆਈ ਬਖ਼ਸ਼ਦਾ ਹੈਂ ਤਾਂ ਇਸ ਨਾਲ ਭੀ ਤੇਰੀ ਹੀ ਸੋਭਾ ਖਿਲਰਦੀ ਹੈ ਕਿਉਂਕਿ ਮੈਂ ਤਾਂ ਇਸ ਲੋਕ ਤੇ ਪਰਲੋਕ ਵਿਚ ਸਦਾ ਹੀ ਤੇਰਾ ਹੀ ਧਿਆਨ ਧਰਦਾ ਹਾਂ"},{"gurmukhi":"ਨਾਨਕਕੇਪ੍ਰਭਸਦਾਸੁਖਦਾਤੇਮੈਤਾਣੁਤੇਰਾਇਕੁਨਾਉ॥੪॥੭॥੪੬॥","meaning":"ਹੇ ਨਾਨਕ ਦੇ ਪ੍ਰਭੂ! ਹੇ ਸਦਾ ਸੁਖ ਦੇਣ ਵਾਲੇ ਪ੍ਰਭੂ! ਤੇਰਾ ਨਾਮ ਹੀ ਮੇਰੇ ਵਾਸਤੇ ਸਹਾਰਾ ਹੈ ।੪।੭।੪੬।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (35, 'ਮਨਮੇਰੇਤਿਨਕੀਓਟਲੇਹਿ॥', '[{"gurmukhi":"","meaning":"ਹੇ ਮੇਰੇ ਮਨ! (ਜੋ ਮਨੱੁਖ਼ ਸਦਾ ਪ੍ਰਭੂ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ ਵੱਸਦੇ ਹਨ) ਉਹਨਾਂ ਦੀ ਸਰਣੀ ਪਉ"},{"gurmukhi":"ਮਨੁਤਨੁਅਪਨਾਤਿਨਜਨਦੇਹਿ॥","meaning":"ਆਪਣਾ ਤਨ ਮਨ ਉਹਨਾਂ ਤੋਂ ਸਦਕੇ ਕਰ ਦੇਹ ।"},{"gurmukhi":"ਜਿਨਿਜਨਿਅਪਨਾਪ੍ਰਭੂਪਛਾਤਾ॥","meaning":"ਜਿਸ ਮਨੁੱਖ ਨੇ ਅਪਣੇ ਪ੍ਰਭੂ ਨੂੰ ਪਛਾਣ ਲਿਆ ਹੈ,"},{"gurmukhi":"ਸੋਜਨੁਸਰਬਥੋਕਕਾਦਾਤਾ॥","meaning":"ਉਹ ਮਨੁੱਖ ਸਾਰੇ ਪਦਾਰਥ ਦੇਣ ਦੇ ਸਮਰੱਥ ਹੋ ਜਾਂਦਾ ਹੈ;"},{"gurmukhi":"ਤਿਸਕੀਸਰਨਿਸਰਬਸੁਖਪਾਵਹਿ॥","meaning":"(ਹੇ ਮਨ!) ਉਸ ਦੀ ਸਰਣੀ ਪਿਆਂ ਤੂੰ ਸਾਰੇ ਸੁਖ ਪਾਵਹਿਂਗਾ ।"},{"gurmukhi":"ਤਿਸਕੈਦਰਸਿਸਭਪਾਪਮਿਟਾਵਹਿ॥","meaning":"ਉਸ ਦੇ ਦੀਦਾਰ ਨਾਲ ਤੂੰ ਸਾਰੇ ਪਾਪ ਦੂਰ ਕਰ ਲਵਹਿਂਗਾ"},{"gurmukhi":"ਅਵਰਸਿਆਨਪਸਗਲੀਛਾਡੁ॥","meaning":"ਹੋਰ ਚੁਤਰਾਈ ਛੱਡ ਦੇਹ,"},{"gurmukhi":"ਤਿਸੁਜਨਕੀਤੂਸੇਵਾਲਾਗੁ॥","meaning":"ਉਸ ਸੇਵਕ ਦੀ ਸੇਵਾ ਵਿਚ ਜੁੱਟ ਪਉ;"},{"gurmukhi":"ਆਵਨੁਜਾਨੁਨਹੋਵੀਤੇਰਾ॥","meaning":"ਇਸ ਤਰ੍ਹਾਂ ਮੁੜ ਮੁੜ ਜਗਤ ਵਿਚ) ਤੇਰਾ ਆਉਣ ਜਾਣ ਨਹੀਂ ਹੋਵੇਗਾ ।"},{"gurmukhi":"ਨਾਨਕਤਿਸੁਜਨਕੇਪੂਜਹੁਸਦਪੈਰਾ॥੮॥੧੭॥","meaning":"ਹੇ ਨਾਨਕ! ਉਸ ਸੰਤ ਜਨ ਦੇ ਸਦਾ ਪੈਰ ਪੂਜ।੮।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (36, 'ਗਉੜੀ॥', '[{"gurmukhi":"ਰਾਮਜਪਉਜੀਅਐਸੇਐਸੇ॥ਧ੍ਰੂਪ੍ਰਹਿਲਾਦਜਪਿਓਹਰਿਜੈਸੇ॥੧॥","meaning":"ਹੇ ਜਿੰਦੇ! (ਇਉਂ ਅਰਦਾਸ ਕਰ, ਕਿ) ਹੇ ਪ੍ਰਭੂ! ਮੈਂ ਤੈਨੂੰ ਉਸ ਪ੍ਰੇਮ ਤੇ ਸ਼ਰਧਾ ਨਾਲ ਸਿਮਰਾਂ ਜਿਸ ਪ੍ਰੇਮ ਤੇ ਸ਼ਰਧਾ ਨਾਲ ਧ੍ਰੂ ਤੇ ਪ੍ਰਹਿਲਾਦ ਭਗਤ ਨੇ, ਹੇ ਹਰੀ! ਤੈਨੂੰ ਸਿਮਰਿਆ ਸੀ ।੧।"},{"gurmukhi":"ਦੀਨਦਇਆਲਭਰੋਸੇਤੇਰੇ॥","meaning":"ਹੇ ਦੀਨਾਂ ਉੱਤੇ ਦਇਆ ਕਰਨ ਵਾਲੇ ਪ੍ਰਭੂ! ਤੇਰੀ ਮਿਹਰ ਦੀ ਆਸ ਤੇ"},{"gurmukhi":"ਸਭੁਪਰਵਾਰੁਚੜਾਇਆਬੇੜੇ॥੧॥ਰਹਾਉ॥","meaning":"ਮੈਂ ਆਪਣਾ ਸਾਰਾ ਪਰਵਾਰ ਤੇਰੇ (ਨਾਮ ਦੇ) ਜਹਾਜ਼ ਤੇ ਚੜ੍ਹਾ ਦਿੱਤਾ ਹੈ (ਮੈਂ ਜੀਭ, ਅੱਖ, ਕੰਨ ਆਦਿਕ ਸਭ ਗਿਆਨ-ਇੰਦ੍ਰਿਆਂ ਨੂੰ ਤੇਰੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਵਿਚ ਜੋੜ ਦਿੱਤਾ ਹੈ) ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਜਾਤਿਸੁਭਾਵੈਤਾਹੁਕਮੁਮਨਾਵੈ॥","meaning":"ਜਦੋਂ ਪ੍ਰਭੂ ਨੂੰ ਭਾਉਂਦਾ ਹੈ ਤਾਂ ਉਹ (ਇਸ ਸਾਰੇ ਪਰਵਾਰ ਤੋਂ ਆਪਣਾ) ਹੁਕਮ ਮਨਾਉਂਦਾ ਹੈ (ਭਾਵ, ਇਹਨਾਂ ਇੰਦ੍ਰਿਆਂ ਪਾਸੋਂ ਉਹੀ ਕੰਮ ਕਰਾਉਂਦਾ ਹੈ ਜਿਸ ਕੰਮ ਲਈ ਉਸ ਨੇ ਇਹ ਇੰਦ੍ਰੇ ਬਣਾਏ ਹਨ),"},{"gurmukhi":"ਇਸਬੇੜੇਕਉਪਾਰਿਲਘਾਵੈ॥੨॥","meaning":"ਤੇ ਇਸ ਤਰ੍ਹਾਂ ਇਸ ਸਾਰੇ ਪੂਰ ਨੂੰ (ਇਹਨਾਂ ਸਭ ਇੰਦ੍ਰਿਆਂ ਨੂੰ) ਵਿਕਾਰਾਂ ਦੀਆਂ ਲਹਿਰਾਂ ਤੋਂ ਬਚਾ ਲੈਂਦਾ ਹੈ ।੨।"},{"gurmukhi":"ਗੁਰਪਰਸਾਦਿਐਸੀਬੁਧਿਸਮਾਨੀ॥","meaning":"ਸਤਿਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ (ਜਿਸ ਮਨੁੱਖ ਦੇ ਅੰਦਰ) ਅਜਿਹੀ ਅਕਲ ਪਰਗਟ ਹੋ ਪੈਂਦੀ ਹੈ (ਭਾਵ, ਜੋ ਮਨੁੱਖ ਸਾਰੇ ਇੰਦ੍ਰਿਆਂ ਨੂੰ ਪ੍ਰਭੂ ਦੇ ਰੰਗ ਵਿਚ ਰੰਗਦਾ ਹੈ),"},{"gurmukhi":"ਚੂਕਿਗਈਫਿਰਿਆਵਨਜਾਨੀ॥੩॥","meaning":"ਉਸ ਦਾ ਮੁੜ ਮੁੜ ਜੰਮਣਾ ਮਰਨਾ ਮੁੱਕ ਜਾਂਦਾ ਹੈ ।੩।"},{"gurmukhi":"ਕਹੁਕਬੀਰਭਜੁਸਾਰਿਗਪਾਨੀ॥","meaning":"ਹੇ ਕਬੀਰ! ਆਖ (ਭਾਵ, ਆਪਣੇ ਆਪ ਨੂੰ ਸਮਝਾ)—ਸਾਰਿੰਗਪਾਨੀ ਪ੍ਰਭੂ ਨੂੰ ਸਿਮਰ,"},{"gurmukhi":"ਉਰਵਾਰਿਪਾਰਿਸਭਏਕੋਦਾਨੀ॥੪॥੨॥੧੦॥੬੧॥","meaning":"ਲੋਕ-ਪਰਲੋਕ ਵਿਚ ਹਰ ਥਾਂ ਉਸ ਇੱਕ ਪ੍ਰਭੂ ਨੂੰ ਹੀ ਜਾਣ ।੪।੨।੧੦।੬੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (37, 'ਰਾਗੁਸੂਹੀਮਹਲਾ੫ਅਸਟਪਦੀਆਘਰੁ੧੦ਕਾਫੀ', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਜੇਭੁਲੀਜੇਚੁਕੀਸਾੲਂੀਭੀਤਹਿੰਜੀਕਾਢੀਆ॥","meaning":"ਹੇ ਮੇਰੇ ਖਸਮ-ਪ੍ਰਭੂ! ਜੇ ਮੈਂ ਭੁੱਲਾਂ ਕਰਦੀ ਹਾਂ, ਜੇ ਮੈਂ ਉਕਾਇਆਂ ਕਰਦੀ ਹਾਂ, ਤਾਂ ਭੀ ਮੈਂ ਤੇਰੀ ਹੀ ਅਖਵਾਂਦੀ ਹਾਂ (ਮੈਂ ਤੇਰਾ ਦਰ ਛੱਡ ਕੇ ਹੋਰ ਕਿਧਰੇ ਭੀ ਜਾਣ ਨੂੰ ਤਿਆਰ ਨਹੀਂ ਹਾਂ) ।"},{"gurmukhi":"ਜਿਨ੍ਹਾਨੇਹੁਦੂਜਾਣੇਲਗਾਝੂਰਿਮਰਹੁਸੇਵਾਢੀਆ॥੧॥","meaning":"ਜਿਨ੍ਹਾਂ ਦਾ ਪਿਆਰ (ਤੈਥੋਂ ਬਿਨਾ) ਕਿਸੇ ਹੋਰ ਨਾਲ ਬਣਿਆ ਹੋਇਆ ਹੈ, ਉਹ ਛੁੱਟੜਾਂ ਜ਼ਰੂਰ ਝੁਰ ਝੁਰ ਕੇ ਮਰ ਰਹੀਆਂ ਹਨ ।੧।"},{"gurmukhi":"ਹਉਨਾਛੋਡਉਕੰਤਪਾਸਰਾ॥","meaning":"ਮੈਂ ਖਸਮ-ਪ੍ਰਭੂ ਦਾ ਸੋਹਣਾ ਪਾਸਾ (ਕਦੇ ਭੀ) ਨਾਹ ਛੱਡਾਂਗੀ ।"},{"gurmukhi":"ਸਦਾਰੰਗੀਲਾਲਾਲੁਪਿਆਰਾਏਹੁਮਹਿੰਜਾਆਸਰਾ॥੧॥ਰਹਾਉ॥","meaning":"ਮੇਰਾ ਉਹ ਪਿਆਰਾ ਲਾਲ ਸਦਾ ਆਨੰਦ-ਸਰੂਪ ਹੈ, ਮੇਰਾ ਇਹੀ ਆਸਰਾ ਹੈ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਸਜਣੁਤੂਹੈਸੈਣੁਤੂਮੈਤੁਝਉਪਰਿਬਹੁਮਾਣੀਆ॥","meaning":"ਹੇ ਖਸਮ-ਪ੍ਰਭੂ! ਮੇਰਾ ਤਾਂ ਤੂੰ ਹੀ ਸੱਜਣ ਹੈਂ, ਤੂੰ ਹੀ ਸਨਬੰਧੀ ਹੈਂ । ਮੈਨੂੰ ਤਾਂ ਤੇਰੇ ਉਤੇ ਹੀ ਮਾਣ ਹੈ ।"},{"gurmukhi":"ਜਾਤੂਅੰਦਰਿਤਾਸੁਖੇਤੂੰਨਿਮਾਣੀਮਾਣੀਆ॥੨॥","meaning":"ਜਦੋਂ ਤੂੰ ਮੇਰੇ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਵੱਸਦਾ ਹੈਂ, ਤਦੋਂ ਹੀ ਮੈਂ ਸੁਖੀ ਹੁੰਦੀ ਹਾਂ । ਮੈਂ ਨਿਮਾਣੀ ਦਾ ਤੂੰ ਹੀ ਮਾਣ ਹੈਂ ।੨।"},{"gurmukhi":"ਜੇਤੂਤੁਠਾਕ੍ਰਿਪਾਨਿਧਾਨਨਾਦੂਜਾਵੇਖਾਲਿ॥","meaning":"ਹੇ ਕਿਰਪਾ ਦੇ ਖ਼ਜ਼ਾਨੇ ਖਸਮ-ਪ੍ਰਭੂ! ਜੇ ਤੂੰ ਮੇਰੇ ਉੱਤੇ ਦਇਆਵਾਨ ਹੋਇਆ ਹੈਂ, ਤਾਂ (ਆਪਣੇ ਚਰਨਾਂ ਤੋਂ ਬਿਨਾ) ਕੋਈ ਹੋਰ (ਆਸਰਾ) ਨਾਹ ਵਿਖਾਈਂ ।"},{"gurmukhi":"ਏਹਾਪਾਈਮੂਦਾਤੜੀਨਿਤਹਿਰਦੈਰਖਾਸਮਾਲਿ॥੩॥","meaning":"ਮੈਂ ਤਾਂ ਇਹੋ ਸੋਹਣੀ ਦਾਤਿ ਲੱਭੀ ਹੋਈ ਹੈ, ਇਸੇ ਨੂੰ ਮੈਂ ਸਦਾ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਸਾਂਭ ਸਾਂਭ ਰੱਖਦੀ ਹਾਂ ।੩।"},{"gurmukhi":"ਪਾਵਜੁਲਾਈਪੰਧਤਉਨੈਣੀਦਰਸੁਦਿਖਾਲਿ॥","meaning":"ਮੈਂ ਆਪਣੇ ਪੈਰਾਂ ਨੂੰ ਤੇਰੇ (ਦੇਸ ਲੈ ਜਾਣ ਵਾਲੇ) ਰਸਤੇ ਉਤੇ ਤੋਰਾਂ । ਹੇ ਪਿਆਰੇ! (ਮੇਰੀਆਂ ਇਹਨਾਂ) ਅੱਖਾਂ ਨੂੰ ਆਪਣਾ ਦਰਸਨ ਦਿਖਾਲ ।"},{"gurmukhi":"ਸ੍ਰਵਣੀਸੁਣੀਕਹਾਣੀਆਜੇਗੁਰੁਥੀਵੈਕਿਰਪਾਲਿ॥੪॥","meaning":"ਹੇ ਖਸਮ-ਪ੍ਰਭੂ! ਜੇ ਗੁਰੂ (ਮੇਰੇ ਉਤੇ) ਦਇਆਵਾਨ ਹੋਵੇ, ਤਾਂ ਮੈਂ (ਉਸ ਪਾਸੋਂ) ਆਪਣੇ ਕੰਨਾਂ ਨਾਲ ਤੇਰੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੀਆਂ ਗੱਲਾਂ ਸੁਣਦੀ ਰਹਾਂ।੪।"},{"gurmukhi":"ਕਿਤੀਲਖਕਰੋੜਿਪਿਰੀਏਰੋਮਨਪੁਜਨਿਤੇਰਿਆ॥","meaning":"ਜੇ ਮੈਂ ਕਿਤਨੇ ਹੀ ਲੱਖਾਂ ਤੇ ਕੋ੍ਰੜਾਂ ਤੇਰੇ ਗੁਣ ਦੱਸਾਂ, ਤਾਂ ਭੀ ਉਹ ਸਾਰੇ ਤੇਰੇ ਇਕ ਰੋਮ (ਦੀ ਵਡਿਆਈ) ਤਕ ਨਹੀਂ ਅੱਪੜ ਸਕਦੇ ।"},{"gurmukhi":"ਤੂਸਾਹੀਹੂਸਾਹੁਹਉਕਹਿਨਸਕਾਗੁਣਤੇਰਿਆ॥੫॥","meaning":"ਹੇ ਪਿਆਰੇ! ਤੂੰ ਸ਼ਾਹਾਂ ਦਾ ਪਾਤਿਸ਼ਾਹ ਹੈਂ । ਮੈਂ ਤੇਰੇ ਸਾਰੇ ਗੁਣ ਬਿਆਨ ਨਹੀਂ ਕਰ ਸਕਦੀ । ੫।"},{"gurmukhi":"ਸਹੀਆਤਊਅਸੰਖਮੰਞਹੁਹਭਿਵਧਾਣੀਆ॥","meaning":"ਹੇ ਪਿਆਰੇ! ਅਣਗਿਣਤ ਹੀ ਸਹੇਲੀਆਂ ਤੇਰੇ (ਦਰ ਦੀਆਂ ਦਾਸੀਆਂ) ਹਨ । ਮੇਰੇ ਨਾਲੋਂ ਉਹ ਸਾਰੀਆਂ ਹੀ ਚੰਗੀਆਂ ਹਨ ।"},{"gurmukhi":"ਹਿਕਭੋਰੀਨਦਰਿਨਿਹਾਲਿਦੇਹਿਦਰਸੁਰੰਗੁਮਾਣੀਆ॥੬॥","meaning":"ਇਕ ਰਤਾ ਭੀ ਸਮੇ ਲਈ ਹੀ ਮੇਰੇ ਵਲ ਭੀ ਮੇਹਰ ਦੀ ਨਿਗਾਹ ਨਾਲ ਵੇਖ । ਮੈਨੂੰ ਭੀ ਦਰਸਨ ਦੇਹ, ਤਾ ਕਿ ਮੈਂ ਭੀ ਆਤਮਕ ਆਨੰਦ ਮਾਣ ਸਕਾਂ ।੬।"},{"gurmukhi":"ਜੈਡਿਠੇਮਨੁਧੀਰੀਐਕਿਲਵਿਖਵੰਞਨਿ੍ਹਦੂਰੇ॥","meaning":"ਜਿਸ ਦਾ ਦਰਸਨ ਕੀਤਿਆਂ ਮਨ ਧੀਰਜ ਫੜਦਾ ਹੈ ਅਤੇ ਸਾਰੇ ਪਾਪ ਦੂਰ ਹੋ ਜਾਂਦੇ ਹਨ? ।"},{"gurmukhi":"ਸੋਕਿਉਵਿਸਰੈਮਾਉਮੈਜੋਰਹਿਆਭਰਪੂਰੇ॥੭॥","meaning":"ਹੇ ਮਾਂ! ਮੈਨੂੰ (ਭਲਾ) ਉਹ (ਪਿਆਰਾ) ਕਿਵੇਂ ਵਿਸਰ ਸਕਦਾ ਹੈ, ਜੋ ਸਾਰੇ ਜਗਤ ਵਿਚ ਵਿਆਪਕ ਹੈ।੭।"},{"gurmukhi":"ਹੋਇਨਿਮਾਣੀਢਹਿਪਈਮਿਲਿਆਸਹਜਿਸੁਭਾਇ॥","meaning":"ਜਦੋਂ ਮੈਂ ਆਤਮਕ ਅਡੋਲਤਾ ਵਿਚ ਪ੍ਰੇਮ ਵਿਚ ਟਿਕ ਕੇ, ਆਜਜ਼ ਹੋ ਕੇ (ਮਾਣ ਛੱਡ ਕੇ ਉਸ ਦੇ ਦਰ ਤੇ) ਢਹਿ ਪਈ, ਤਾਂ ਉਹ ਪਿਆਰਾ ਮੈਨੂੰ ਮਿਲ ਪਿਆ ।"},{"gurmukhi":"ਪੂਰਬਿਲਿਖਿਆਪਾਇਆਨਾਨਕਸੰਤਸਹਾਇ॥੮॥੧॥੪॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਕਿਸੇ ਪੂਰਬਲੇ ਜਨਮ ਵਿਚ ਚੰਗੀ ਕਿਸਮਤ ਦਾ ਲਿਖਿਆ ਲੇਖ ਮੈਨੂੰ ਗੁਰੂ ਦੀ ਸਹਾਇਤਾ ਨਾਲ ਮਿਲ ਪਿਆ ਹੈ ।੮।੧।੪।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (38, 'ਸੋਰਠਿਮਹਲਾ੫॥', '[{"gurmukhi":"ਨਾਲਿਨਰਾਇਣੁਮੇਰੈ॥","meaning":"ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ ਮੇਰੇ ਨਾਲ (ਮੇਰੇ ਹਿਰਦੇ ਵਿਚ ਵੱਸ ਰਿਹਾ) ਹੈ"},{"gurmukhi":"ਜਮਦੂਤੁਨਆਵੈਨੇਰੈ॥","meaning":"ਉਸ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਜਮਦੂਤ ਮੇਰੇ ਨੇੜੇ ਨਹੀਂ ਢੁੱਕਦਾ (ਮੈਨੂੰ ਮੌਤ ਦਾ, ਆਤਮਕ ਮੌਤ ਦਾ ਖ਼ਤਰਾ ਨਹੀਂ ਰਿਹਾ)"},{"gurmukhi":"ਕੰਠਿਲਾਇਪ੍ਰਭਰਾਖੈ॥","meaning":"ਪ੍ਰਭੂ ਉਸ ਮਨੁੱਖ ਨੂੰ ਆਪਣੇ ਗਲ ਨਾਲ ਲਾ ਰੱਖਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਸਤਿਗੁਰਕੀਸਚੁਸਾਖੈ॥੧॥","meaning":"ਪ੍ਰਭੂ ਉਸ ਮਨੁੱਖ ਨੂੰ ਆਪਣੇ ਗਲ ਨਾਲ ਲਾ ਰੱਖਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਗੁਰਿਪੂਰੈਪੂਰੀਕੀਤੀ॥","meaning":"ਹੇ ਭਾਈ! ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਪੂਰੇ ਗੁਰੂ ਨੇ (ਜੀਵਨ ਵਿਚ) ਸਫਲਤਾ ਬਖ਼ਸ਼ੀ,"},{"gurmukhi":"ਦੁਸਮਨਮਾਰਿਵਿਡਾਰੇਸਗਲੇਦਾਸਕਉਸੁਮਤਿਦੀਤੀ॥੧॥ਰਹਾਉ॥","meaning":"ਪ੍ਰਭੂ ਨੇ (ਕਾਮਾਦਿਕ ਉਸ ਦੇ) ਸਾਰੇ ਹੀ ਵੈਰੀ ਮਾਰ ਮੁਕਾਏ; ਤੇ, ਉਸ ਸੇਵਕ ਨੂੰ (ਨਾਮ ਸਿਮਰਨ ਦੀ) ਸ੍ਰੇਸ਼ਟ ਅਕਲ ਦੇ ਦਿੱਤੀ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਪ੍ਰਭਿਸਗਲੇਥਾਨਵਸਾਏ॥","meaning":"ਹੇ ਭਾਈ! ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਨੂੰ ਗੁਰੂ ਨੇ ਜੀਵਨ-ਸਫਲਤਾ ਬਖ਼ਸ਼ੀ) ਪ੍ਰਭੂ ਨੇ ਉਹਨਾਂ ਦੇ ਸਾਰੇ ਗਿਆਨ-ਇੰਦ੍ਰੇ ਆਤਮਕ ਗੁਣਾਂ ਨਾਲ ਭਰਪੂਰ ਕਰ ਦਿੱਤੇ"},{"gurmukhi":"ਸੁਖਿਸਾਂਦਿਫਿਰਿਆਏ॥","meaning":"ਉਹ ਮਨੁੱਖ (ਕਾਮਾਦਿਕ ਵਲੋਂ) ਪਰਤ ਕੇ ਆਤਮਕ ਆਨੰਦ ਵਿਚ ਆ ਟਿਕੇ"},{"gurmukhi":"ਨਾਨਕਪ੍ਰਭਸਰਣਾਏ॥","meaning":"ਹੇ ਨਾਨਕ! ਉਸ ਪ੍ਰਭੂ ਦੀ ਸ਼ਰਨ ਪਿਆ ਰਹੁ"},{"gurmukhi":"ਜਿਨਿਸਗਲੇਰੋਗਮਿਟਾਏ॥੨॥੨੪॥੮੮॥","meaning":"ਜਿਸ ਨੇ (ਸ਼ਰਨ ਪਿਆਂ ਦੇ) ਸਾਰੇ ਰੋਗ ਦੂਰ ਕਰ ਦਿੱਤੇ ।੨।੨੪।੮੮।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (39, 'ਆਸਾ॥', '[{"gurmukhi":"ਸੁਤੁਅਪਰਾਧਕਰਤਹੈਜੇਤੇ॥","meaning":"ਪੁੱਤਰ ਭਾਵੇਂ ਕਿਤਨੀਆਂ ਹੀ ਗ਼ਲਤੀਆਂ ਕਰੇ,"},{"gurmukhi":"ਜਨਨੀਚੀਤਿਨਰਾਖਸਿਤੇਤੇ॥੧॥","meaning":"ਉਸ ਦੀ ਮਾਂ ਉਹ ਸਾਰੀਆਂ ਦੀਆਂ ਸਾਰੀਆਂ ਭੁਲਾ ਦੇਂਦੀ ਹੈ ।੧।"},{"gurmukhi":"ਰਾਮਈਆਹਉਬਾਰਿਕੁਤੇਰਾ॥","meaning":"ਹੇ (ਮੇਰੇ) ਸੁਹਣੇ ਰਾਮ! ਮੈਂ ਤੇਰਾ ਅੰਞਾਣ ਬੱਚਾ ਹਾਂ,"},{"gurmukhi":"ਕਾਹੇਨਖੰਡਸਿਅਵਗਨੁਮੇਰਾ॥੧॥ਰਹਾਉ॥","meaning":"ਤੂੰ (ਮੇਰੇ ਅੰਦਰੋਂ) ਮੇਰੀਆਂ ਭੁੱਲਾਂ ਕਿਉਂ ਦੂਰ ਨਹੀਂ ਕਰਦਾ? ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਜੇਅਤਿਕ੍ਰੋਪਕਰੇਕਰਿਧਾਇਆ॥","meaning":"ਜੇ (ਮੂਰਖ ਬੱਚਾ) ਬੜਾ ਕੋ੍ਰਧ ਕਰ ਕਰ ਕੇ ਮਾਂ ਨੂੰ ਮਾਰਨ ਭੀ ਪਏ,"},{"gurmukhi":"ਤਾਭੀਚੀਤਿਨਰਾਖਸਿਮਾਇਆ॥੨॥","meaning":"ਤਾਂ ਭੀ ਮਾਂ (ਉਸ ਦੇ ਮੂਰਖ-ਪੁਣੇ) ਚੇਤੇ ਨਹੀਂ ਰੱਖਦੀ ।੨।"},{"gurmukhi":"ਚਿੰਤਭਵਨਿਮਨੁਪਰਿਓਹਮਾਰਾ॥","meaning":"ਹੇ ਮੇਰੇ ਰਾਮ! ਮੇਰਾ ਮਨ ਚਿੰਤਾ ਦੇ ਖੂਹ ਵਿਚ ਪਿਆ ਹੋਇਆ ਹੈ (ਮੈਂ ਸਦਾ ਭੁੱਲਾਂ ਹੀ ਕਰਦਾ ਰਿਹਾ ਹਾਂ)"},{"gurmukhi":"ਨਾਮਬਿਨਾਕੈਸੇਉਤਰਸਿਪਾਰਾ॥੩॥","meaning":"ਤੇਰਾ ਨਾਮ ਸਿਮਰਨ ਤੋਂ ਬਿਨਾ ਕਿਵੇਂ ਇਸ ਚਿੰਤਾ ਵਿਚੋਂ ਪਾਰ ਲੰਘੇ? ।੩।"},{"gurmukhi":"ਦੇਹਿਬਿਮਲਮਤਿਸਦਾਸਰੀਰਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੇਰੇ ਇਸ ਸਰੀਰ ਨੂੰ (ਭਾਵ, ਮੈਨੂੰ) ਸਦਾ ਕੋਈ ਸੁਹਣੀ ਮੱਤ ਦੇਹ,"},{"gurmukhi":"ਸਹਜਿਸਹਜਿਗੁਨਰਵੈਕਬੀਰਾ॥੪॥੩॥੧੨॥","meaning":"ਜਿਸ ਕਰਕੇ (ਤੇਰਾ ਬੱਚਾ) ਕਬੀਰ ਅਡੋਲ ਅਵਸਥਾ ਵਿਚ ਰਹਿ ਕੇ ਤੇਰੇ ਗੁਣ ਗਾਂਦਾ ਰਹੇ ।੪।੩।੧੨।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (40, 'ਬਸੰਤੁਮਹਲਾ੩॥', '[{"gurmukhi":"ਸਭਿਜੁਗਤੇਰੇਕੀਤੇਹੋਏ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਸਾਰੇ ਜੁਗ (ਸਾਰੇ ਸਮੇ) ਤੇਰੇ ਹੀ ਬਣਾਏ ਹੋਏ ਹਨ (ਤੇਰੇ ਨਾਮ ਦੀ ਪ੍ਰਾਪਤੀ ਜੁਗਾਂ ਦੇ ਵਿਤਕਰੇ ਨਾਲ ਨਹੀਂ ਹੁੰਦੀ ।"},{"gurmukhi":"ਸਤਿਗੁਰੁਭੇਟੈਮਤਿਬੁਧਿਹੋਏ॥੧॥","meaning":"ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਤੇਰੀ ਮਿਹਰ ਨਾਲ) ਗੁਰੂ ਮਿਲ ਪੈਂਦਾ ਹੈ (ਉਸ ਦੇ ਅੰਦਰ ਨਾਮ ਜਪਣ ਵਾਲੀ) ਮਤਿ ਅਕਲ ਪੈਦਾ ਹੋ ਜਾਂਦੀ ਹੈ ।੧।"},{"gurmukhi":"ਹਰਿਜੀਉਆਪੇਲੈਹੁਮਿਲਾਇ॥","meaning":"ਹੇ ਪ੍ਰਭੂ ਜੀ! (ਜਿਸ ਮਨੁੱਖ ਨੂੰ) ਤੂੰ ਆਪ ਹੀ (ਆਪਣੇ ਚਰਨਾਂ ਵਿਚ) ਜੋੜ ਲੈਂਦਾ ਹੈਂ,"},{"gurmukhi":"ਗੁਰਕੈਸਬਦਿਸਚਨਾਮਿਸਮਾਇ॥੧॥ਰਹਾਉ॥","meaning":"ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ (ਉਹ ਮਨੁੱਖ) (ਤੇਰੇ) ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਨਾਮ ਵਿਚ ਲੀਨ ਰਹਿੰਦਾ ਹੈ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਮਨਿਬਸੰਤੁਹਰੇਸਭਿਲੋਇ॥","meaning":"ਹੇ ਭਾਈ! (ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਦੇ) ਮਨ ਵਿਚ ਸਦਾ ਖਿੜੇ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ ਆ ਵੱਸਦਾ ਹੈ, ਉਹ ਸਾਰੇ ਹੀ ਇਸ ਜਗਤ ਵਿਚ ਆਤਮਕ ਜੀਵਨ ਵਾਲੇ ਹੋ ਜਾਂਦੇ ਹਨ,"},{"gurmukhi":"ਫਲਹਿਫੁਲੀਅਹਿਰਾਮਨਾਮਿਸੁਖੁਹੋਇ॥੨॥","meaning":"ਉਹ ਮਨੁੱਖ ਦੁਨੀਆ ਵਿਚ ਭੀ ਕਾਮਯਾਬ ਹੁੰਦੇ ਹਨ, ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਦੀ ਬਰਕਤਿ ਨਾਲ ਉਹਨਾਂ ਦੇ ਅੰਦਰ ਆਤਮਕ ਆਨੰਦ (ਭੀ) ਬਣਿਆ ਰਹਿੰਦਾ ਹੈ ।੨।"},{"gurmukhi":"ਸਦਾਬਸੰਤੁਗੁਰਸਬਦੁਵੀਚਾਰੇ॥","meaning":"ਹੇ ਭਾਈ! ਜਿਹੜਾ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਨੂੰ ਮਨ ਵਿਚ ਵਸਾਂਦਾ ਹੈ ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਨੂੰ ਹਿਰਦੇ ਵਿਚ ਟਿਕਾਈ ਰੱਖਦਾ ਹੈ,"},{"gurmukhi":"ਰਾਮਨਾਮੁਰਾਖੈਉਰਧਾਰੇ॥੩॥","meaning":"ਉਸ ਦੇ ਅੰਦਰ ਸਦਾ ਆਤਮਕ ਖਿੜਾਉ ਬਣਿਆ ਰਹਿੰਦਾ ਹੈ ।੩।"},{"gurmukhi":"ਮਨਿਬਸੰਤੁਤਨੁਮਨੁਹਰਿਆਹੋਇ॥","meaning":"ਹੇ ਨਾਨਕ! ਜਿਸ ਮਨੁੱਖ ਦੇ ਮਨ ਵਿਚ ਸਦਾ ਖਿੜੇ ਰਹਿਣ ਵਾਲਾ ਹਰੀ ਆ ਵੱਸਦਾ ਹੈ, ਉਸ ਦਾ ਤਨ ਆਤਮਕ ਜੀਵਨ ਵਾਲਾ ਹੋ ਜਾਂਦਾ ਹੈ ਉਸ ਦਾ ਮਨ ਆਤਮਕ ਜੀਵਨ ਵਾਲਾ ਹੋ ਜਾਂਦਾ ਹੈ ।"},{"gurmukhi":"ਨਾਨਕਇਹੁਤਨੁਬਿਰਖੁਰਾਮਨਾਮੁਫਲੁਪਾਏਸੋਇ॥੪॥੩॥੧੫॥","meaning":"ਹੇ ਨਾਨਕ! ਇਹ ਸਰੀਰ (ਮਾਨੋ) ਰੁੱਖ ਹੈ, (ਜਿਸ ਦੇ ਮਨ ਵਿਚ ਬਸੰਤ ਆ ਜਾਂਦੀ ਹੈ) ਉਸ ਮਨੁੱਖ ਦਾ ਇਹ ਸਰੀਰ-ਰੁੱਖ ਹਰਿ-ਨਾਮ-ਫਲ ਪ੍ਰਾਪਤ ਕਰ ਲੈਂਦਾ ਹੈ ।੪।੧੫।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (41, 'ਮਾਝਮਹਲਾ੪॥', '[{"gurmukhi":"ਹਰਿਗੁਰਗਿਆਨੁਹਰਿਰਸੁਹਰਿਪਾਇਆ॥","meaning":"ਮੈਂ ਗੁਰੂ ਦੀ ਦਿੱਤੀ ਹੋਈ ਪਰਮਾਤਮਾ ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਪ੍ਰਾਪਤ ਕਰ ਲਈ ਹੈ, ਮੈਨੂੰ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ-ਰਸ ਮਿਲ ਗਿਆ ਹੈ"},{"gurmukhi":"ਮਨੁਹਰਿਰੰਗਿਰਾਤਾਹਰਿਰਸੁਪੀਆਇਆ॥","meaning":"ਮੇਰਾ ਮਨ ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ-ਰੰਗ ਵਿਚ ਰੰਗਿਆ ਗਿਆ ਹੈ, ਮੈਨੂੰ (ਗੁਰੂ ਨੇ) ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ-ਰਸ ਪਿਲਾ ਦਿੱਤਾ ਹੈ"},{"gurmukhi":"ਹਰਿਹਰਿਨਾਮੁਮੁਖਿਹਰਿਹਰਿਬੋਲੀਮਨੁਹਰਿਰਸਿਟੁਲਿਟੁਲਿਪਉਦਾਜੀਉ॥੧॥","meaning":"(ਹੁਣ) ਮੈਂ ਸਦਾ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਮੂੰਹ ਨਾਲ ਉਚਾਰਦਾ ਰਹਿੰਦਾ ਹਾਂ, ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ-ਰਸ ਵਿਚ ਮੇਰਾ ਮਨ ਉਛਲ ਉਛਲ ਪੈਂਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਆਵਹੁਸੰਤਮੈਗਲਿਮੇਲਾਈਐ॥","meaning":"ਹੇ ਸੰਤ ਜਨੋ ! ਆਵੋ, ਮੈਨੂੰ ਆਪਣੇ ਗਲ ਨਾਲ ਲਾ ਲਵੋ"},{"gurmukhi":"ਮੇਰੇਪ੍ਰੀਤਮਕੀਮੈਕਥਾਸੁਣਾਈਐ॥","meaning":"ਤੇ ਮੈਨੂੰ ਮੇਰੇ ਪ੍ਰੀਤਮ ਪ੍ਰਭੂ ਦੀਆਂ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੀਆਂ ਗੱਲਾਂ ਸੁਣਾਵੋ"},{"gurmukhi":"ਹਰਿਕੇਸੰਤਮਿਲਹੁਮਨੁਦੇਵਾਜੋਗੁਰਬਾਣੀਮੁਖਿਚਉਦਾਜੀਉ॥੨॥","meaning":"ਹੇ ਪ੍ਰਭੂ ਦੇ ਸੰਤ ਜਨੋ ! ਮੈਨੂੰ ਮਿਲੋ । ਜੇਹੜਾ ਕੋਈ ਸਤਿਗੁਰੂ ਦੀ ਬਾਣੀ ਮੂੰਹ ਨਾਲ ਉਚਾਰਦਾ ਹੈ (ਤੇ ਮੈਨੂੰ ਸੁਣਾਂਦਾ ਹੈਂ) ਮੈਂ ਆਪਣਾ ਮਨ ਉਸ ਦੇ ਹਵਾਲੇ ਕਰਦਾ ਹਾਂ ।੨।"},{"gurmukhi":"ਵਡਭਾਗੀਹਰਿਸੰਤੁਮਿਲਾਇਆ॥","meaning":"ਮੇਰੇ ਵੱਡੇ ਭਾਗਾਂ ਨਾਲ ਪਰਮਾਤਮਾ ਨੇ ਮੈਨੂੰ ਗੁਰੂ ਮਿਲਾ ਦਿੱਤਾ"},{"gurmukhi":"ਗੁਰਿਪੂਰੈਹਰਿਰਸੁਮੁਖਿਪਾਇਆ॥","meaning":"ਤੇ (ਉਸ) ਪੂਰੇ ਗੁਰੂ ਨੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ-ਰਸ ਮੇਰੇ ਮੂੰਹ ਵਿਚ ਪਾ ਦਿੱਤਾ ਹੈ"},{"gurmukhi":"ਭਾਗਹੀਨਸਤਿਗੁਰੁਨਹੀਪਾਇਆਮਨਮੁਖੁਗਰਭਜੂਨੀਨਿਤਿਪਉਦਾਜੀਉ॥੩॥","meaning":"ਨਿਭਾਗੇ ਬੰਦਿਆਂ ਨੂੰ ਹੀ ਸਤਿਗੁਰੂ ਨਹੀਂ ਮਿਲਦਾ । ਜੇਹੜਾ ਮਨੁੱਖ ਆਪਣੇ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਦਾ ਰਹਿੰਦਾ ਹੈ, ਉਹ ਸਦਾ ਜੂਨਾਂ ਦੇ ਗੇੜ ਵਿਚ ਪਿਆ ਰਹਿੰਦਾ ਹੈ ।੩।"},{"gurmukhi":"ਆਪਿਦਇਆਲਿਦਇਆਪ੍ਰਭਿਧਾਰੀ॥","meaning":"ਦਇਆ ਦੇ ਘਰ ਪ੍ਰਭੂ ਨੇ ਜਿਸ ਮਨੁੱਖ ਉੱਤੇ ਮਿਹਰ ਕੀਤੀ"},{"gurmukhi":"ਮਲੁਹਉਮੈਬਿਖਿਆਸਭਨਿਵਾਰੀ॥","meaning":"ਉਸ ਨੇ (ਆਪਣੇ ਅੰਦਰੋਂ) ਹਉਮੈ ਦੀ ਮੈਲ ਮਾਇਆ ਦੀ ਮੈਲ ਸਾਰੀ ਹੀ ਦੂਰੀ ਕਰ ਲਈ"},{"gurmukhi":"ਨਾਨਕਹਟਪਟਣਵਿਚਿਕਾਂਇਆਹਰਿਲੈਂਦੇਗੁਰਮੁਖਿਸਉਦਾਜੀਉ॥੪॥੫॥","meaning":"ਹੇ ਨਾਨਕ ! ਜੇਹੜੇ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੁੰਦੇ ਹਨ, ਉਹ (ਆਪਣੇ) ਸਰੀਰ-ਹੱਟ ਵਿਚ ਹੀ ਸਰੀਰ-ਸ਼ਹਰ ਵਿਚ ਹੀ (ਟਿਕ ਕੇ) ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਦਾ ਸੌਦਾ ਖ਼ਰੀਦਦੇ ਹਨ ।੪।੫।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (42, 'ਭੈਰਉਮਹਲਾ੫॥', '[{"gurmukhi":"ਸਾਚਪਦਾਰਥੁਗੁਰਮੁਖਿਲਹਹੁ॥","meaning":"ਹੇ ਭਾਈ! (ਇਹ) ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ (ਹਰਿ-ਨਾਮ) ਧਨ ਗੁਰੂ ਦੀ ਸਰਨ ਪੈ ਕੇ ਹਾਸਲ ਕਰੋ ।"},{"gurmukhi":"ਪ੍ਰਭਕਾਭਾਣਾਸਤਿਕਰਿਸਹਹੁ॥੧॥","meaning":"ਪਰਮਾਤਮਾ ਵਲੋਂ ਵਰਤੀ ਰਜ਼ਾ ਨੂੰ (ਆਪਣੇ) ਭਲੇ ਵਾਸਤੇ ਜਾਣ ਕੇ ਸਹਾਰੋ"},{"gurmukhi":"ਜੀਵਤਜੀਵਤਜੀਵਤਰਹਹੁ॥","meaning":"ਸਦਾ ਆਤਮਕ ਜੀਵਨ ਵਾਲੇ ਬਣੇ ਰਹੋ"},{"gurmukhi":"ਰਾਮਰਸਾਇਣੁਨਿਤਉਠਿਪੀਵਹੁ॥","meaning":"ਸਦਾ ਆਹਰ ਨਾਲ ਸਭ ਰਸਾਂ ਤੋਂ ਸ੍ਰੇਸ਼ਟ ਨਾਮ-ਰਸ ਪੀਂਦੇ ਰਹੋ,"},{"gurmukhi":"ਹਰਿਹਰਿਹਰਿਹਰਿਰਸਨਾਕਹਹੁ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਭਾਈ! ਸਦਾ ਹੀ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਆਪਣੀ ਜੀਭ ਨਾਲ ਉਚਾਰਦੇ ਰਹੋ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਕਲਿਜੁਗਮਹਿਇਕਨਾਮਿਉਧਾਰੁ॥","meaning":"ਹੇ ਭਾਈ! ਸਿਰਫ਼ ਹਰਿ-ਨਾਮ ਦੀ ਰਾਹੀਂ ਹੀ ਜਗਤ ਵਿਚ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ ਪਾਰ-ਉਤਾਰਾ ਹੁੰਦਾ ਹੈ,"},{"gurmukhi":"ਨਾਨਕੁਬੋਲੈਬ੍ਰਹਮਬੀਚਾਰੁ॥੨॥੧੧॥","meaning":"ਨਾਨਕ (ਤੁਹਾਨੂੰ) ਪਰਮਾਤਮਾ ਨਾਲ ਮਿਲਾਪ ਦੀ (ਇਹੀ) ਜੁਗਤਿ ਦੱਸਦਾ ਹੈ ।੨।੧੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (43, 'ਸੂਹੀਮਹਲਾ੫॥', '[{"gurmukhi":"ਦਰਸਨੁਦੇਖਿਜੀਵਾਗੁਰਤੇਰਾ॥","meaning":"ਹੇ ਗੁਰੂ! ਤੇਰਾ ਦਰਸਨ ਕਰ ਕੇ ਮੈਨੂੰ ਆਤਮਕ ਜੀਵਨ ਮਿਲ ਜਾਂਦਾ ਹੈ ।"},{"gurmukhi":"ਪੂਰਨਕਰਮੁਹੋਇਪ੍ਰਭਮੇਰਾ॥੧॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ! ਤੇਰੀ ਪੂਰਨ ਬਖ਼ਸ਼ਸ਼ ਹੋਏ (ਤੇ, ਮੈਨੂੰ ਗੁਰੂ ਮਿਲ ਜਾਵੇ) ।੧।"},{"gurmukhi":"ਇਹਬੇਨੰਤੀਸੁਣਿਪ੍ਰਭਮੇਰੇ॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ (ਮੇਰੀ) ਇਹ ਅਰਜ਼ੋਈ ਸੁਣ,"},{"gurmukhi":"ਦੇਹਿਨਾਮੁਕਰਿਅਪਣੇਚੇਰੇ॥੧॥ਰਹਾਉ॥","meaning":"ਮੈਨੂੰ ਆਪਣਾ ਸੇਵਕ ਬਣਾ ਕੇ (ਆਪਣਾ) ਨਾਮ ਬਖ਼ਸ਼ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਅਪਣੀਸਰਣਿਰਾਖੁਪ੍ਰਭਦਾਤੇ॥","meaning":"ਹੇ ਸਭ ਦਾਤਾਂ ਦੇਣ ਵਾਲੇ ਪ੍ਰਭੂ! ਮੈਨੂੰ ਆਪਣੀ ਸਰਨ ਵਿਚ ਰੱਖ ।"},{"gurmukhi":"ਗੁਰਪ੍ਰਸਾਦਿਕਿਨੈਵਿਰਲੈਜਾਤੇ॥੨॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਕਿਸੇ ਵਿਰਲੇ ਮਨੁੱਖ ਨੇ ਤੇਰੇ ਨਾਲ ਡੂੰਘੀ ਸਾਂਝ ਪਾਈ ਹੈ ।੨।"},{"gurmukhi":"ਸੁਨਹੁਬਿਨਉਪ੍ਰਭਮੇਰੇਮੀਤਾ॥","meaning":"ਹੇ ਮੇਰੇ ਮਿੱਤਰ ਪ੍ਰਭੂ! ਮੇਰੀ ਅਰਜ਼ੋਈ ਸੁਣ"},{"gurmukhi":"ਚਰਣਕਮਲਵਸਹਿਮੇਰੈਚੀਤਾ॥੩॥","meaning":"ਸੋਹਣੇ ਚਰਨ ਮੇਰੇ ਚਿੱਤ ਵਿਚ ਵੱਸ ਪੈਣ ।੩।"},{"gurmukhi":"ਨਾਨਕੁਏਕਕਰੈਅਰਦਾਸਿ॥","meaning":"ਨਾਨਕ (ਤੇਰੇ ਦਰ ਤੇ) ਇਕ ਅਰਜ਼ ਕਰਦਾ ਹੈ ।"},{"gurmukhi":"ਵਿਸਰੁਨਾਹੀਪੂਰਨਗੁਣਤਾਸਿ॥੪॥੧੮॥੨੪॥","meaning":"ਹੇ ਪੂਰਨ ਪ੍ਰਭੂ! ਸਭ ਗੁਣਾਂ ਦੇ ਖ਼ਜ਼ਾਨੇ ਪ੍ਰਭੂ!(ਕਿਰਪਾ ਕਰ, ਮੈਨੂੰ ਨਾਨਕ ਨੂੰ ਕਦੇ) ਨਾਹ ਭੁੱਲ ।੪।੧੮।੨੪।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (44, 'ਗੂਜਰੀਮਹਲਾ੫ਘਰੁ੨', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਰਾਜਨਮਹਿਤੂੰਰਾਜਾਕਹੀਅਹਿਭੂਮਨਮਹਿਭੂਮਾ॥","meaning":"ਹੇ ਕਰਤਾਰ! (ਦੁਨੀਆ ਦੇ) ਰਾਜਿਆਂ ਵਿਚ ਤੂੰ (ਸ਼ਿਰੋਮਣੀ) ਰਾਜਾ ਅਖਵਾਂਦਾ ਹੈਂ, ਭੁਇਂ ਦੇ ਮਾਲਕਾਂ ਵਿਚ ਤੂੰ (ਸਭ ਤੋਂ ਵੱਡਾ) ਭੁਇਂ ਦਾ ਮਾਲਕ ਹੈਂ ।"},{"gurmukhi":"ਠਾਕੁਰਮਹਿਠਕੁਰਾਈਤੇਰੀਕੋਮਨਸਿਰਿਕੋਮਾ॥੧॥","meaning":"ਹੇ ਕਰਤਾਰ! (ਦੁਨੀਆ ਦੇ) ਸਰਦਾਰਾਂ ਵਿਚ ਤੇਰੀ ਸਰਦਾਰੀ (ਸਭ ਤੋਂ ਵੱਡੀ) ਹੈ, ਉੱਚੀ ਕੁਲ ਵਾਲਿਆਂ ਵਿਚ ਤੂੰ ਸ਼ਿਰੋਮਣੀ ਕੁਲ ਵਾਲਾ ਹੈਂ ।੧।"},{"gurmukhi":"ਪਿਤਾਮੇਰੋਬਡੋਧਨੀਅਗਮਾ॥","meaning":"ਹੇ ਕਰਤਾਰ! ਤੂੰ ਮੇਰਾ ਪਿਤਾ ਹੈਂ, ਤੂੰ ਸਾਡੀ ਸਿਆਣਪ ਦੀ ਪਹੁੰਚ ਤੋਂ ਪਰੇ ਹੈਂ ।"},{"gurmukhi":"ਉਸਤਤਿਕਵਨਕਰੀਜੈਕਰਤੇਪੇਖਿਰਹੇਬਿਸਮਾ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਕਰਤਾਰ! ਤੇਰੀ ਕੇਹੜੀ ਕੇਹੜੀ ਵਡਿਆਈ ਅਸੀ ਕਰੀਏ? (ਤੇਰੀ ਲੀਲਾ) ਵੇਖ ਵੇਖ ਕੇ ਅਸੀ ਹੈਰਾਨ ਹੋ ਰਹੇ ਹਾਂ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਸੁਖੀਅਨਮਹਿਸੁਖੀਆਤੂੰਕਹੀਅਹਿਦਾਤਨਸਿਰਿਦਾਤਾ॥","meaning":"ਹੇ ਕਰਤਾਰ! (ਦੁਨੀਆ ਦੇ) ਸੁਖੀ ਲੋਕਾਂ ਵਿਚ ਤੂੰ (ਸ਼ਿਰੋਮਣੀ) ਸੁਖੀ ਕਿਹਾ ਜਾ ਸਕਦਾ ਹੈਂ"},{"gurmukhi":"ਤੇਜਨਮਹਿਤੇਜਵੰਸੀਕਹੀਅਹਿਰਸੀਅਨਮਹਿਰਾਤਾ॥੨॥","meaning":"ਦਾਨੀਆਂ ਵਿਚ ਤੂੰ ਹੀ (ਸ਼ਿਰੋਮਣੀ) ਤੇਜਸ੍ਵੀ ਕਹਾ ਸਕਦਾ ਹੈਂ (ਦੁਨੀਆ ਦੇ) ਰਸ ਮਾਣਨ ਵਾਲਿਆਂ ਵਿਚ ਤੂੰ ਸ਼ਿਰੋਮਣੀ ਰਸੀਆ ਹੈਂ ।੨।"},{"gurmukhi":"ਸੂਰਨਮਹਿਸੂਰਾਤੂੰਕਹੀਅਹਿਭੋਗਨਮਹਿਭੋਗੀ॥","meaning":"ਹੇ ਕਰਤਾਰ! ਸੂਰਮਿਆਂ ਵਿਚ ਤੂੰ ਸ਼ਿਰੋਮਣੀ ਸੂਰਮਾ ਅਖਵਾਣ ਦਾ ਹੱਕਦਾਰ ਹੈਂ, (ਦੁਨੀਆ ਦੇ ਸਭ ਜੀਵਾਂ ਵਿਚ ਵਿਆਪਕ ਹੋਣ ਕਰ ਕੇ) ਭੋਗੀਆਂ ਵਿਚ ਤੂੰ ਹੀ ਭੋਗੀ ਹੈਂ ।"},{"gurmukhi":"ਗ੍ਰਸਤਨਮਹਿਤੂੰਬਡੋਗ੍ਰਿਹਸਤੀਜੋਗਨਮਹਿਜੋਗੀ॥੩॥","meaning":"ਗ੍ਰਿਹਸਤੀਆਂ ਵਿਚ ਤੂੰ ਸਭ ਤੋਂ ਵੱਡਾ ਗ੍ਰਿਹਸਤੀ ਹੈਂ (ਜਿਸ ਦਾ ਇਤਨਾ ਵੱਡਾ ਸੰਸਾਰ-ਟੱਬਰ ਹੈ), ਜੋਗੀਆਂ ਵਿਚ ਤੂੰ ਸ਼ਿਰੋਮਣੀ ਜੋਗੀ ਹੈਂ (ਇਤਨੇ ਵੱਡੇ ਪਰਵਾਰ ਵਾਲਾ ਹੁੰਦਿਆਂ ਭੀ ਨਿਰਲੇਪ ਹੈਂ) ।੩।"},{"gurmukhi":"ਕਰਤਨਮਹਿਤੂੰਕਰਤਾਕਹੀਅਹਿਆਚਾਰਨਮਹਿਆਚਾਰੀ॥","meaning":"ਹੇ ਕਰਤਾਰ! ਨਵੇਂ ਕੰਮ ਕਰਨ ਵਾਲੇ ਸਿਆਣਿਆਂ ਵਿਚ ਤੂੰ ਸ਼ਿਰੋਮਣੀ ਰਚਨਹਾਰ ਹੈ; ਧਾਰਮਿਕ ਰਸਮਾਂ ਕਰਨ ਵਾਲਿਆਂ ਵਿਚ ਭੀ ਤੂੰ ਹੀ ਸ਼ਿਰੋਮਣੀ ਹੈਂ ।"},{"gurmukhi":"ਸਾਹਨਮਹਿਤੂੰਸਾਚਾਸਾਹਾਵਾਪਾਰਨਮਹਿਵਾਪਾਰੀ॥੪॥","meaning":"ਹੇ ਕਰਤਾਰ! (ਦੁਨੀਆ ਦੇ) ਸਾਹੂਕਾਰਾਂ ਵਿਚ ਤੂੰ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ (ਸ਼ਿਰੋਮਣੀ) ਸਾਹੂਕਾਰ ਹੈਂ, ਤੇ ਵਾਪਾਰੀਆਂ ਵਿਚ ਤੂੰ ਵੱਡਾ ਵਾਪਾਰੀ ਹੈਂ (ਜਿਸ ਨੇ ਇਤਨਾ ਵੱਡਾ ਜਗਤ-ਪਸਾਰਾ ਪਸਾਰਿਆ ਹੋਇਆ ਹੈ) ।੪।"},{"gurmukhi":"ਦਰਬਾਰਨਮਹਿਤੇਰੋਦਰਬਾਰਾਸਰਨਪਾਲਨਟੀਕਾ॥","meaning":"ਹੇ ਕਰਤਾਰ! (ਦੁਨੀਆ ਦੇ) ਦਰਬਾਰ ਲਾਣ ਵਾਲਿਆਂ ਵਿਚ ਤੇਰਾ ਦਰਬਾਰ ਸ਼ਿਰੋਮਣੀ ਹੈ, ਸਰਨ ਪਿਆਂ ਦੀ ਲਾਜ ਰੱਖਣ ਵਾਲਿਆਂ ਦਾ ਤੂੰ ਸ਼ਿਰੋਮਣੀ ਟਿੱਕਾ ਹੈਂ ।"},{"gurmukhi":"ਲਖਿਮੀਕੇਤਕਗਨੀਨਜਾਈਐਗਨਿਨਸਕਉਸੀਕਾ॥੫॥","meaning":"ਹੇ ਕਰਤਾਰ! ਤੇਰੇ ਘਰ ਵਿਚ ਕਿਤਨੀ ਕੁ ਮਾਇਆ ਹੈ—ਇਸ ਦਾ ਅੰਦਾਜ਼ਾ ਨਹੀਂ ਲਾਇਆ ਜਾ ਸਕਦਾ । ਮੈਂ ਤੇਰੇ ਖ਼ਜ਼ਾਨੇ ਗਿਣ ਨਹੀਂ ਸਕਦਾ ।੫।"},{"gurmukhi":"ਨਾਮਨਮਹਿਤੇਰੋਪ੍ਰਭਨਾਮਾਗਿਆਨਨਮਹਿਗਿਆਨੀ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! (ਦੁਨੀਆ ਦੇ) ਵਡਿਆਈ-ਨਾਮਣੇ ਵਾਲਿਆਂ ਵਿਚੋਂ ਤੇਰਾ ਨਾਮਣਾ ਸ਼ਿਰੋਮਣੀ ਹੈ, ਤੇ ਗਿਆਨਵਾਨਾਂ ਵਿਚ ਤੂੰ ਹੀ ਸ਼ਿਰੋਮਣੀ ਗਿਆਨੀ ਹੈਂ ।"},{"gurmukhi":"ਜੁਗਤਨਮਹਿਤੇਰੀਪ੍ਰਭਜੁਗਤਾਇਸਨਾਨਨਮਹਿਇਸਨਾਨੀ॥੬॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਚੰਗੀ ਜੀਵਨ-ਜੁਗਤਿ ਵਾਲਿਆਂ ਵਿਚ ਤੇਰੀ ਜੁਗਤਿ ਸ੍ਰੇਸ਼ਟ ਹੈ, (ਦੁਨੀਆ ਦੇ ਤੀਰਥ-) ਇਸ਼ਨਾਨੀਆਂ ਵਿਚ ਤੂੰ ਸ਼ਿਰੋਮਣੀ ਇਸ਼ਨਾਨੀ ਹੈਂ (ਕਿਉਂਕਿ ਸਾਰੇ ਜਲਾਂ ਵਿਚ ਤੂੰ ਸਦਾ ਆਪ ਹੀ ਵੱਸ ਰਿਹਾ ਹੈਂ) ।੬।"},{"gurmukhi":"ਸਿਧਨਮਹਿਤੇਰੀਪ੍ਰਭਸਿਧਾਕਰਮਨਸਿਰਿਕਰਮਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਕਰਾਮਾਤੀ ਤਾਕਤਾਂ ਰੱਖਣ ਵਾਲਿਆਂ ਵਿਚ ਤੇਰੀ ਕਰਾਮਾਤੀ ਤਾਕਤ ਸ਼ਿਰੋਮਣੀ ਹੈ, ਕੰਮ ਕਰਨ ਵਾਲਿਆਂ ਵਿਚ ਤੂੰ ਸ਼ਿਰੋਮਣੀ ਉੱਦਮੀ ਹੈਂ ।"},{"gurmukhi":"ਆਗਿਆਮਹਿਤੇਰੀਪ੍ਰਭਆਗਿਆਹੁਕਮਨਸਿਰਿਹੁਕਮਾ॥੭॥","meaning":"ਹੇ ਪ੍ਰਭੂ! (ਦੁਨੀਆ ਦੇ) ਇਖ਼ਤਿਆਰ ਵਾਲਿਆਂ ਵਿਚ ਤੇਰਾ ਇਖ਼ਤਿਆਰ ਸਭ ਤੋਂ ਵੱਡਾ ਹੈ, (ਦੁਨੀਆ ਦੇ) ਹੁਕਮ ਚਲਾਣ ਵਾਲਿਆਂ ਵਿਚ ਤੂੰ ਸ਼ਿਰੋਮਣੀ ਹਾਕਮ ਹੈਂ ।੭।"},{"gurmukhi":"ਜਿਉਬੋਲਾਵਹਿਤਿਉਬੋਲਹਸੁਆਮੀਕੁਦਰਤਿਕਵਨਹਮਾਰੀ॥","meaning":"ਹੇ ਕਰਤਾਰ! ਹੇ ਸੁਆਮੀ! ਸਾਡੀ (ਤੇਰੇ ਪੈਦਾ ਕੀਤੇ ਹੋਏ ਜੀਵਾਂ ਦੀ) ਕੀਹ ਪਾਇਆਂ ਹੈ? ਜਿਵੇਂ ਤੂੰ ਸਾਨੂੰ ਬੁਲਾਂਦਾ ਹੈਂ ਉਸੇ ਤਰ੍ਹਾਂ ਅਸੀ ਬੋਲਦੇ ਹਾਂ ।"},{"gurmukhi":"ਸਾਧਸੰਗਿਨਾਨਕਜਸੁਗਾਇਓਜੋਪ੍ਰਭਕੀਅਤਿਪਿਆਰੀ॥੮॥੧॥੮॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—ਕਰਤਾਰ ਦੀ ਪ੍ਰੇਰਨਾ ਨਾਲ ਹੀ ਮਨੁੱਖ ਨੇ) ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਟਿਕ ਕੇ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕੀਤੀ ਹੈ, ਇਹ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਪ੍ਰਭੂ ਨੂੰ ਬੜੀ ਪਿਆਰੀ ਲੱਗਦੀ ਹੈ ।੮।੧।੮।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (45, 'ਛੰਤ॥', '[{"gurmukhi":"ਭਿੰਨੀਰੈਨੜੀਐਚਾਮਕਨਿਤਾਰੇ॥","meaning":"(ਹੇ ਭਾਈ!) ਤੇ੍ਰਲ ਭਿੱਜੀ ਰਾਤ ਵਿਚ (ਆਕਾਸ਼ ਵਿਚ) ਤਾਰੇ ਡਲ੍ਹਕਦੇ ਹਨ (ਤਿਵੇਂ, ਪਰਮਾਤਮਾ ਦੇ ਪ੍ਰੇਮ ਵਿਚ ਭਿੱਜੇ ਹੋਏ ਹਿਰਦੇ ਵਾਲੇ ਮਨੁੱਖਾਂ ਦੇ ਚਿੱਤ-ਆਕਾਸ਼ ਵਿਚ ਸੋਹਣੇ ਆਤਮਕ ਗੁਣ ਲਿਸ਼ਕਾਂ ਮਾਰਦੇ ਹਨ) ।"},{"gurmukhi":"ਜਾਗਹਿਸੰਤਜਨਾਮੇਰੇਰਾਮਪਿਆਰੇ॥","meaning":"ਮੇਰੇ ਰਾਮ ਦੇ ਪਿਆਰੇ ਸੰਤ ਜਨ (ਸਿਮਰਨ ਦੀ ਬਰਕਤਿ ਨਾਲ ਮਾਇਆ ਦੇ ਹੱਲਿਆਂ ਵਲੋਂ) ਸੁਚੇਤ ਰਹਿੰਦੇ ਹਨ ।"},{"gurmukhi":"ਰਾਮਪਿਆਰੇਸਦਾਜਾਗਹਿਨਾਮੁਸਿਮਰਹਿਅਨਦਿਨੋ॥","meaning":"ਪਰਮਾਤਮਾ ਦੇ ਪਿਆਰੇ ਸੰਤ ਜਨ ਸਦਾ ਹੀ ਸੁਚੇਤ ਰਹਿੰਦੇ ਹਨ, ਹਰ ਵੇਲੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰਦੇ ਹਨ ।"},{"gurmukhi":"ਚਰਣਕਮਲਧਿਆਨੁਹਿਰਦੈਪ੍ਰਭਬਿਸਰੁਨਾਹੀਇਕੁਖਿਨੋ॥","meaning":"ਸੰਤ ਜਨ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਪਰਮਾਤਮਾ ਦੇ ਸੋਹਣੇ ਕੋਮਲ ਚਰਨਾਂ ਦਾ ਧਿਆਨ ਧਰਦੇ ਹਨ (ਤੇ, ਉਸ ਦੇ ਦਰ ਤੇ ਅਰਦਾਸ ਕਰਦੇ ਹਨ—) ਹੇ ਪ੍ਰਭੂ ਰਤਾ ਜਿਤਨੇ ਸਮੇ ਲਈ ਭੀ ਸਾਡੇ ਦਿਲ ਤੋਂ ਦੂਰ ਨਾਹ ਹੋ ।"},{"gurmukhi":"ਤਜਿਮਾਨੁਮੋਹੁਬਿਕਾਰੁਮਨਕਾਕਲਮਲਾਦੁਖਜਾਰੇ॥","meaning":"ਸੰਤ ਜਨ ਆਪਣੇ ਮਨ ਦਾ ਮਾਣ ਛੱਡ ਕੇ, ਮੋਹ ਤੇ ਵਿਕਾਰ ਦੂਰ ਕਰਕੇ ਆਪਣੇ ਸਾਰੇ ਦੁੱਖ ਪਾਪ ਸਾੜ ਲੈਂਦੇ ਹਨ ।"},{"gurmukhi":"ਬਿਨਵੰਤਿਨਾਨਕਸਦਾਜਾਗਹਿਹਰਿਦਾਸਸੰਤਪਿਆਰੇ॥੧॥","meaning":"ਨਾਨਕ ਬੇਨਤੀ ਕਰਦਾ ਹੈ—(ਹੇ ਭਾਈ!) ਪਰਮਾਤਮਾ ਦੇ ਪਿਆਰੇ ਸੰਤ ਪਰਮਾਤਮਾ ਦੇ ਦਾਸ ਸਦਾ (ਮਾਇਆ ਦੇ ਹੱਲਿਆਂ ਵਲੋਂ) ਸੁਚੇਤ ਰਹਿੰਦੇ ਹਨ ।੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (46, 'ਸਾਰਗਮਹਲਾ੫ਦੁਪਦੇਘਰੁ੪', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਮੋਹਨਘਰਿਆਵਹੁਕਰਉਜੋਦਰੀਆ॥","meaning":"ਹੇ ਮੋਹਨ-ਪ੍ਰਭੂ! ਮੈਂ ਮਿੰਨਤ ਕਰਦੀ ਹਾਂ ਮੇਰੇ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਆ ਵੱਸ ।"},{"gurmukhi":"ਮਾਨੁਕਰਉਅਭਿਮਾਨੈਬੋਲਉਭੂਲਚੂਕਤੇਰੀਪ੍ਰਿਅਚਿਰੀਆ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਮੋਹਨ! ਮੈਂ (ਸਦਾ) ਮਾਣ ਕਰਦੀ ਰਹਿੰਦੀ ਹਾਂ, ਮੈਂ (ਸਦਾ) ਅਹੰਕਾਰ ਨਾਲ ਗੱਲਾਂ ਕਰਦੀ ਹਾਂ, ਮੈਂ ਬਥੇਰੀਆਂ ਭੁੱਲਾਂ-ਚੁੱਕਾਂ ਕਰਦੀ ਹਾਂ, (ਫਿਰ ਭੀ) ਹੇ ਪਿਆਰੇ! ਮੈਂ ਤੇਰੀ (ਹੀ) ਦਾਸੀ ਹਾਂ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਨਿਕਟਿਸੁਨਉਅਰੁਪੇਖਉਨਾਹੀਭਰਮਿਭਰਮਿਦੁਖਭਰੀਆ॥","meaning":"ਹੇ ਮੋਹਨ! ਮੈਂ ਸੁਣਦੀ ਹਾਂ (ਤੂੰ) ਨੇੜੇ (ਵੱਸਦਾ ਹੈਂ), ਪਰ ਮੈਂ (ਤੈਨੂੰ) ਵੇਖ ਨਹੀਂ ਸਕਦੀ । ਸਦਾ ਭਟਕ ਭਟਕ ਕੇ ਮੈਂ ਦੁੱਖਾਂ ਵਿਚ ਫਸੀ ਰਹਿੰਦੀ ਹਾਂ ।"},{"gurmukhi":"ਹੋਇਕ੍ਰਿਪਾਲਗੁਰਲਾਹਿਪਾਰਦੋਮਿਲਉਲਾਲਮਨੁਹਰੀਆ॥੧॥","meaning":"ਹੇ ਗੁਰੂ! ਜੇ ਤੂੰ ਦਇਆਵਾਨ ਹੋ ਕੇ (ਮੇਰੇ ਅੰਦਰੋਂ ਮਾਇਆ ਦੇ ਮੋਹ ਦਾ) ਪਰਦਾ ਦੂਰ ਕਰ ਦੇਵੇਂ, ਮੈਂ (ਸੋਹਣੇ) ਲਾਲ (ਪ੍ਰਭੂ) ਨੂੰ ਮਿਲ ਪਵਾਂ, ਤੇ, ਮੇਰਾ ਮਨ (ਆਤਮਕ ਜੀਵਨ ਨਾਲ) ਹਰ-ਭਰਾ ਹੋ ਜਾਏ ।੧।"},{"gurmukhi":"ਏਕਨਿਮਖਜੇਬਿਸਰੈਸੁਆਮੀਜਾਨਉਕੋਟਿਦਿਨਸਲਖਬਰੀਆ॥","meaning":"ਹੇ ਭਾਈ! ਜੇ ਅੱਖ ਝਮਕਣ ਜਿਤਨੇ ਸਮੇ ਲਈ ਭੀ ਮਾਲਕ-ਪ੍ਰਭੂ (ਮਨ ਤੋਂ) ਭੱੁਲ ਜਾਏ, ਤਾਂ ਮੈਂ ਇਉਂ ਸਮਝਦੀ ਹਾਂ ਕਿ ਕ੍ਰੋੜਾਂ ਦਿਨ ਲੱਖਾਂ ਵਰ੍ਹੇ ਲੰਘ ਗਏ ਹਨ ।"},{"gurmukhi":"ਸਾਧਸੰਗਤਿਕੀਭੀਰਜਉਪਾਈਤਉਨਾਨਕਹਰਿਸੰਗਿਮਿਰੀਆ॥੨॥੧॥੨੪॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਜਦੋਂ ਮੈਨੂੰ ਸਾਧ ਸੰਗਤਿ ਦਾ ਸਮਾਗਮ ਪ੍ਰਾਪਤ ਹੋਇਆ, ਤਦੋਂ ਪਰਮਾਤਮਾ ਨਾਲ ਮੇਲ ਹੋ ਗਿਆ ।੨।੧।੨੪।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (47, 'ਸੁਣਿਸਖੀਏਮੇਰੀਨੀਦਭਲੀਮੈਆਪਨੜਾਪਿਰੁਮਿਲਿਆ॥', '[{"gurmukhi":"","meaning":"ਹੇ ਸਹੇਲੀਏ! ਸੁਣ, (ਹੁਣ) ਮੈਨੂੰ ਨੀਂਦ ਭੀ ਪਿਆਰੀ ਲੱਗਦੀ ਹੈ, (ਕਿਉਂਕਿ ਸੁਪਨੇ ਵਿਚ ਭੀ) ਮੈਨੂੰ ਆਪਣਾ ਪਿਆਰਾ ਪਤੀ ਮਿਲ ਪੈਂਦਾ ਹੈ ।"},{"gurmukhi":"ਭ੍ਰਮੁਖੋਇਓਸਾਂਤਿਸਹਜਿਸੁਆਮੀਪਰਗਾਸੁਭਇਆਕਉਲੁਖਿਲਿਆ॥","meaning":"ਉਸ ਮਾਲਕ-ਪ੍ਰਭੂ ਨੇ ਮੇਰੀ ਭਟਕਣਾ ਦੂਰ ਕਰ ਦਿੱਤੀ ਹੈ, ਮੇਰੇ ਅੰਦਰ ਹੁਣ ਸ਼ਾਂਤੀ ਬਣੀ ਰਹਿੰਦੀ ਹੈ, ਮੈਂ ਆਤਮਕ ਅਡੋਲਤਾ ਵਿਚ ਟਿਕੀ ਰਹਿੰਦੀ ਹਾਂ, (ਮੇਰੇ ਅੰਦਰ ਉਸ ਦੀ ਜੋਤਿ ਦਾ) ਚਾਨਣ ਹੋ ਗਿਆ ਹੈ (ਜਿਵੇਂ ਸੂਰਜ ਦੀਆਂ ਕਿਰਨਾਂ ਨਾਲ)) ਕੌਲ-ਫੁੱਲ ਖਿੜ ਪੈਂਦਾ ਹੈ (ਤਿਵੇਂ ਉਸ ਦੀ ਜੋਤਿ ਦੇ ਚਾਨਣ ਨਾਲ ਮੇਰਾ ਹਿਰਦਾ ਖਿੜਿਆ ਰਹਿੰਦਾ ਹੈ) ।"},{"gurmukhi":"ਵਰੁਪਾਇਆਪ੍ਰਭੁਅੰਤਰਜਾਮੀਨਾਨਕਸੋਹਾਗੁਨਟਲਿਆ॥੪॥੪॥੨॥੫॥੧੧॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—ਹੇ ਸਹੇਲੀਏ! ਸਾਧ ਸੰਗਤਿ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਮੈਂ ਅੰਤਰਜਾਮੀ ਪ੍ਰਭੂ-ਖਸਮ ਲੱਭ ਲਿਆ ਹੈ, ਤੇ (ਮੇਰੇ ਸਿਰ ਦਾ) ਇਹ ਸੁਹਾਗ ਕਦੇ ਦੂਰ ਹੋਣ ਵਾਲਾ ਨਹੀਂ ।੪।੪।੨।੫।੧੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (48, 'ਬਸੰਤੁਮਹਲਾ੫॥', '[{"gurmukhi":"ਜੀਅਪ੍ਰਾਣਤੁਮ੍ਹਪਿੰਡਦੀਨ੍ਹ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! (ਸਭ ਜੀਵਾਂ ਨੂੰ) ਜਿੰਦ, ਪ੍ਰਾਣ, ਸਰੀਰ ਤੂੰ ਹੀ ਦਿੱਤੇ ਹਨ ।"},{"gurmukhi":"ਮੁਗਧਸੁੰਦਰਧਾਰਿਜੋਤਿਕੀਨ੍ਹ॥","meaning":"ਆਪਣੀ ਜੋਤਿ ਤੂੰ (ਸਰੀਰਾਂ ਵਿਚ) ਟਿਕਾ ਕੇ ਮੂਰਖਾਂ ਨੂੰ ਸੋਹਣੇ ਬਣਾ ਦੇਂਦਾ ਹੈਂ ।"},{"gurmukhi":"ਸਭਿਜਾਚਿਕਪ੍ਰਭਤੁਮ੍ਹਦਇਆਲ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਸਾਰੇ ਜੀਵ (ਤੇਰੇ ਦਰ ਦੇ) ਮੰਗਤੇ ਹਨ, ਤੂੰ ਸਭ ਉੱਤੇ ਦਇਆ ਕਰਨ ਵਾਲਾ ਹੈਂ ।"},{"gurmukhi":"ਨਾਮੁਜਪਤਹੋਵਤਨਿਹਾਲ॥੧॥","meaning":"ਤੇਰਾ ਨਾਮ ਜਪਦਿਆਂ ਜੀਵ ਪ੍ਰਸੰਨ-ਚਿੱਤ ਹੋ ਜਾਂਦੇ ਹਨ ।੧।"},{"gurmukhi":"ਮੇਰੇਪ੍ਰੀਤਮਕਾਰਣਕਰਣਜੋਗ॥","meaning":"ਹੇ ਸਭ ਕੁਝ ਕਰਨ ਦੀ ਸਮਰਥਾ ਵਾਲੇ!"},{"gurmukhi":"ਹਉਪਾਵਉਤੁਮਤੇਸਗਲਥੋਕ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰੀਤਮ! ਮੈਂ ਤੇਰੇ ਪਾਸੋਂ ਹੀ ਸਾਰੇ ਪਦਾਰਥ ਹਾਸਲ ਕਰਦਾ ਹਾਂ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਨਾਮੁਜਪਤਹੋਵਤਉਧਾਰ॥","meaning":"ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਜਪਦਿਆਂ (ਜਗਤ ਤੋਂ) ਪਾਰ-ਉਤਾਰਾ ਹੁੰਦਾ ਹੈ,"},{"gurmukhi":"ਨਾਮੁਜਪਤਸੁਖਸਹਜਸਾਰ॥","meaning":"ਆਤਮਕ ਅਡੋਲਤਾ ਦੇ ਸੇ੍ਰਸ਼ਟ ਸੁਖ ਪ੍ਰਾਪਤ ਹੋ ਜਾਂਦੇ ਹਨ,"},{"gurmukhi":"ਨਾਮੁਜਪਤਪਤਿਸੋਭਾਹੋਇ॥","meaning":"(ਲੋਕ ਪਰਲੋਕ ਵਿਚ) ਇੱਜ਼ਤ ਸੋਭਾ ਮਿਲਦੀ ਹੈ,"},{"gurmukhi":"ਨਾਮੁਜਪਤਬਿਘਨੁਨਾਹੀਕੋਇ॥੨॥","meaning":"(ਜੀਵਨ-ਸਫ਼ਰ ਵਿਚ ਵਿਕਾਰਾਂ ਵਲੋਂ) ਕੋਈ ਰੁਕਵਾਟ ਨਹੀਂ ਪੈਂਦੀ ।੨।"},{"gurmukhi":"ਜਾਕਾਰਣਿਇਹਦੁਲਭਦੇਹ॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ! ਜਿਸ ਹਰਿ-ਨਾਮ ਦੇ ਜਪਣ ਵਾਸਤੇ (ਤੇਰੀ ਮਿਹਰ ਨਾਲ) ਇਹ ਦੁਰਲੱਭ ਮਨੁੱਖਾ ਸਰੀਰ ਮਿਲਿਆ ਹੈ,"},{"gurmukhi":"ਸੋਬੋਲੁਮੇਰੇਪ੍ਰਭੂਦੇਹਿ॥","meaning":"ਉਹ ਹਰਿ-ਨਾਮ ਮੈਨੂੰ ਬਖ਼ਸ਼ ।"},{"gurmukhi":"ਸਾਧਸੰਗਤਿਮਹਿਇਹੁਬਿਸ੍ਰਾਮੁ॥","meaning":"(ਮੇਰਾ) ਇਹ (ਮਨ) ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਟਿਕਾਣਾ ਪ੍ਰਾਪਤ ਕਰੀ ਰੱਖੇ ।"},{"gurmukhi":"ਸਦਾਰਿਦੈਜਪੀਪ੍ਰਭਤੇਰੋਨਾਮੁ॥੩॥","meaning":"ਹੇ ਪ੍ਰਭੂ! (ਮਿਹਰ ਕਰ) ਮੈਂ ਸਦਾ ਤੇਰਾ ਨਾਮ ਜਪਦਾ ਰਹਾਂ ।੩।"},{"gurmukhi":"ਤੁਝਬਿਨੁਦੂਜਾਕੋਇਨਾਹਿ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੈਥੋਂ ਬਿਨਾ ਮੈਨੂੰ ਕੋਈ ਹੋਰ (ਆਸਰਾ) ਨਹੀਂ ਹੈ ।"},{"gurmukhi":"ਸਭੁਤੇਰੋਖੇਲੁਤੁਝਮਹਿਸਮਾਹਿ॥","meaning":"ਇਹ ਸਾਰਾ ਜਗਤ-ਤਮਾਸ਼ਾ ਤੇਰਾ ਹੀ ਬਣਾਇਆ ਹੋਇਆ ਹੈ ।"},{"gurmukhi":"ਜਿਉਭਾਵੈਤਿਉਰਾਖਿਲੇ॥","meaning":"ਸਾਰੇ ਜੀਵ ਤੇਰੇ ਵਿਚ ਹੀ ਲੀਨ ਹੋ ਜਾਂਦੇ ਹਨ । ਜਿਵੇਂ ਤੈਨੂੰ ਚੰਗਾ ਲੱਗੇ ਤਿਵੇਂ (ਮੇਰੀ) ਰੱਖਿਆ ਕਰ ।"},{"gurmukhi":"ਸੁਖੁਨਾਨਕਪੂਰਾਗੁਰੁਮਿਲੇ॥੪॥੪॥","meaning":"ਹੇ ਨਾਨਕ! ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਪੂਰਾ ਗੁਰੂ ਮਿਲ ਪੈਂਦਾ ਹੈ, ਉਸ ਨੂੰ ਆਤਮਕ ਆਨੰਦ ਪ੍ਰਾਪਤ ਹੁੰਦਾ ਹੈ ।੪।੪।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (49, 'ਮਲਾਰਮਹਲਾ੫॥', '[{"gurmukhi":"ਪ੍ਰਭਮੇਰੇਪ੍ਰੀਤਮਪ੍ਰਾਨਪਿਆਰੇ॥","meaning":"ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ! ਹੇ ਮੇਰੇ ਪ੍ਰੀਤਮ! ਹੇ ਮੇਰੀ ਜਿੰਦ ਤੋਂ ਪਿਆਰੇ!"},{"gurmukhi":"ਪ੍ਰੇਮਭਗਤਿਅਪਨੋਨਾਮੁਦੀਜੈਦਇਆਲਅਨੁਗ੍ਰਹੁਧਾਰੇ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਦਇਆ ਦੇ ਸੋਮੇ ਪ੍ਰਭੂ! (ਮੇਰੇ ਉਤੇ) ਮਿਹਰ ਕਰ । ਮੈਨੂੰ ਆਪਣਾ ਪਿਆਰ ਬਖ਼ਸ਼, ਮੈਨੂੰ ਆਪਣੀ ਭਗਤੀ ਦੇਹ, ਮੈਨੂੰ ਆਪਣਾ ਨਾਮ ਦੇਹ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਸਿਮਰਉਚਰਨਤੁਹਾਰੇਪ੍ਰੀਤਮਰਿਦੈਤੁਹਾਰੀਆਸਾ॥","meaning":"ਹੇ ਪ੍ਰੀਤਮ! ਮੈਂ ਤੇਰੇ ਚਰਨਾਂ ਦਾ ਧਿਆਨ ਧਰਦਾ ਰਹਾਂ, ਮੇਰੇ ਹਿਰਦੇ ਵਿਚ ਤੇਰੀ ਆਸ ਟਿਕੀ ਰਹੀ ।"},{"gurmukhi":"ਸੰਤਜਨਾਪਹਿਕਰਉਬੇਨਤੀਮਨਿਦਰਸਨਕੀਪਿਆਸਾ॥੧॥","meaning":"ਮੈਂ ਸੰਤ ਜਨਾਂ ਪਾਸ ਬੇਨਤੀ ਕਰਦਾ ਰਹਿੰਦਾ ਹਾਂ (ਕਿ ਮੈਨੂੰ ਤੇਰਾ ਦਰਸਨ ਕਰਾ ਦੇਣ, ਮੇਰੇ) ਮਨ ਵਿਚ (ਤੇਰੇ) ਦਰਸਨ ਦੀ ਬੜੀ ਤਾਂਘ ਹੈ ।੧।"},{"gurmukhi":"ਬਿਛੁਰਤਮਰਨੁਜੀਵਨੁਹਰਿਮਿਲਤੇਜਨਕਉਦਰਸਨੁਦੀਜੈ॥","meaning":"ਹੇ ਪ੍ਰੀਤਮ ਪ੍ਰਭੂ! ਤੈਥੋਂ ਵਿਛੁੜਿਆਂ ਆਤਮਕ ਮੌਤ ਹੋ ਜਾਂਦੀ ਹੈ, ਤੈਨੂੰ ਮਿਲਿਆਂ ਆਤਮਕ ਜੀਵਨ ਮਿਲਦਾ ਹੈ । ਹੇ ਪ੍ਰਭੂ! ਆਪਣੇ ਸੇਵਕ ਨੂੰ ਦਰਸਨ ਦੇਹ ।"},{"gurmukhi":"ਨਾਮਅਧਾਰੁਜੀਵਨਧਨੁਨਾਨਕਪ੍ਰਭਮੇਰੇਕਿਰਪਾਕੀਜੈ॥੨॥੫॥੯॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ! ਮਿਹਰ ਕਰ, ਤੇਰੇ ਨਾਮ ਦਾ ਆਸਰਾ (ਮੈਨੂੰ ਮਿਲਿਆ ਰਹੇ, ਇਹੀ ਹੈ ਮੇਰੀ) ਜ਼ਿੰਦਗੀ ਦਾ ਸਰਮਾਇਆ ।੨।੫।੯।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (50, 'ਸਲੋਕਮਃ੪॥', '[{"gurmukhi":"ਹਮਰੀਜਿਹਬਾਏਕਪ੍ਰਭਹਰਿਕੇਗੁਣਅਗਮਅਥਾਹ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਹੇ ਹਰੀ! ਅਸਾਂ ਜੀਵਾਂ ਦੀ (ਸਿਰਫ਼) ਇੱਕ ਜੀਭ ਹੈ, ਪਰ ਤੇਰੇ ਗੁਣ ਬੇਅੰਤ ਹਨ (ਇਕ ਐਸਾ ਸਮੁੰਦਰ ਹਨ) ਜਿਸ ਦੀ ਹਾਥ ਨਹੀਂ ਪੈ ਸਕਦੀ ।"},{"gurmukhi":"ਹਮਕਿਉਕਰਿਜਪਹਇਆਣਿਆਹਰਿਤੁਮਵਡਅਗਮਅਗਾਹ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਬਹੁਤ ਅਪਹੁੰਚ ਹੈਂ ਤੇ ਡੂੰਘਾ ਹੈਂ ਅਸੀ ਅੰਞਾਣ ਜੀਵ ਤੈਨੂੰ ਕਿਵੇਂ ਜਪ ਸਕਦੇ ਹਾਂ?"},{"gurmukhi":"ਹਰਿਦੇਹੁਪ੍ਰਭੂਮਤਿਊਤਮਾਗੁਰਸਤਿਗੁਰਕੈਪਗਿਪਾਹ॥","meaning":"? ਹੇ ਹਰੀ! ਸਾਨੂੰ ਕੋਈ ਸ੍ਰੇਸ਼ਟ ਅਕਲ ਬਖ਼ਸ਼ ਜਿਸ ਦਾ ਸਦਕਾ ਅਸੀ ਗੁਰੂ ਦੇ ਚਰਨਾਂ ਉਤੇ ਢਹਿ ਪਈਏ ।"},{"gurmukhi":"ਸਤਸੰਗਤਿਹਰਿਮੇਲਿਪ੍ਰਭਹਮਪਾਪੀਸੰਗਿਤਰਾਹ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਹੇ ਹਰੀ! ਸਾਨੂੰ ਸਾਧ ਸੰਗਤਿ ਮਿਲਾ ਕਿ (ਸਤ ਸੰਗੀਆਂ ਦੀ) ਸੰਗਤਿ ਵਿਚ ਅਸੀ ਪਾਪੀ (ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ) ਪਾਰ ਲੰਘ ਜਾਈਏ ।"},{"gurmukhi":"ਜਨਨਾਨਕਕਉਹਰਿਬਖਸਿਲੈਹੁਹਰਿਤੁਠੈਮੇਲਿਮਿਲਾਹ॥","meaning":"ਹੇ ਹਰੀ! (ਆਪਣੇ) ਦਾਸ ਨਾਨਕ ਉਤੇ ਮਿਹਰ ਕਰ, ਜੇ ਤੂੰ ਮਿਹਰ ਕਰੇਂ ਤਾਂ ਹੀ ਅਸੀ ਤੇਰੇ ਚਰਨਾਂ ਵਿਚ ਮਿਲ ਸਕਦੇ ਹਾਂ ।"},{"gurmukhi":"ਹਰਿਕਿਰਪਾਕਰਿਸੁਣਿਬੇਨਤੀਹਮਪਾਪੀਕਿਰਮਤਰਾਹ॥੧॥","meaning":"ਹੇ ਹਰੀ! ਕਿਰਪਾ ਕਰ, (ਅਸਾਡੀ) ਬੇਨਤੀ ਸੁਣ, ਅਸੀ ਪਾਪੀ ਅਸੀ ਕੀੜੇ (ਇਸ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ) ਪਾਰ ਲੰਘ ਸਕੀਏ ।੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (51, 'ਆਸਾਵਰੀਮਹਲਾ੫॥', '[{"gurmukhi":"ਕਾਰਨਕਰਨਤੂੰਹਾਂ॥","meaning":"ਹੇ ਮੇਰੇ ਮਨ! (ਪ੍ਰਭੂ-ਦਰ ਤੇ ਇਉਂ ਅਰਦਾਸ ਕਰ—ਹੇ ਪ੍ਰਭੂ!) ਤੂੰ ਸਾਰੇ ਜਗਤ ਦਾ ਰਚਨਹਾਰ ਹੈਂ"},{"gurmukhi":"ਅਵਰੁਨਾਸੁਝੈਮੂੰਹਾਂ॥","meaning":"(ਤੈਥੋਂ ਬਿਨਾ) ਮੈਨੂੰ ਕੋਈ ਹੋਰ ਨਹੀਂ ਸੁੱਝਦਾ (ਜੋ ਇਹ ਤਾਕਤ ਰੱਖਦਾ ਹੋਵੇ)"},{"gurmukhi":"ਕਰਹਿਸੁਹੋਈਐਹਾਂ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜੋ ਕੁਝ ਤੂੰ ਕਰਦਾ ਹੈਂ ਉਹੀ (ਜਗਤ ਵਿਚ) ਵਰਤਦਾ ਹੈ"},{"gurmukhi":"ਸਹਜਿਸੁਖਿਸੋਈਐਹਾਂ॥","meaning":"ਹੇ ਮੇਰੇ ਮਨ! (ਜੇ ਆਪਣੀਆਂ ਚਤੁਰਾਈਆਂ ਛੱਡ ਕੇ) ਪਰਮਾਤਮਾ ਦੇ ਦਰ ਤੇ ਡਿੱਗ ਪਈਏ ਤਾਂ ਮਨ ਵਿਚ ਹੌਸਲਾ ਬੱਝ ਜਾਂਦਾ ਹੈ"},{"gurmukhi":"ਧੀਰਜਮਨਿਭਏਹਾਂ॥","meaning":"ਆਤਮਕ ਅਡੋਲਤਾ ਵਿਚ ਆਨੰਦ ਵਿਚ ਲੀਨ ਰਹਿ ਸਕੀਦਾ ਹੈ"},{"gurmukhi":"ਪ੍ਰਭਕੈਦਰਿਪਏਮੇਰੇਮਨਾ॥੧॥ਰਹਾਉ॥","meaning":""},{"gurmukhi":"ਸਾਧੂਸੰਗਮੇਹਾਂ॥","meaning":"ਹੇ ਮੇਰੇ ਮਨ । ਗੁਰੂ ਦੀ ਸੰਗਤਿ ਵਿਚ ਰਿਹਾਂ ਉਹ ਜੁਗਤਿ ਪੂਰਨ ਤੌਰ ਤੇ ਆ ਜਾਂਦੀ ਹੈ"},{"gurmukhi":"ਪੂਰਨਸੰਜਮੇਹਾਂ॥","meaning":"ਜਿਸ ਨਾਲ ਗਿਆਨ-ਇੰਦ੍ਰੇ ਵੱਸ ਵਿਚ ਆ ਜਾਂਦੇ ਹਨ"},{"gurmukhi":"ਜਬਤੇਛੁਟੇਆਪਹਾਂ॥","meaning":"ਹੇ ਮਨ! ਜਿਸ ਵੇਲੇ (ਮਨੁੱਖ ਦੇ ਅੰਦਰੋਂ) ਹਉਮੈ ਅਹੰਕਾਰ ਮੁੱਕ ਜਾਂਦਾ ਹੈ"},{"gurmukhi":"ਤਬਤੇਮਿਟੇਤਾਪਹਾਂ॥","meaning":"(ਤੇ ਗੁਰੂ ਦੀ ਓਟ ਠੀਕ ਜਾਪਦੀ ਹੈ) ਉਸੇ ਵੇਲੇ ਤੋਂ (ਮਨ ਦੇ) ਸਾਰੇ ਦੁੱਖ-ਕਲੇਸ਼ ਦੂਰ ਹੋ ਜਾਂਦੇ ਹਨ"},{"gurmukhi":"ਕਿਰਪਾਧਾਰੀਆਹਾਂ॥","meaning":"ਸੋ ਹੇ ਮੇਰੇ ਮਨ! (ਗੁਰੂ ਦੀ ਸੰਗਤਿ ਵਿਚ ਰਹਿ ਕੇ ਪ੍ਰਭੂ-ਦਰ ਤੇ ਅਰਦਾਸ ਕਰ, ਆਖ—)"},{"gurmukhi":"ਪਤਿਰਖੁਬਨਵਾਰੀਆਮੇਰੇਮਨਾ॥੧॥","meaning":"ਹੇ ਜਗਤ ਦੇ ਮਾਲਕ-ਪ੍ਰਭੂ! ਮੇਰੇ ਉੱਤੇ ਮੇਹਰ ਕਰ, ਮੇਰੀ (ਸਰਨ ਪਏ ਦੀ) ਇੱਜ਼ਤ ਰੱਖ ।੧।"},{"gurmukhi":"ਇਹੁਸੁਖੁਜਾਨੀਐਹਾਂ॥","meaning":"ਹੇ ਮੇਰੇ ਮਨ! ਜੋ ਕੁਝ ਪਰਮਾਤਮਾ ਕਰਦਾ ਹੈ ਉਸ ਨੂੰ (ਮਿੱਠਾ ਕਰ ਕੇ) ਮੰਨਣਾ ਚਾਹੀਦਾ ਹੈ"},{"gurmukhi":"ਹਰਿਕਰੇਸੁਮਾਨੀਐਹਾਂ॥","meaning":"ਇਸੇ ਨੂੰ ਹੀ ਸੁਖ (ਦਾ ਮੂਲ) ਸਮਝਣਾ ਚਾਹੀਦਾ ਹੈ"},{"gurmukhi":"ਮੰਦਾਨਾਹਿਕੋਇਹਾਂ॥","meaning":"ਹੇ ਮਨ! ਜੇਹੜਾ ਮਨੁੱਖ ਸੰਤ ਜਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਬਣਦਾ ਹੈ"},{"gurmukhi":"ਸੰਤਕੀਰੇਨਹੋਇਹਾਂ॥","meaning":"ਉਸ ਨੂੰ (ਜਗਤ ਵਿਚ) ਕੋਈ ਭੈੜਾ ਨਹੀਂ ਦਿੱਸਦਾ"},{"gurmukhi":"ਆਪੇਜਿਸੁਰਖੈਹਾਂ॥","meaning":"ਹੇ ਮੇਰੇ ਮਨ! ਪਰਮਾਤਮਾ ਆਪ ਹੀ ਜਿਸ ਮਨੁੱਖ ਨੂੰ (ਵਿਕਾਰਾਂ ਵਲੋਂ) ਬਚਾਂਦਾ ਹੈ"},{"gurmukhi":"ਹਰਿਅੰਮ੍ਰਿਤੁਸੋਚਖੈਮੇਰੇਮਨਾ॥੨॥","meaning":"ਉਹ ਮਨੁੱਖ ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲਾ ਹਰਿ-ਨਾਮ-ਜਲ ਪੀਂਦਾ ਹੈ"},{"gurmukhi":"ਜਿਸਕਾਨਾਹਿਕੋਇਹਾਂ॥","meaning":"ਹੇ ਮੇਰੇ ਮਨ! ਜਿਸ ਮਨੁੱਖ ਦਾ ਕੋਈ ਭੀ ਸਹਾਈ ਨਹੀਂ ਬਣਦਾ"},{"gurmukhi":"ਤਿਸਕਾਪ੍ਰਭੂਸੋਇਹਾਂ॥","meaning":"(ਜੇ ਉਹ ਪ੍ਰਭੂ ਦੀ ਸਰਨ ਆ ਪਏ, ਤਾਂ) ਉਹ ਪ੍ਰਭੂ ਉਸ ਦਾ ਰਾਖਾ ਬਣ ਜਾਂਦਾ ਹੈ"},{"gurmukhi":"ਅੰਤਰਗਤਿਬੁਝੈਹਾਂ॥","meaning":"ਉਹ ਪਰਮਾਤਮਾ ਹਰੇਕ ਦੇ ਦਿਲ ਦੀ ਗੱਲ ਜਾਣ ਲੈਂਦਾ ਹ"},{"gurmukhi":"ਸਭੁਕਿਛੁਤਿਸੁਸੁਝੈਹਾਂ॥","meaning":"ਉਸ ਨੂੰ ਹਰੇਕ ਜੀਵ ਦੀ ਹਰੇਕ ਮਨੋ-ਕਾਮਨਾ ਦੀ ਸਮਝ ਆ ਜਾਂਦੀ ਹੈ"},{"gurmukhi":"ਪਤਿਤਉਧਾਰਿਲੇਹੁਹਾਂ॥","meaning":"(ਇਸ ਵਾਸਤੇ) ਹੇ ਮੇਰੇ ਮਨ! ਪਰਮਾਤਮਾ ਦੇ ਦਰ ਤੇ ਇਉਂ ਅਰਜ਼ੋਈ ਕਰ"},{"gurmukhi":"ਨਾਨਕਅਰਦਾਸਿਏਹੁਮੇਰੇਮਨਾ॥੩॥੬॥੧੬੨॥","meaning":"ਹੇ ਪ੍ਰਭੂ! (ਸਾਨੂੰ ਵਿਕਾਰਾਂ ਵਿਚ) ਡਿੱਗੇ ਜੀਵਾਂ ਨੂੰ (ਵਿਕਾਰਾਂ ਤੋਂ) ਬਚਾ ਲੈ, (ਤੇਰੇ ਦਰ ਤੇ ਮੇਰੀ) ਨਾਨਕ ਦੀ ਇਹੀ ਅਰਦਾਸਿ ਹੈ ।੩।੬।੧੬੨।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (52, 'ਟੋਡੀਮਹਲਾ੫॥', '[{"gurmukhi":"ਕ੍ਰਿਪਾਨਿਧਿਬਸਹੁਰਿਦੈਹਰਿਨੀਤ॥","meaning":"ਹੇ ਕਿਰਪਾ ਦੇ ਖ਼ਜ਼ਾਨੇ ਪ੍ਰਭੂ! ਮੇਰੇ ਹਿਰਦੇ ਵਿਚ ਵੱਸਦਾ ਰਹੁ ।"},{"gurmukhi":"ਤੈਸੀਬੁਧਿਕਰਹੁਪਰਗਾਸਾਲਾਗੈਪ੍ਰਭਸੰਗਿਪ੍ਰੀਤਿ॥ਰਹਾਉ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੇਰੇ ਅੰਦਰ ਇਹੋ ਜਿਹੀ ਅਕਲ ਦਾ ਚਾਨਣ ਕਰ, ਕਿ ਤੇਰੇ ਨਾਲ ਮੇਰੀ ਪ੍ਰੀਤਿ ਬਣੀ ਰਹੇ ।ਰਹਾਉ।"},{"gurmukhi":"ਦਾਸਤੁਮਾਰੇਕੀਪਾਵਉਧੂਰਾਮਸਤਕਿਲੇਲੇਲਾਵਉ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੈਂ ਤੇਰੇ ਸੇਵਕ ਦੀ ਚਰਨ-ਧੂੜ ਪ੍ਰਾਪਤ ਕਰਾਂ, (ਉਹ ਚਰਨ-ਧੂੜ) ਲੈ ਲੈ ਕੇ ਮੈਂ (ਆਪਣੇ) ਮੱਥੇ ਉੱਤੇ ਲਾਂਦਾ ਰਹਾਂ ।"},{"gurmukhi":"ਮਹਾਪਤਿਤਤੇਹੋਤਪੁਨੀਤਾਹਰਿਕੀਰਤਨਗੁਨਗਾਵਉ॥੧॥","meaning":"( ਹੇ ਪ੍ਰਭੂ! ਮੇਹਰ ਕਰ) ਮੈਂ ਤੇਰੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰਦਾ ਰਹਾਂ, ਮੈਂ ਤੇਰੇ ਗੁਣ ਗਾਂਦਾ ਰਹਾਂ । (ਜਿਸ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਵੱਡੇ ਵੱਡੇ ਵਿਕਾਰੀਆਂ ਤੋਂ ਭੀ ਪਵਿਤ੍ਰ ਹੋ ਜਾਂਦੇ ਹਨ ।੧।"},{"gurmukhi":"ਆਗਿਆਤੁਮਰੀਮੀਠੀਲਾਗਉਕੀਓਤੁਹਾਰੋਭਾਵਉ॥","meaning":"(ਹੇ ਪ੍ਰਭੂ! ਮੇਹਰ ਕਰ) ਮੈਨੂੰ ਤੇਰੀ ਰਜ਼ਾ ਮਿੱਠੀ ਲੱਗਦੀ ਰਹੇ, ਮੈਨੂੰ ਤੇਰਾ ਕੀਤਾ ਚੰਗਾ ਲੱਗਦਾ ਰਹੇ ।"},{"gurmukhi":"ਜੋਤੂਦੇਹਿਤਹੀਇਹੁਤ੍ਰਿਪਤੈਆਨਨਕਤਹੂਧਾਵਉ॥੨॥","meaning":"ਜੋ ਕੁਝ ਤੂੰ ਮੈਨੂੰ ਦੇਂਦਾ ਹੈਂ, ਉਸੇ ਵਿਚ ਹੀ (ਮੇਰਾ) ਇਹ ਮਨ ਸੰਤੁਸ਼ਟ ਰਹੇ, ਮੈਂ ਕਿਸੇ ਭੀ ਹੋਰ ਪਾਸੇ ਭਟਕਦਾ ਨਾਹ ਫਿਰਾਂ ।੨।"},{"gurmukhi":"ਸਦਹੀਨਿਕਟਿਜਾਨਉਪ੍ਰਭਸੁਆਮੀਸਗਲਰੇਣਹੋਇਰਹੀਐ॥","meaning":"ਹੇ ਮੇਰੇ ਮਾਲਕ-ਪ੍ਰਭੂ! ਮੈਂ ਤੈਨੂੰ ਸਦਾ ਆਪਣੇ ਨੇੜੇ (ਵੱਸਦਾ) ਜਾਣਦਾ ਰਹਾਂ । ਹੇ ਭਾਈ! ਸਭਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਬਣ ਕੇ ਰਹਿਣਾ ਚਾਹੀਦਾ ਹੈ ।"},{"gurmukhi":"ਸਾਧੂਸੰਗਤਿਹੋਇਪਰਾਪਤਿਤਾਪ੍ਰਭੁਅਪੁਨਾਲਹੀਐ॥੩॥","meaning":"ਜਦੋਂ ਗੁਰੂ ਦੀ ਸੰਗਤਿ ਹਾਸਲ ਹੁੰਦੀ ਹੈ, ਤਦੋਂ ਆਪਣੇ ਪ੍ਰਭੂ ਨੂੰ ਲੱਭ ਲਈਦਾ ਹੈ ।੩।"},{"gurmukhi":"ਸਦਾਸਦਾਹਮਛੋਹਰੇਤੁਮਰੇਤੂਪ੍ਰਭਹਮਰੋਮੀਰਾ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਅਸੀ ਜੀਵ ਸਦਾ ਹੀ ਤੇਰੇ ਅੰਞਾਣ ਬੱਚੇ ਹਾਂ,ਤੂੰ ਸਾਡੀ ਮਾਂ ਹੈ ਸਾਡਾ ਪਿਉ ਹੈਂ (ਮੇਹਰ ਕਰ) ਤੇਰਾ ਨਾਮ ਸਾਡੇ ਮੂੰਹ ਵਿਚ ਰਹੇ (ਜਿਵੇਂ) ਮਾਪੇ ਆਪਣੇ ਬੱਚੇ ਦੇ ਮੂੰਹ ਵਿਚ ਦੁੱਧ (ਪਾਂਦੇ ਰਹਿੰਦੇ ਹਨ) ।੪।੩।੫।"},{"gurmukhi":"ਨਾਨਕਬਾਰਿਕਤੁਮਮਾਤਪਿਤਾਮੁਖਿਨਾਮੁਤੁਮਾਰੋਖੀਰਾ॥੪॥੩॥੫॥","meaning":""}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (53, 'ਬਿਲਾਵਲੁਮਹਲਾ੫॥', '[{"gurmukhi":"ਪਿੰਗੁਲਪਰਬਤਪਾਰਿਪਰੇਖਲਚਤੁਰਬਕੀਤਾ॥","meaning":"ਹੇ ਮਿੱਤਰ! ਗੁਰੂ ਨੂੰ ਮਿਲ ਕੇ (ਮਨੁੱਖ) ਪਵਿੱਤਰ ਜੀਵਨ ਵਾਲੇ ਹੋ ਜਾਂਦੇ ਹਨ, (ਮਾਨੋ,) ਲੂਲ੍ਹੇ ਮਨੁੱਖ ਪਹਾੜਾਂ ਤੋਂ ਪਾਰ ਲੰਘ ਜਾਂਦੇ ਹਨ, ਮਹਾ ਮੂਰਖ ਮਨੁੱਖ ਸਿਆਣੇ ਵਖਿਆਨ-ਕਰਤਾ ਬਣ ਜਾਂਦੇ ਹਨ,"},{"gurmukhi":"ਅੰਧੁਲੇਤ੍ਰਿਭਵਣਸੂਝਿਆਗੁਰਭੇਟਿਪੁਨੀਤਾ॥੧॥","meaning":"ਅੰਨ੍ਹੇ ਨੂੰ ਤਿੰਨਾ ਭਵਨਾਂ ਦੀ ਸੋਝੀ ਪੈ ਜਾਂਦੀ ਹੈ ।੧।"},{"gurmukhi":"ਮਹਿਮਾਸਾਧੂਸੰਗਕੀਸੁਨਹੁਮੇਰੇਮੀਤਾ॥","meaning":"ਹੇ ਮੇਰੇ ਮਿੱਤਰ! ਗੁਰੂ ਦੀ ਸੰਗਤਿ ਦੀ ਵਡਿਆਈ (ਧਿਆਨ ਨਾਲ) ਸੁਣ ।"},{"gurmukhi":"ਮੈਲੁਖੋਈਕੋਟਿਅਘਹਰੇਨਿਰਮਲਭਏਚੀਤਾ॥੧॥ਰਹਾਉ॥","meaning":"ਮਨ ਪਵਿੱਤਰ ਹੋ ਜਾਂਦਾ ਹੈ, (ਉਸ ਦੇ ਅੰਦਰੋਂ ਵਿਕਾਰਾਂ ਦੀ) ਮੈਲ ਦੂਰ ਹੋ ਜਾਂਦੀ ਹੈ, ਉਸ ਦੇ ਕੋ੍ਰੜਾਂ ਪਾਪ ਨਾਸ ਹੋ ਜਾਂਦੇ ਹਨ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਐਸੀਭਗਤਿਗੋਵਿੰਦਕੀਕੀਟਿਹਸਤੀਜੀਤਾ॥","meaning":"ਪਰਮਾਤਮਾ ਦੀ ਭਗਤੀ ਅਚਰਜ (ਤਾਕਤ ਰੱਖਦੀ ਹੈ, ਇਸ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਕੀੜੀ (ਨਿਮ੍ਰਤਾ) ਨੇ ਹਾਥੀ (ਅਹੰਕਾਰ) ਨੂੰ ਜਿੱਤ ਲਿਆ ਹੈ ।"},{"gurmukhi":"ਜੋਜੋਕੀਨੋਆਪਨੋਤਿਸੁਅਭੈਦਾਨੁਦੀਤਾ॥੨॥","meaning":"ਜਿਸ ਜਿਸ ਮਨੁੱਖ ਨੂੰ (ਪਰਮਾਤਮਾ ਨੇ) ਆਪਣਾ ਬਣਾ ਲਿਆ, ਉਸ ਨੂੰ ਪਰਮਾਤਮਾ ਨੇ ਨਿਰਭੈਤਾ ਦੀ ਦਾਤਿ ਦੇ ਦਿੱਤੀ ।੨।"},{"gurmukhi":"ਸਿੰਘੁਬਿਲਾਈਹੋਇਗਇਓਤ੍ਰਿਣੁਮੇਰੁਦਿਖੀਤਾ॥","meaning":"ਬਿੱਲੀ (ਨਿਮ੍ਰਤਾ) ਬਣ ਜਾਂਦਾ ਹੈ, ਤੀਲਾ (ਗ਼ਰੀਬੀ ਸੁਭਾਉ) ਸੁਮੇਰ ਪਰਬਤ (ਬੜੀ ਵੱਡੀ ਤਾਕਤ) ਦਿੱਸਣ ਲੱਗ ਪੈਂਦਾ ਹੈ ।"},{"gurmukhi":"ਸ੍ਰਮੁਕਰਤੇਦਮਆਢਕਉਤੇਗਨੀਧਨੀਤਾ॥੩॥","meaning":"ਅੱਧੀ ਅੱਧੀ ਕੌਡੀ ਵਾਸਤੇ ਧੱਕੇ ਖਾਂਦੇ ਫਿਰਦੇ ਸਨ, ਉਹ ਦੌਲਤ-ਮੰਦ ਧਨਾਢ ਬਣ ਜਾਂਦੇ ਹਨ (ਮਾਇਆ ਵਲੋਂ ਬੇ-ਮੁਥਾਜ ਹੋ ਜਾਂਦੇ ਹਨ) ।੩।"},{"gurmukhi":"ਕਵਨਵਡਾਈਕਹਿਸਕਉਬੇਅੰਤਗੁਨੀਤਾ॥","meaning":"ਮੈਂ ਕੇਹੜੀ ਕੇਹੜੀ ਵਡਿਆਈ ਦੱਸਾਂ? ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਬੇਅੰਤ ਗੁਣਾਂ ਦਾ ਮਾਲਕ ਹੈ ।"},{"gurmukhi":"ਕਰਿਕਿਰਪਾਮੋਹਿਨਾਮੁਦੇਹੁਨਾਨਕਦਰਸਰੀਤਾ॥੪॥੭॥੩੭॥","meaning":"ਹੇ ਨਾਨਕ! ਅਰਦਾਸ ਕਰ, ਤੇ, ਆਖ—ਹੇ ਪ੍ਰਭੂ!) ਮੈਂ ਤੇਰੇ ਦਰ ਦਾ ਗ਼ੁਲਾਮ ਹਾਂ, ਮੇਹਰ ਕਰ ਤੇ, ਮੈਨੂੰ ਆਪਣਾ ਨਾਮ ਬਖ਼ਸ਼ ।੪।੭।੩੭।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (54, 'ਮਾਰੂਮਹਲਾ੫॥', '[{"gurmukhi":"ਆਉਜੀਤੂਆਉਹਮਾਰੈਹਰਿਜਸੁਸ੍ਰਵਨਸੁਨਾਵਨਾ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਪਿਆਰੇ ਗੁਰੂ! ਆ । ਮੇਰੇ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਆ ਵੱਸ, ਤੇ, ਮੇਰੇ ਕੰਨਾਂ ਵਿਚ ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਸੁਣਾ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਤੁਧੁਆਵਤਮੇਰਾਮਨੁਤਨੁਹਰਿਆਹਰਿਜਸੁਤੁਮਸੰਗਿਗਾਵਨਾ॥੧॥","meaning":"ਹੇ ਪਿਆਰੇ ਗੁਰੂ! ਤੇਰੇ ਆਇਆਂ ਮੇਰਾ ਮਨ ਮੇਰਾ ਤਨ ਆਤਮਕ ਜੀਵਨ ਵਾਲਾ ਹੋ ਜਾਂਦਾ ਹੈ । ਹੇ ਸਤਿਗੁਰੂ! ਤੇਰੇ ਚਰਨਾਂ ਵਿਚ ਰਹਿ ਕੇ ਹੀ ਪਰਮਾਤਮਾ ਦਾ ਜਸ ਗਾਇਆ ਜਾ ਸਕਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਸੰਤਕ੍ਰਿਪਾਤੇਹਿਰਦੈਵਾਸੈਦੂਜਾਭਾਉਮਿਟਾਵਨਾ॥੨॥","meaning":"ਹੇ ਭਾਈ! ਗੁਰੂ ਦੀ ਮਿਹਰ ਨਾਲ ਪਰਮਾਤਮਾ ਹਿਰਦੇ ਵਿਚ ਆ ਵੱਸਦਾ ਹੈ, ਤੇ ਮਾਇਆ ਦਾ ਮੋਹ ਦੂਰ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ ।੨।"},{"gurmukhi":"ਭਗਤਦਇਆਤੇਬੁਧਿਪਰਗਾਸੈਦੁਰਮਤਿਦੂਖਤਜਾਵਨਾ॥੩॥","meaning":"ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ ਦੇ ਭਗਤ ਦੀ ਕਿਰਪਾ ਨਾਲ ਬੁੱਧੀ ਵਿਚ ਆਤਮਕ ਜੀਵਨ ਦਾ ਚਾਨਣ ਹੋ ਜਾਂਦਾ ਹੈ, ਖੋਟੀ ਮਤਿ ਦੇ ਸਾਰੇ ਵਿਕਾਰ ਤਿਆਗੇ ਜਾਂਦੇ ਹਨ ।੩।"},{"gurmukhi":"ਦਰਸਨੁਭੇਟਤਹੋਤਪੁਨੀਤਾਪੁਨਰਪਿਗਰਭਿਨਪਾਵਨਾ॥੪॥","meaning":"ਹੇ ਭਾਈ! ਗੁਰੂ ਦਾ ਦਰਸਨ ਕਰਦਿਆਂ ਜੀਵਨ ਪਵਿੱਤਰ ਹੋ ਜਾਂਦਾ ਹੈ, ਮੁੜ ਮੁੜ ਜੂਨਾਂ ਦੇ ਗੇੜ ਵਿਚ ਨਹੀਂ ਪਈਦਾ ।੪।"},{"gurmukhi":"ਨਉਨਿਧਿਰਿਧਿਸਿਧਿਪਾਈਜੋਤੁਮਰੈਮਨਿਭਾਵਨਾ॥੫॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਜਿਹੜਾ (ਵਡਭਾਗੀ) ਮਨੁੱਖ ਤੇਰੇ ਮਨ ਵਿਚ ਪਿਆਰਾ ਲੱਗਣ ਲੱਗ ਪੈਂਦਾ ਹੈ, ਉਹ, (ਮਾਨੋ) ਦੁਨੀਆ ਦੇ ਸਾਰੇ ਹੀ ਨੌ ਖ਼ਜ਼ਾਨੇ ਅਤੇ ਕਰਾਮਾਤੀ ਤਾਕਤਾਂ ਹਾਸਲ ਕਰ ਲੈਂਦਾ ਹੈ ।੫।"},{"gurmukhi":"ਸੰਤਬਿਨਾਮੈਥਾਉਨਕੋਈਅਵਰਨਸੂਝੈਜਾਵਨਾ॥੬॥","meaning":"ਹੇ ਭਾਈ! ਗੁਰੂ ਤੋਂ ਬਿਨਾ ਮੇਰਾ ਹੋਰ ਕੋਈ ਆਸਰਾ ਨਹੀਂ, ਕਿਸੇ ਹੋਰ ਥਾਂ ਜਾਣਾ ਮੈਨੂੰ ਨਹੀਂ ਸੁੱਝਦਾ ।੬।"},{"gurmukhi":"ਮੋਹਿਨਿਰਗੁਨਕਉਕੋਇਨਰਾਖੈਸੰਤਾਸੰਗਿਸਮਾਵਨਾ॥੭॥","meaning":"ਹੇ ਭਾਈ! ਮੇਰੀ ਗੁਣ-ਹੀਨ ਦੀ (ਗੁਰੂ ਤੋਂ ਬਿਨਾ) ਹੋਰ ਕੋਈ ਬਾਂਹ ਨਹੀਂ ਫੜਦਾ । ਸੰਤ ਜਨਾਂ ਦੀ ਸੰਗਤਿ ਵਿਚ ਰਹਿ ਕੇ ਹੀ ਪ੍ਰਭੂ-ਚਰਨਾਂ ਵਿਚ ਲੀਨ ਹੋਈਦਾ ਹੈ ।੭।"},{"gurmukhi":"ਕਹੁਨਾਨਕਗੁਰਿਚਲਤੁਦਿਖਾਇਆਮਨਮਧੇਹਰਿਹਰਿਰਾਵਨਾ॥੮॥੨॥੫॥","meaning":"ਹੇ ਨਾਨਕ! ਆਖ—ਗੁਰੂ ਨੇ (ਮੈਨੂੰ) ਅਚਰਜ ਤਮਾਸ਼ਾ ਵਿਖਾ ਦਿੱਤਾ ਹੈ । ਮੈਂ ਆਪਣੇ ਮਨ ਵਿਚ ਹਰ ਵੇਲੇ ਪਰਮਾਤਮਾ ਦੇ ਮਿਲਾਪ ਦਾ ਆਨੰਦ ਮਾਣ ਰਿਹਾ ਹਾਂ ।੮।੨।੫।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (55, 'ਸੋਰਠਿਮਹਲਾ੫॥', '[{"gurmukhi":"ਹਮਰੀਗਣਤਨਗਣੀਆਕਾਈਅਪਣਾਬਿਰਦੁਪਛਾਣਿ॥","meaning":"ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ ਅਸਾਂ ਜੀਵਾਂ ਦੇ ਕੀਤੇ ਮੰਦ-ਕਰਮਾਂ ਦਾ ਕੋਈ ਖ਼ਿਆਲ ਨਹੀਂ ਕਰਦਾ । ਉਹ ਆਪਣੇ ਮੁੱਢ-ਕਦੀਮਾਂ ਦੇ (ਪਿਆਰ ਵਾਲੇ) ਸੁਭਾਉ ਨੂੰ ਚੇਤੇ ਰੱਖਦਾ ਹੈ,"},{"gurmukhi":"ਹਾਥਦੇਇਰਾਖੇਕਰਿਅਪੁਨੇਸਦਾਸਦਾਰੰਗੁਮਾਣਿ॥੧॥","meaning":"(ਉਹ, ਸਗੋਂ, ਸਾਨੂੰ ਗੁਰੂ ਮਿਲਾ ਕੇ, ਸਾਨੂੰ) ਆਪਣੇ ਬਣਾ ਕੇ (ਆਪਣੇ) ਹੱਥ ਦੇ ਕੇ (ਸਾਨੂੰ ਵਿਕਾਰਾਂ ਵਲੋਂ) ਬਚਾਂਦਾ ਹੈ । (ਜਿਸ ਵਡ-ਭਾਗੀ ਨੂੰ ਗੁਰੂ ਮਿਲ ਪੈਂਦਾ ਹੈ, ਉਹ) ਸਦਾ ਹੀ ਆਤਮਕ ਆਨੰਦ ਮਾਣਦਾ ਹੈ ।੧।"},{"gurmukhi":"ਸਾਚਾਸਾਹਿਬੁਸਦਮਿਹਰਵਾਣ॥","meaning":"ਹੇ ਭਾਈ! ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਮਾਲਕ-ਪ੍ਰਭੂ ਸਦਾ ਦਇਆਵਾਨ ਰਹਿੰਦਾ ਹੈ,"},{"gurmukhi":"ਬੰਧੁਪਾਇਆਮੇਰੈਸਤਿਗੁਰਿਪੂਰੈਹੋਈਸਰਬਕਲਿਆਣ॥ਰਹਾਉ॥","meaning":"(ਕੁਕਰਮਾਂ ਵਲ ਪਰਤ ਰਹੇ ਬੰਦਿਆਂ ਨੂੰ ਉਹ ਗੁਰੂ ਮਿਲਾਂਦਾ ਹੈ । ਜਿਸ ਨੂੰ ਪੂਰਾ ਗੁਰੂ ਮਿਲ ਪਿਆ, ਉਸ ਦੇ ਵਿਕਾਰਾਂ ਦੇ ਰਸਤੇ ਵਿਚ) ਮੇਰੇ ਪੂਰੇ ਗੁਰੂ ਨੇ ਬੰਨ੍ਹ ਮਾਰ ਦਿੱਤਾ (ਤੇ, ਇਸ ਤਰ੍ਹਾਂ ਉਸ ਦੇ ਅੰਦਰ) ਸਾਰੇ ਆਤਮਕ ਆਨੰਦ ਪੈਦਾ ਹੋ ਗਏ ।ਰਹਾਉ।"},{"gurmukhi":"ਜੀਉਪਾਇਪਿੰਡੁਜਿਨਿਸਾਜਿਆਦਿਤਾਪੈਨਣੁਖਾਣੁ॥","meaning":"ਹੇ ਭਾਈ! ਜਿਸ ਪਰਮਾਤਮਾ ਨੇ ਜਿੰਦ ਪਾ ਕੇ (ਸਾਡਾ) ਸਰੀਰ ਪੈਦਾ ਕੀਤਾ ਹੈ, ਜੇਹੜਾ (ਹਰ ਵੇਲੇ) ਸਾਨੂੰ ਖ਼ੁਰਾਕ ਤੇ ਪੁਸ਼ਾਕ ਦੇ ਰਿਹਾ ਹੈ,"},{"gurmukhi":"ਅਪਣੇਦਾਸਕੀਆਪਿਪੈਜਰਾਖੀਨਾਨਕਸਦਕੁਰਬਾਣੁ॥੨॥੧੬॥੪੪॥","meaning":"ਉਹ ਪਰਮਾਤਮਾ (ਸੰਸਾਰ-ਸਮੁੰਦਰ ਦੀਆਂ ਵਿਕਾਰ-ਲਹਿਰਾਂ ਤੋਂ) ਆਪਣੇ ਸੇਵਕ ਦੀ ਇੱਜ਼ਤ (ਗੁਰੂ ਮਿਲਾ ਕੇ) ਆਪ ਬਚਾਂਦਾ ਹੈ । ਹੇ ਨਾਨਕ! (ਆਖ—ਮੈਂ ਉਸ ਪਰਮਾਤਮਾ ਤੋਂ) ਸਦਾ ਸਦਕੇ ਜਾਂਦਾ ਹਾਂ ।੨।੧੬।੪੪।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (56, 'ਗਉੜੀਮਹਲਾ੫॥', '[{"gurmukhi":"ਪ੍ਰਭਮਿਲਬੇਕਉਪ੍ਰੀਤਿਮਨਿਲਾਗੀ॥","meaning":"(ਹੇ ਭੈਣ!) ਪਰਮਾਤਮਾ ਨੂੰ ਮਿਲਣ ਵਾਸਤੇ ਮੇਰੇ ਮਨ ਵਿਚ ਪ੍ਰੀਤਿ ਪੈਦਾ ਹੋ ਗਈ ਹੈ ।"},{"gurmukhi":"ਪਾਇਲਗਉਮੋਹਿਕਰਉਬੇਨਤੀਕੋਊਸੰਤੁਮਿਲੈਬਡਭਾਗੀ॥੧॥ਰਹਾਉ॥","meaning":"(ਪਰਮਾਤਮਾ ਨਾਲ ਮਿਲਾ ਸਕਣ ਵਾਲਾ ਜੇ) ਵੱਡੇ ਭਾਗਾਂ ਵਾਲਾ (ਗੁਰੂ-) ਸੰਤ ਮੈਨੂੰ ਮਿਲ ਪਏ, ਤਾਂ ਮੈਂ ਉਸ ਦੇ ਪੈਰੀਂ ਲੱਗਾਂ, ਮੈਂ ਉਸ ਅਗੇ ਬੇਨਤੀ ਕਰਾਂ (ਕਿ ਮੈਨੂੰ ਪਰਮਾਤਮਾ ਨਾਲ ਮਿਲਾ ਦੇ) ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਮਨੁਅਰਪਉਧਨੁਰਾਖਉਆਗੈਮਨਕੀਮਤਿਮੋਹਿਸਗਲਤਿਆਗੀ॥","meaning":"ਮੈਂ ਆਪਣਾ ਮਨ ਉਸ ਦੇ ਹਵਾਲੇ ਕਰ ਦਿਆਂ, ਮੈਂ ਆਪਣਾ ਧਨ ਉਸ ਦੇ ਅੱਗੇ ਰੱਖ ਦਿਆਂ । (ਹੇ ਭੈਣ!) ਮੈਂ ਆਪਣੇ ਮਨ ਦੀ ਸਾਰੀ ਚਤੁਰਾਈ ਛੱਡ ਦਿੱਤੀ ਹੈ ।"},{"gurmukhi":"ਜੋਪ੍ਰਭਕੀਹਰਿਕਥਾਸੁਨਾਵੈਅਨਦਿਨੁਫਿਰਉਤਿਸੁਪਿਛੈਵਿਰਾਗੀ॥੧॥","meaning":"(ਹੇ ਭੈਣ!) ਜੇਹੜਾ (ਵਡਭਾਗੀ ਸੰਤ ਮੈਨੂੰ) ਪਰਮਾਤਮਾ ਦੀਆਂ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੀਆਂ ਗੱਲਾਂ ਸੁਣਾਂਦਾ ਰਹੇ, ਮੈਂ ਹਰ ਵੇਲੇ ਉਸ ਦੇ ਪਿੱਛੇ ਪਿੱਛੇ ਪ੍ਰੇਮ ਵਿਚ ਕਮਲੀ ਹੋਈ ਫਿਰਦੀ ਰਹਾਂ"},{"gurmukhi":"ਪੂਰਬਕਰਮਅੰਕੁਰਜਬਪ੍ਰਗਟੇਭੇਟਿਓਪੁਰਖੁਰਸਿਕਬੈਰਾਗੀ॥","meaning":"ਹੇ ਨਾਨਕ! (ਆਖ—) ਪਹਿਲੇ ਜਨਮਾਂ ਵਿਚ ਕੀਤੇ ਭਲੇ ਕਰਮਾਂ ਦੇ ਸੰਸਕਾਰਾਂ ਦੇ ਅੰਗੂਰ ਜਿਸ ਜੀਵ-ਇਸਤ੍ਰੀ ਦੇ ਉੱਘੜ ਪਏ, ਉਸ ਨੂੰ ਉਹ ਸਰਬ-ਵਿਆਪਕ ਪ੍ਰਭੂ ਮਿਲ ਪਿਆ ਹੈ ਜੋ ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ ਬੈਠਾ ਸਭ ਰਸ ਮਾਣਨ ਵਾਲਾ ਹੈ ਤੇ ਜੋ ਰਸਾਂ ਤੋਂ ਨਿਰਲੇਪ ਭੀ ਹੈ ।"},{"gurmukhi":"ਮਿਟਿਓਅੰਧੇਰੁਮਿਲਤਹਰਿਨਾਨਕਜਨਮਜਨਮਕੀਸੋਈਜਾਗੀ॥੨॥੨॥੧੧੯॥","meaning":"ਪਰਮਾਤਮਾ ਨੂੰ ਮਿਲਦਿਆਂ ਹੀ ਉਸ ਜੀਵ-ਇਸਤ੍ਰੀ ਦੇ ਅੰਦਰੋਂ ਮਾਇਆ ਦੇ ਮੋਹ ਦਾ ਹਨੇਰਾ ਦੂਰ ਹੋ ਜਾਂਦਾ ਹੈ, ਉਹ ਅਨੇਕਾਂ ਜਨਮਾਂ ਤੋਂ ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਸੁੱਤੀ ਹੋਈ ਜਾਗ ਪੈਂਦੀ ਹੈ ।੨।੨।੧੧੯।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (57, 'ਬਾਰਹਮਾਹਾਮਾਂਝਮਹਲਾ੫ਘਰੁ੪', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਕਿਰਤਿਕਰਮਕੇਵੀਛੁੜੇਕਰਿਕਿਰਪਾਮੇਲਹੁਰਾਮ॥","meaning":"ਹੇ ਪ੍ਰਭੂ ! ਅਸੀ ਆਪਣੇ ਕਰਮਾਂ ਦੀ ਕਮਾਈ ਅਨੁਸਾਰ (ਤੈਥੋਂ) ਵਿੱਛੁੜੇ ਹੋਏ ਹਾਂ (ਤੈਨੂੰ ਵਿਸਾਰੀ ਬੈਠੇ ਹਾਂ), ਮਿਹਰ ਕਰ ਕੇ ਸਾਨੂੰ ਆਪਣੇ ਨਾਲ ਮਿਲਾਵੋ ।"},{"gurmukhi":"ਚਾਰਿਕੁੰਟਦਹਦਿਸਭ੍ਰਮੇਥਕਿਆਏਪ੍ਰਭਕੀਸਾਮ॥","meaning":"(ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਫਸ ਕੇ) ਚੁਫੇਰੇ ਹਰ ਪਾਸੇ (ਸੁਖਾਂ ਦੀ ਖ਼ਾਤਰ) ਭਟਕਦੇ ਰਹੇ ਹਾਂ, ਹੁਣ, ਹੇ ਪ੍ਰਭੂ ! ਥੱਕ ਕੇ ਤੇਰੀ ਸਰਨ ਆਏ ਹਾਂ ।"},{"gurmukhi":"ਧੇਨੁਦੁਧੈਤੇਬਾਹਰੀਕਿਤੈਨਆਵੈਕਾਮ॥","meaning":"(ਜਿਵੇਂ) ਦੁੱਧ ਤੋਂ ਸੱਖਣੀ ਗਾਂ ਕਿਸੇ ਕੰਮ ਨਹੀਂ ਆਉਂਦੀ,"},{"gurmukhi":"ਜਲਬਿਨੁਸਾਖਕੁਮਲਾਵਤੀਉਪਜਹਿਨਾਹੀਦਾਮ॥","meaning":"(ਜਿਵੇਂ) ਪਾਣੀ ਤੋਂ ਬਿਨਾ ਖੇਤੀ ਸੁੱਕ ਜਾਂਦੀ ਹੈ (ਫ਼ਸਲ ਨਹੀਂ ਪੱਕਦੀ, ਤੇ ਉਸ ਖੇਤੀ ਵਿਚੋਂ) ਧਨ ਦੀ ਕਮਾਈ ਨਹੀਂ ਹੋ ਸਕਦੀ (ਤਿਵੇਂ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਤੋਂ ਬਿਨਾ ਸਾਡਾ ਜੀਵਨ ਵਿਅਰਥ ਚਲਾ ਜਾਂਦਾ ਹੈ) ।"},{"gurmukhi":"ਹਰਿਨਾਹਨਮਿਲੀਐਸਾਜਨੈਕਤਪਾਈਐਬਿਸਰਾਮ॥","meaning":"ਸੱਜਣ ਖਸਮ-ਪ੍ਰਭੂ ਨੂੰ ਮਿਲਣ ਤੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਥਾਂ ਸੁਖ ਭੀ ਨਹੀਂ ਮਿਲਦਾ ।"},{"gurmukhi":"ਜਿਤੁਘਰਿਹਰਿਕੰਤੁਨਪ੍ਰਗਟਈਭਠਿਨਗਰਸੇਗ੍ਰਾਮ॥","meaning":"(ਸੁਖ ਮਿਲੇ ਭੀ ਕਿਵੇਂ ?) ਜਿਸ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਪਤੀ ਪ੍ਰਭੂ ਆ ਵੱਸੇ, ਉਸ ਦੇ ਭਾ ਦੇ (ਵੱਸਦੇ) ਪਿੰਡ ਤੇ ਸ਼ਹਰ ਤੱਪਦੀ ਭੱਠੀ ਵਰਗੇ ਹੁੰਦੇ ਹਨ ।"},{"gurmukhi":"ਸ੍ਰਬਸੀਗਾਰਤੰਬੋਲਰਸਸਣੁਦੇਹੀਸਭਖਾਮ॥","meaning":"(ਇਸਤ੍ਰੀ ਨੂੰ ਪਤੀ ਤੋਂ ਬਿਨਾ) ਸਰੀਰ ਦੇ ਸਾਰੇ ਸ਼ਿੰਗਾਰ ਪਾਨਾਂ ਦੇ ਬੀੜੇ ਤੇ ਹੋਰ ਰਸ (ਆਪਣੇ) ਸਰੀਰ ਸਮੇਤ ਹੀ ਵਿਅਰਥ ਦਿੱਸਦੇ ਹਨ,"},{"gurmukhi":"ਪ੍ਰਭਸੁਆਮੀਕੰਤਵਿਹੂਣੀਆਮੀਤਸਜਣਸਭਿਜਾਮ॥","meaning":"(ਤਿਵੇਂ) ਮਾਲਕ ਖਸਮ-ਪ੍ਰਭੂ (ਦੀ ਯਾਦ) ਤੋਂ ਬਿਨਾ ਸਾਰੇ ਸੱਜਣ ਮਿਤ੍ਰ ਜਿੰਦ ਦੇ ਵੈਰੀ ਹੋ ਢੁਕਦੇ ਹਨ ।"},{"gurmukhi":"ਨਾਨਕਕੀਬੇਨੰਤੀਆਕਰਿਕਿਰਪਾਦੀਜੈਨਾਮੁ॥","meaning":"(ਤਾਹੀਏਂ) ਨਾਨਕ ਦੀ ਬੇਨਤੀ ਹੈ ਕਿ (ਹੇ ਪ੍ਰਭੂ !) ਕਿਰਪਾ ਕਰ ਕੇ ਆਪਣੇ ਨਾਮ ਦੀ ਦਾਤਿ ਬਖ਼ਸ਼ ।"},{"gurmukhi":"ਹਰਿਮੇਲਹੁਸੁਆਮੀਸੰਗਿਪ੍ਰਭਜਿਸਕਾਨਿਹਚਲਧਾਮ॥੧॥","meaning":"ਹੇ ਹਰੀ ! ਆਪਣੇ ਚਰਨਾਂ ਵਿਚ (ਮੈਨੂੰ) ਜੋੜੀ ਰੱਖ, (ਹੋਰ ਸਾਰੇ ਆਸਰੇ-ਪਰਨੇ ਨਾਸਵੰਤ ਹਨ) ਇਕ ਤੇਰਾ ਘਰ ਸਦਾ ਅਟੱਲ ਰਹਿਣ ਵਾਲਾ ਹੈ ।੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (58, 'ਪਉੜੀ੨੭:ਗੁਰੂਨਾਨਕਸੂਰਯੋਦਯ', '[{"gurmukhi":"ਸਤਿਗੁਰੁਨਾਨਕੁਪ੍ਰਗਟਿਆਮਿਟੀਧੁੰਧੁਜਗਿਚਾਨਣੁਹੋਆ।","meaning":""},{"gurmukhi":"ਜਿਉਕਰਿਸੂਰਜੁਨਿਕਲਿਆਤਾਰੇਛਪਿਅੰਧੇਰੁਪਲੋਆ।","meaning":""},{"gurmukhi":"ਸਿੰਘੁਬੁਕੇਮਿਰਗਾਵਲੀਭੰਨੀਜਾਇਨਧੀਰਿਧਰੋਆ।","meaning":""},{"gurmukhi":"ਜਿਥੇਬਾਬਾਪੈਰੁਧਰਿਪੂਜਾਆਸਣੁਥਾਪਣਿਸੋਆ।","meaning":""},{"gurmukhi":"ਸਿਧਾਸਣਿਸਭਿਜਗਤਿਦੇਨਾਨਕਆਦਿਮਤੇਜੇਕੋਆ।","meaning":""},{"gurmukhi":"ਘਰਿਘਰਿਅੰਦਰਿਧਰਮਸਾਲਹੋਵੈਕੀਰਤਨੁਸਦਾਵਿਸੋਆ।","meaning":""},{"gurmukhi":"ਬਾਬੇਤਾਰੇਚਾਰਿਚਕਿਨਉਖੰਡਿਪ੍ਰਿਥਮੀਸਚਾਢੋਆ।","meaning":""},{"gurmukhi":"ਗੁਰਮੁਖਿਕਲਿਵਿਚਿਪਰਗਟੁਹੋਆ॥੨੭॥","meaning":""}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (59, 'ਮਲਾਰਮਹਲਾ੪ਪੜਤਾਲਘਰੁ੩', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਹਰਿਜਨਬੋਲਤਸ੍ਰੀਰਾਮਨਾਮਾਮਿਲਿਸਾਧਸੰਗਤਿਹਰਿਤੋਰ॥੧॥ਰਹਾਉ॥","meaning":"ਹੇ ਹਰੀ! ਤੇਰੇ ਭਗਤ ਤੇਰੀ ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਮਿਲ ਕੇ ਤੇਰਾ ਨਾਮ ਜਪਦੇ ਹਨ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਹਰਿਧਨੁਬਨਜਹੁਹਰਿਧਨੁਸੰਚਹੁਜਿਸੁਲਾਗਤਹੈਨਹੀਚੋਰ॥੧॥","meaning":"ਹੇ ਭਾਈ! (ਤੁਸੀਂ ਭੀ ਸਾਧ ਸੰਗਤਿ ਵਿਚ) ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ-ਧਨ ਵਣਜੋ, ਪ੍ਰਭੂ ਦਾ ਨਾਮ-ਧਨ ਇਕੱਠਾ ਕਰੋ, (ਇਹ ਧਨ ਐਸਾ ਹੈ) ਕਿ ਇਸ ਨੂੰ ਚੋਰ ਚੁਰਾ ਨਹੀਂ ਸਕਦੇ ।੧।"},{"gurmukhi":"ਚਾਤ੍ਰਿਕਮੋਰਬੋਲਤਦਿਨੁਰਾਤੀਸੁਨਿਘਨਿਹਰਕੀਘੋਰ॥੨॥","meaning":"ਹੇ ਭਾਈ! (ਜਿਵੇਂ) ਪਪੀਹੇ ਤੇ ਮੋਰ ਬੱਦਲਾਂ ਦੀ ਗੜਗੱਜ ਸੁਣ ਕੇ ਦਿਨ ਰਾਤ ਬੋਲਦੇ ਹਨ, (ਤਿਵੇਂ ਤੁਸੀ ਭੀ ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਮਿਲ ਕੇ ਹਰੀ ਦਾ ਨਾਮ ਜਪਿਆ ਕਰੋ) ।੨"},{"gurmukhi":"ਜੋਬੋਲਤਹੈਮ੍ਰਿਗਮੀਨਪੰਖੇਰੂਸੁਬਿਨੁਹਰਿਜਾਪਤਹੈਨਹੀਹੋਰ॥੩॥","meaning":"ਹੇ ਭਾਈ! (ਉਹ ਪਰਮਾਤਮਾ ਐਸਾ ਹੈ ਕਿ) ਪਸ਼ੂ ਪੰਛੀ ਮੱਛੀਆਂ ਆਦਿਕ (ਧਰਤੀ ਉਤੇ ਤੁਰਨ ਫਿਰਨ ਵਾਲੇ, ਪਾਣੀ ਵਿਚ ਰਹਿਣ ਵਾਲੇ, ਆਕਾਸ਼ ਵਿਚ ਉੱਡਣ ਵਾਲੇ ਸਾਰੇ ਹੀ) ਜੋ ਬੋਲਦੇ ਹਨ, ਪਰਮਾਤਮਾ (ਦੀ ਦਿੱਤੀ ਸੱਤਿਆ) ਤੋਂ ਬਿਨਾ (ਕਿਸੇ) ਹੋਰ (ਦੀ ਸੱਤਿਆ ਨਾਲ) ਨਹੀਂ ਬੋਲਦੇ ।੩।"},{"gurmukhi":"ਨਾਨਕਜਨਹਰਿਕੀਰਤਿਗਾਈਛੂਟਿਗਇਓਜਮਕਾਸਭਸੋਰ॥੪॥੧॥੮॥","meaning":"ਹੇ ਨਾਨਕ! ਜਿਨ੍ਹਾਂ ਭੀ ਹਰਿ-ਸੇਵਕਾਂ ਨੇ ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦਾ ਗੀਤ ਗਾਣਾ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤਾ, (ਉਹਨਾਂ ਵਾਸਤੇ) ਜਮਦੂਤਾਂ ਦਾ ਸਾਰਾ ਰੌਲਾ ਮੁੱਕ ਗਿਆ (ਉਹਨਾਂ ਨੂੰ ਜਮਦੂਤਾਂ ਦਾ ਕੋਈ ਡਰ ਨਾਹ ਰਹਿ ਗਿਆ) ।੪।੧।੮।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (60, 'ਸਲੋਕਮਃ੨॥', '[{"gurmukhi":"ਸਾਵਣੁਆਇਆਹੇਸਖੀਕੰਤੈਚਿਤਿਕਰੇਹੁ॥","meaning":"ਹੇ ਸਖੀ! ਸਾਵਣ (ਦਾ ਮਹੀਨਾ) ਆਇਆ ਹੈ (ਭਾਵ, ਗੁਰੂ ਵਲੋਂ ਨਾਮ-ਅੰਮ੍ਰਿਤ ਦੀ ਵਰਖਾ ਹੋ ਰਹੀ ਹੈ) ਖਸਮ (-ਪ੍ਰਭੂ) ਨੂੰ ਹਿਰਦੇ ਵਿਚ ਪ੍ਰੋ ਲਉ"},{"gurmukhi":"ਨਾਨਕਝੂਰਿਮਰਹਿਦੋਹਾਗਣੀਜਿਨ੍ਹਅਵਰੀਲਾਗਾਨੇਹੁ॥੧॥","meaning":"ਹੇ ਨਾਨਕ! ਜਿਨ੍ਹਾਂ (ਜੀਵ-ਇਸਤਰੀਆਂ) ਦਾ ਪਿਆਰ (ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਛੱਡ ਕੇ) ਹੋਰਨਾਂ ਨਾਲ ਹੈ ਉਹ ਮੰਦ-ਭਾਗਣਾਂ ਦੁਖੀ ਹੁੰਦੀਆਂ ਹਨ ।੧।"},{"gurmukhi":"ਮਃ੨॥","meaning":""},{"gurmukhi":"ਸਾਵਣੁਆਇਆਹੇਸਖੀਜਲਹਰੁਬਰਸਨਹਾਰੁ॥","meaning":"ਹੇ ਸਖੀ! ਸਾਵਣ (ਭਾਵ ‘ਨਾਮ’ ਦੀ ਵਰਖਾ ਦਾ ਸਮਾ) ਆਇਆ ਹੈ, ਬੱਦਲ ਵਰ੍ਹਾਊ ਹੋ ਗਿਆ ਹੈ (ਭਾਵ, ਗੁਰੂ ਮੇਹਰ ਕਰ ਰਿਹਾ ਹੈ)"},{"gurmukhi":"ਨਾਨਕਸੁਖਿਸਵਨੁਸੋਹਾਗਣੀਜਿਨ੍ਹਸਹਨਾਲਿਪਿਆਰੁ॥੨॥","meaning":"ਹੇ ਨਾਨਕ! (ਇਸ ਸੁਹਾਵਣੇ ਸਮੇ) ਜਿਨ੍ਹਾਂ (ਜੀਵ-ਇਸਤ੍ਰੀਆਂ ਦਾ) ਖਸਮ (-ਪ੍ਰਭੂ) ਨਾਲ ਪਿਆਰ ਬਣਿਆ ਹੈ ਉਹ ਭਾਗਾਂ ਵਾਲੀਆਂ ਪਈਆਂ ਸੁਖ ਨਾਲ ਸਉਣ (ਭਾਵ, ਸੁਖੀ ਜੀਵਨ ਬਿਤੀਤ ਕਰਨ) ।੨।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (61, 'ਵਾਹਿਗੁਰੂਵਾਹਿਗੁਰੂਵਾਹਿਗੁਰੂਵਾਹਿਜੀਉ॥', '[{"gurmukhi":"","meaning":"ਵਾਹ ਵਾਹ! ਹੇ ਪਿਆਰੇ! ਹੇ ਗੁਰੂ! ਸਦਕੇ!"},{"gurmukhi":"ਕਵਲਨੈਨਮਧੁਰਬੈਨਕੋਟਿਸੈਨਸੰਗਸੋਭਕਹਤਮਾਜਸੋਦਜਿਸਹਿਦਹੀਭਾਤੁਖਾਹਿਜੀਉ॥","meaning":"ਤੇਰੇ ਕਮਲ ਵਰਗੇ ਨੇਤ੍ਰ ਹਨ, (ਮੇਰੇ ਵਾਸਤੇ ਤਾਂ ਤੂੰ ਹੀ ਹੈਂ ਜਿਸ ਨੂੰ) ਮਾਂ ਜਸੋਧਾ ਆਖਦੀ ਸੀ—‘ਹੇ ਲਾਲ (ਆ), ਦਹੀਂ ਚਾਉਲ ਖਾ ।’"},{"gurmukhi":"ਦੇਖਿਰੂਪੁਅਤਿਅਨੂਪੁਮੋਹਮਹਾਮਗਭਈਕਿੰਕਨੀਸਬਦਝਨਤਕਾਰਖੇਲੁਪਾਹਿਜੀਉ॥","meaning":"ਜਦੋਂ ਤੂੰ ਖੇਡ ਮਚਾਉਂਦਾ ਸੈਂ, ਤੇਰੀ ਤੜਾਗੀ ਦੀ ਛਣਕਾਰ ਦੀ ਅਵਾਜ਼ ਪੈਂਦੀ ਸੀ, ਤੇਰੇ ਅੱਤ ਸੋਹਣੇ ਮੁਖੜੇ ਨੂੰ ਵੇਖ ਕੇ (ਮਾਂ ਜਸੋਧਾ) ਤੇਰੇ ਪਿਆਰ ਵਿਚ ਮਗਨ ਹੋ ਜਾਂਦੀ ਸੀ ।"},{"gurmukhi":"ਕਾਲਕਲਮਹੁਕਮੁਹਾਥਿਕਹਹੁਕਉਨੁਮੇਟਿਸਕੈਈਸੁਬੰਮ੍ਯੁਗ੍ਯਾਨੁਧ੍ਯਾਨੁਧਰਤਹੀਐਚਾਹਿਜੀਉ॥","meaning":"ਕਾਲ ਦੀ ਕਲਮ ਤੇ ਹੁਕਮ (ਗੁਰੂ ਦੇ ਹੀ) ਹੱਥ ਵਿਚ ਹਨ । ਦੱਸੋ, ਕਉਣ (ਗੁਰੂ ਦੇ ਹੁਕਮ ਨੂੰ) ਮਿਟਾ ਸਕਦਾ ਹੈ? ਸ਼ਿਵ ਤੇ ਬ੍ਰਹਮਾ (ਗੁਰੂ ਦੇ ਬਖ਼ਸ਼ੇ ਹੋਏ) ਗਿਆਨ ਤੇ ਧਿਆਨ ਨੂੰ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਧਾਰਨ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹਨ ।"},{"gurmukhi":"ਸਤਿਸਾਚੁਸ੍ਰੀਨਿਵਾਸੁਆਦਿਪੁਰਖੁਸਦਾਤੁਹੀਵਾਹਿਗੁਰੂਵਾਹਿਗੁਰੂਵਾਹਿਗੁਰੂਵਾਹਿਜੀਉ॥੧॥੬॥","meaning":"ਹੇ ਗੁਰੂ! ਤੂੰ ਅਚਰਜ ਹੈਂ, ਤੂੰ ਸਤਿ-ਸਰੂਪ ਹੈਂ, ਤੂੰ ਅਟੱਲ ਹੈਂ, ਤੂੰ ਹੀ ਲੱਛਮੀ ਟਿਕਾਣਾ ਹੈਂ, ਤੂੰ ਹੀ ਆਦਿ ਪੁਰਖੁ ਹੈਂ ਤੇ ਸਦਾ-ਥਿਰ ਹੈਂ ।੬।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (62, 'ਕਹਾਭਯੋਜੋਦੋਊਲੋਚਨਮੂੰਦਕੈਬੈਠਿਰਹਿਓਬਕਧਿਆਨਲਗਾਇਓ॥', '[{"gurmukhi":"","meaning":"ਕੀ ਹੋਇਆ ਜੇ ਕੋਈ ਦੋਵੇਾਂ ਅੱਖਾ ਬੰਦ ਕਰ ਕੇ ਬੈਠ ਗਿਆ ਅਤੇ ਬਗਲੇ ਵਾਗ ਧਿਆਨ ਲਗਾ ਲਿਆ;"},{"gurmukhi":"ਨ੍ਹਾਤਫਿਰਿਓਲੀਏਸਾਤਸਮੁਦ੍ਰਨਿਲੋਕਗਯੋਪਰਲੋਕਗਵਾਇਓ॥","meaning":"ਜੇ ਕੋਈ (ਉਮਰ ਭਰ) ਸੱਤ ਸਮੁੰਦਰਾ ਵਿਚ ਇਸ਼ਨਾਨ ਕਰਦਾ ਫਿਰਿਆ (ਤਾ ਇਹ ਸਮਝ ਲਿਆ ਜਾਵੇ ਕਿ) ਉਸ ਦਾ ਲੋਕ ਵੀ ਗਿਆ ਅਤੇ ਪਰਲੋਕ ਵੀ (ਉਸ ਨੇ) ਗੰਵਾ ਲਿਆ;"},{"gurmukhi":"ਬਾਸਕੀਓਬਿਖਿਆਨਸੋਂਬੈਠਕੈਐਸੇਹੀਐਸੇਸੁਬੈਸਬਿਤਾਇਓ॥","meaning":"ਬਾਨ-ਪ੍ਰਸਤੀ (ਬਿਖਿਆਨ-ਵੈਖਾਨਸ) ਹੋ ਕੇ ਜੰਗਲਾ ਵਿਚ ਨਿਵਾਸ ਕੀਤਾ, ਉਨ੍ਰਹਾ ਨੇ ਵੀ ਇਸ ਤਰ੍ਰਹਾ ਆਪਣੀ ਸਾਰੀ ਉਮਰ (ਵਿਅਰਥ ਵਿਚ) ਬਿਤਾ ਦਿੱਤੀ;"},{"gurmukhi":"ਸਾਚੁਕਹੋਂਸੁਨਲੇਹੁਸਭੈਜਿਨਪ੍ਰੇਮਕੀਓਤਿਨਹੀਪ੍ਰਭੁਪਾਇਓ॥੯॥੨੯॥","meaning":"(ਮੈਂ) ਸਚ ਕਹਿੰਦਾ ਹਾ, ਸਾਰੇ (ਧਿਆਨ ਨਾਲ) ਸੁਣ ਲਵੋ ਕਿ ਜਿੰਨ੍ਰਹਾ ਨੇ ਪਰਮਾਤਮਾ ਨਾਲ ਪ੍ਰੇਮ ਦਾ ਸੰਬੰਧ ਜੋੜਿਆ ਹੈ, ਉਨ੍ਰਹਾ ਨੇ ਹੀ ਉਸ ਨੂੰ ਪ੍ਰਾਪਤ ਕੀਤਾ ਹੈ ॥੯॥੨੯॥"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (63, 'ਰਾਗੁਕਲਿਆਨੁਮਹਲਾ੫ਘਰੁ੧', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਹਮਾਰੈਏਹਕਿਰਪਾਕੀਜੈ॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਮੇਰੇ ਉੱਤੇ ਇਹ ਮਿਹਰ ਕਰ ਕਿ (ਜਿਵੇਂ) ਭੌਰਾ ਫੁੱਲ ਦੇ ਰਸ ਨਾਲ ਰੀਝਿਆ ਰਹਿੰਦਾ ਹੈ,"},{"gurmukhi":"ਅਲਿਮਕਰੰਦਚਰਨਕਮਲਸਿਉਮਨੁਫੇਰਿਫੇਰਿਰੀਝੈ॥੧॥ਰਹਾਉ॥","meaning":"(ਤਿਵੇਂ ਮੇਰਾ ਮਨ) (ਤੇਰੇ) ਸੋਹਣੇ ਚਰਨਾਂ ਨਾਲ ਮੁੜ ਮੁੜ ਲਪਟਿਆ ਰਹੇ ।੧।ਰਹਾਉ।"},{"gurmukhi":"ਆਨਜਲਾਸਿਉਕਾਜੁਨਕਛੂਐਹਰਿਬੂੰਦਚਾਤ੍ਰਿਕਕਉਦੀਜੈ॥੧॥","meaning":"ਹੇ ਪ੍ਰਭੂ! (ਜਿਵੇਂ) ਪਪੀਹੇ ਨੂੰ (ਵਰਖਾ ਦੀ ਬੂੰਦ ਤੋਂ ਬਿਨਾ) ਹੋਰ ਪਾਣੀਆਂ ਨਾਲ ਕੋਈ ਗ਼ਰਜ਼ ਨਹੀਂ ਹੁੰਦੀ, ਤਿਵੇਂ ਮੈਨੂੰ ਪਪੀਹੇ ਨੂੰ (ਆਪਣੇ ਨਾਮ ਅੰਮ੍ਰਿਤ ਦੀ) ਬੂੰਦ ਦੇਹ ।੧।"},{"gurmukhi":"ਬਿਨੁਮਿਲਬੇਨਾਹੀਸੰਤੋਖਾਪੇਖਿਦਰਸਨੁਨਾਨਕੁਜੀਜੈ॥੨॥੧॥","meaning":"ਹੇ ਪ੍ਰਭੂ! ਤੇਰੇ ਮਿਲਾਪ ਤੋਂ ਬਿਨਾ (ਮੇਰੇ ਅੰਦਰ) ਠੰਢ ਨਹੀਂ ਪੈਂਦੀ, (ਮਿਹਰ ਕਰ; ਤੇਰਾ ਦਾਸ) ਨਾਨਕ (ਤੇਰਾ) ਦਰਸਨ ਕਰ ਕੇ ਆਤਮਕ ਜੀਵਨ ਹਾਸਲ ਕਰਦਾ ਰਹੇ ।੨।੧।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (64, 'ਪਉੜੀ॥', '[{"gurmukhi":"ਰੈਣਿਦਿਨਸੁਪਰਭਾਤਿਤੂਹੈਹੀਗਾਵਣਾ॥","meaning":"ਹਰੀ! ਰਾਤ ਦਿਨੇ ਅੰਮ੍ਰਿਤ ਵੇਲੇ (ਭਾਵ, ਹਰ ਵੇਲੇ) ਤੂੰ ਹੀ ਗਾਵਣ-ਜੋਗ ਹੈਂ"},{"gurmukhi":"ਜੀਅਜੰਤਸਰਬਤਨਾਉਤੇਰਾਧਿਆਵਣਾ॥","meaning":"ਸਾਰੇ ਜੀਵ ਜੰਤ ਤੇਰਾ ਹੀ ਨਾਮ ਸਿਮਰਦੇ ਹਨ"},{"gurmukhi":"ਤੂਦਾਤਾਦਾਤਾਰੁਤੇਰਾਦਿਤਾਖਾਵਣਾ॥","meaning":"ਦਾਤਾਂ ਦੇਣ ਵਾਲਾ ਦਾਤਾਰ ਹੈਂ ਤੇਰਾ ਹੀ ਦਿੱਤਾ ਹੋਇਆ ਖਾਂਦੇ ਹਨ"},{"gurmukhi":"ਭਗਤਜਨਾਕੈਸੰਗਿਪਾਪਗਵਾਵਣਾ॥","meaning":", ਤੇ ਭਗਤਾਂ ਦੀ ਸੰਗਤਿ ਵਿਚ ਆਪਣੇ ਪਾਪ ਦੂਰ ਕਰਦੇ ਹਨ"},{"gurmukhi":"ਜਨਨਾਨਕਸਦਬਲਿਹਾਰੈਬਲਿਬਲਿਜਾਵਣਾ॥੨੫॥","meaning":"। ਹੇ ਦਾਸ ਨਾਨਕ! (ਉਹਨਾਂ ਭਗਤ ਜਨਾਂ ਤੋਂ) ਸਦਾ ਸਦਕੇ ਹੋ, ਸਦਕੇ ਹੋ ।੨੫।"}]'::jsonb, 2);
insert into public.shabads (order_index, title, lines, deadline_days) values (65, 'ਧਨਾਸਰੀਮਹਲਾ੫ਘਰੁ੧੨', '[{"gurmukhi":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ॥","meaning":""},{"gurmukhi":"ਬੰਦਨਾਹਰਿਬੰਦਨਾਗੁਣਗਾਵਹੁਗੋਪਾਲਰਾਇ॥ਰਹਾਉ॥","meaning":"ਹੇ ਭਾਈ! ਪਰਮਾਤਮਾ ਨੂੰ ਸਦਾ ਨਮਸਕਾਰ ਕਰਿਆ ਕਰੋ, ਪ੍ਰਭੂ ਪਾਤਿਸ਼ਾਹ ਦੇ ਗੁਣ ਗਾਂਦੇ ਰਹੋ । ਰਹਾਉ।"},{"gurmukhi":"ਵਡੈਭਾਗਿਭੇਟੇਗੁਰਦੇਵਾ॥","meaning":"ਹੇ ਭਾਈ! ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਵੱਡੀ ਕਿਸਮਤ ਨਾਲ ਗੁਰੂ ਮਿਲ ਪੈਂਦਾ ਹ"},{"gurmukhi":"ਕੋਟਿਪਰਾਧਮਿਟੇਹਰਿਸੇਵਾ॥੧॥","meaning":"(ਗੁਰੂ ਦੀ ਰਾਹੀਂ) ਪਰਮਾਤਮਾ ਦੀ ਸੇਵਾ-ਭਗਤੀ ਕਰਨ ਨਾਲ ਉਸ ਦੇ ਕੋ੍ਰੜਾਂ ਪਾਪ ਮਿਟ ਜਾਂਦੇ ਹਨ ।੧।"},{"gurmukhi":"ਚਰਨਕਮਲਜਾਕਾਮਨੁਰਾਪੈ॥","meaning":"ਹੇ ਭਾਈ! ਜਿਸ ਮਨੁੱਖ ਦਾ ਮਨ ਪਰਮਾਤਮਾ ਦੇ ਸੋਹਣੇ ਚਰਨਾਂ (ਦੇ ਪ੍ਰੇਮ-ਰੰਗ) ਵਿਚ ਰੰਗਿਆ ਜਾਂਦਾ ਹੈ"},{"gurmukhi":"ਸੋਗਅਗਨਿਤਿਸੁਜਨਨਬਿਆਪੈ॥੨॥","meaning":"ਉਸ ਮਨੁੱਖ ਉਤੇ ਚਿੰਤਾ ਦੀ ਅੱਗ ਜ਼ੋਰ ਨਹੀਂ ਪਾ ਸਕਦੀ ।੨।"},{"gurmukhi":"ਸਾਗਰੁਤਰਿਆਸਾਧੂਸੰਗੇ॥","meaning":"ਗੁਰੂ ਦੀ ਸੰਗਤਿ ਵਿਚ (ਨਾਮ ਜਪਣ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ ਪਾਰ ਲੰਘ ਜਾਈਦਾ ਹੈ ।੩।"},{"gurmukhi":"ਨਿਰਭਉਨਾਮੁਜਪਹੁਹਰਿਰੰਗੇ॥੩॥","meaning":"ਹੇ ਭਾਈ! ਪ੍ਰੇਮ ਨਾਲ ਨਿਰਭਉ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਜਪਿਆ ਕਰੋ ।"},{"gurmukhi":"ਪਰਧਨਦੋਖਕਿਛੁਪਾਪਨਫੇੜੇ॥","meaning":"ਹੇ ਭਾਈ! (ਸਿਮਰਨ ਦਾ ਸਦਕਾ) ਪਰਾਏ ਧਨ (ਆਦਿਕ) ਦੇ ਕੋਈ ਐਬ ਪਾਪ ਮੰਦੇ ਕਰਮ ਨਹੀਂ ਹੁੰਦੇ"},{"gurmukhi":"ਜਮਜੰਦਾਰੁਨਆਵੈਨੇੜੇ॥੪॥","meaning":"ਭਿਆਨਕ ਜਮ ਭੀ ਨੇੜੇ ਨਹੀਂ ਢੁਕਦਾ (ਮੌਤ ਦਾ ਡਰ ਨਹੀਂ ਵਿਆਪਦਾ, ਆਤਮਕ ਮੌਤ ਨੇੜੇ ਨਹੀਂ ਆਉਂਦੀ) ।੪।"},{"gurmukhi":"ਤ੍ਰਿਸਨਾਅਗਨਿਪ੍ਰਭਿਆਪਿਬੁਝਾਈ॥","meaning":"ਹੇ ਭਾਈ! (ਜੇਹੜੇ ਮਨੁੱਖ ਪ੍ਰਭੂ ਦੇ ਗੁਣ ਗਾਂਦੇ ਹਨ) ਉਹਨਾਂ ਦੀ ਤ੍ਰਿਸ਼ਨਾ ਦੀ ਅੱਗ ਪ੍ਰਭੂ ਨੇ ਆਪ ਬੁਝਾ ਦਿੱਤੀ ਹੈ ।"},{"gurmukhi":"ਨਾਨਕਉਧਰੇਪ੍ਰਭਸਰਣਾਈ॥੫॥੧॥੫੫॥","meaning":"ਹੇ ਨਾਨਕ! ਪ੍ਰਭੂ ਦੀ ਸਰਨ ਪੈ ਕੇ (ਅਨੇਕਾਂ ਜੀਵ ਤ੍ਰਿਸ਼ਨਾ ਦੀ ਅੱਗ ਵਿਚੋਂ) ਬਚ ਨਿਕਲਦੇ ਹਨ ।੫।੧।੫੫।"}]'::jsonb, 2);

